/* 由 tools/extract_employee_handbook.py 从新员工上岗手册生成，请勿手工编辑。 */
window.EMPLOYEE_HANDBOOK = Object.freeze({"version":"2026-02-05","title":"新员工上岗手册","sourceTitle":"新员工上岗手册（20260205）","mediaBase":"assets/employee-handbook/","content":{"title":"新员工上岗手册","children":[{"title":"常见对私业务","children":[{"title":"2.账户管理","children":[{"title":"2.1个人信息（合并、开立、变更）","children":[{"title":"2.1.1开客户号","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、手机号实名认证；"},{"kind":"paragraph","text":"填写单据：《开户申请表(2025年版)》、《个人税收居民身份声明文件（2025年版）》(无纸化可免填单),"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image2.jpeg","image3.jpeg"]},{"kind":"paragraph","text":"图一 图二"},{"kind":"paragraph","text":"二.操作流程","images":["image4.jpeg"]},{"kind":"paragraph","text":"①查本人手机实名制；\n②查询黑名单（已删除无需查询）、福盾系统、银证通系统（已不需查询了）及案件查控平台、反诈风向标（查询结果记录在传票上），全部打印作传票。","shape":true},{"kind":"paragraph","text":"登录核心，联网核查后使用G04001/S001/8101100办理，E38011留存涉税声明影像。","shape":true},{"kind":"paragraph","text":"提示客户柜外清/回单签字，并打印无纸化追溯码，","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"证件号码和姓名录入规则"},{"kind":"table","rows":[["手工比对\n录入信息","证件类型","证件号码录入规则"],["手工比对\n录入信息","居民身份证","长度18位，由全部数字或数字加最末一位大写英文字符组成。符合公安部身份证号码校验规则"],["手工比对\n录入信息","外国人永久居留证","15位（国别码3位大写字母+ 12位数字）"],["手工比对\n录入信息","外国护照","只允许输入字母和数字。"],["手工比对\n录入信息","港澳居民来往内地通行证","第一个字母是H或者M，后面共8位数字。当首字母为“H”时国家/地区为“香港”，当首字母为“M”时国家/地区为“澳门”"],["手工比对\n录入信息","台湾居民来往内地通行证","7或8位数字"],["手工比对\n录入信息","中华人民共和国港澳、台湾居民居住证","长度18位，由全部数字组成。"],["手工比对\n录入信息","中国护照(需补充境外永久居留证号码)","护照号码栏位只允许输入字母和数字。\n补充证件号码栏位应录入个人境外永久居留证号码。"],["手工比对\n录入信息","外交官证","只允许输入字母和数字。"]]},{"kind":"paragraph","text":"备注：证件号码录入中，录入英文小写字母系统自动转换成大写字母；姓与名之间须用空格隔开。"},{"kind":"paragraph","text":"补充证件类型为户口簿的情况（未成年且无身份证客户开立客户号），主证件类型选择户口簿，证件号码输入户口簿户主页的户号（证件有效期从出生日期至满十六周岁之日），从证件类型选择身份证（证件有效期起始日为业务当天，有效期至次日，即有效期为一天）。"},{"kind":"paragraph","text":"如为Q2以及其他短期签证、免签客户开户所补充材料：护照签证复印件、短签外国人特别尽职调查问卷（通过反洗钱组件线上问卷，无需填写纸质问卷）、名单查询下载上传（百度查询仅涉及私行级客户），如客户反洗钱CRR评分大于3.1，则不适用于该简化流程，需特殊处理。"},{"kind":"paragraph","text":"针对居民身份证过期，提供临时身份证件需修改证件类型为临时身份证。"},{"kind":"paragraph","text":"1、反洗钱名单查询注意要点："},{"kind":"paragraph","text":"（1）、名单查询应包括客户中文名称（如有）、英文名称（中国人一般为拼音）（查询类别选择“名称”）；证件号码（查询类别选则“其他证件号”）"},{"kind":"paragraph","text":"（2）、查询中英文名称时勾选“负面信息、其他负面信息、其他负面信息”"},{"kind":"paragraph","text":"（3）、查询证件号码时需勾选“负面信息、其他负面信息、电诈涉案及惩戒名单、其他负面信息”。"},{"kind":"paragraph","text":"2、材料上传"},{"kind":"paragraph","text":"（1）护照、签证类的材料上传到反洗钱组件案例身份证明材料处；名单查询截图上传到反洗钱组件案例负面媒体清单处；开户申请书上传到其他材料，反洗钱组件案例上传到其他材料处（根据各行反洗钱条线要求调整是否上传材料）"},{"kind":"paragraph","text":"（2）上传的材料务必清晰，发现部分网点上传的材料不清晰：如客户证件复印很黑，无法清晰看到证件关键信息：客户证件号码、人脸等。"},{"kind":"paragraph","text":"尽职调查问卷由本行工作人员填写，禁止向客户展示。（已通过反洗钱组件线上完成，无需填写）"},{"kind":"paragraph","text":"","images":["image5.png","image6.png"]}]},{"title":"2.1.2合并客户号","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节","images":["image7.png"]},{"kind":"paragraph","text":"审核材料：客户有效身份证原件；"},{"kind":"paragraph","text":"填写单据：合并客户号申请书。"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"核心交易码：8101701","shape":true},{"kind":"paragraph","text":"提交集授中心要点：\n现有有效证件的联网核查截屏\n两个客户号G04002内容截屏\n合并客户号申请书拍照\n客户头像拍照\n注意事项：\n确定客户证件是否真实有效；\n申请书是否填写完整。","shape":true},{"kind":"paragraph","text":"如是身份证读取新证件识别，如是护照或通行证等非居民证件需手工录入证件信息","shape":true},{"kind":"paragraph","text":"使用通用查询，输入证件类型和证件号依次找到该客户的两个客户号","shape":true},{"kind":"paragraph","text":"","images":["image8.png"]},{"kind":"paragraph","text":"通过G04002确认客户号项下没有签约第三方存管等影响合并的外围","shape":true},{"kind":"paragraph","text":"使用8101701，选择客户是证件类型重复或名称重复，输入主从客户信息，点击提交集授中心","shape":true},{"kind":"paragraph","text":"注意：目前合并客户号是隔日生效！"},{"kind":"paragraph","text":"."}]},{"title":"2.1.3停用客户号","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户本人有效身份证原件；"},{"kind":"paragraph","text":"填写单据：个人信息综合服务变更表；"},{"kind":"paragraph","text":"填单图样：在其他变更栏位注明“停用客户号”。"},{"kind":"paragraph","text":"二.操作流程","images":["image9.png"]},{"kind":"paragraph","text":"联网核查","shape":true},{"kind":"paragraph","text":"G04002综合查询(截屏客户信息、账户信息、外围信息)","shape":true},{"kind":"paragraph","text":"8101200对私客户信息查询及维护一客户基本信息(修改前截图)—图示操作一提交授权","shape":true},{"kind":"paragraph","text":"操作环节注意事项：\n1.集中授权材料：联网核查截图、G04002客户资料截图、核心外围签约情况截图、改前截图、变更单、客户影像；\n2.注意客户名下的所有账户(包括借记卡、存折、信用卡等)均已注销，外围无签约关系才可停用客户号；\n3.外围解约步骤：G04002查询客户存在的外围关系一填写变更单(其他变更处注明外围关系十解约)—60700(选择解约—输入客户号或者卡号一选择外围关系)/60720(输入客户号或选择载体类型输入载体号码-选择外围业务产品点击删除)—提交远程授权—屏打；外围解约后若还有有效签约关系，可使用60454、60442将群组关系、关联关系修改为“不作用”；使用60662可以看到G04002看不到的一些签约关系，还有8101200多笔关系把代办关系解除。电子银行注销也可使用E20245个人客户联动注销直接打印注销传票。\n4、客户号停用原因正常选“06-反洗钱以外的其他原因”，并按实际情况备注具体停用原因。","shape":true},{"kind":"paragraph","text":"四.业务完结注意事项：复查8101200确保客户号已处于停用状态"}]},{"title":"2.1.4常见管控账户处理","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效证件原件、银行卡或存折等介质；"},{"kind":"paragraph","text":"填写单据：变更申请书或解除账户使用和功能限制申请表或提供涉诈审查表。"},{"kind":"paragraph","text":"二.操作流程","images":["image10.png"]},{"kind":"paragraph","text":"联网核查","shape":true},{"kind":"paragraph","text":"进入G04003/G04002和450核对账户资料和交易情况","shape":true},{"kind":"paragraph","text":"核心代码9079/7050进入交易界面","shape":true},{"kind":"paragraph","text":"","images":["image11.jpeg"]},{"kind":"paragraph","text":"回单打印签字","shape":true},{"kind":"paragraph","text":"操作环节注意事项：\n1.确定客户证件是否真实；\n2.申请书是否填写完整。\n3.9079解冻集中授权所需材料：联网核查、G04002客户资料截屏、450账户交易中显示该条冻结的截屏、客户影像（若是非现场解冻，则无需拍摄联网核查及客户影像）、解除账户使用和功能限制申请表或其他解冻文件。备注解冻原因。使用9079进行账户解冻如为有权机关冻结，需由有权机关提供解冻文书才可进行解冻。\n4.7050解除管控集中授权所需材料：联网核查、G04002客户资料截屏、7050修改前界面截屏、解除账户使用和功能限制申请表或其他证明文件、客户影像（若是非现场解冻，则无需拍摄联网核查及客户影像）。反欺诈备注栏位备注解除限制原因。\n5.对于7050管控解除，如涉及受害人标识，应在解除时明确注明。解除可疑标识时，不可仅填写“7050”，应注明“解除非柜面/可疑标识”。管控时，也须清晰注明具体管控措施。 因内部原因冻结后需解冻的，应写说明并经复核签字。说明内容需包括户名、账号及解冻原因。内部冻结时，应注明冻结方式。","shape":true},{"kind":"paragraph","text":"（最新7050页面）"},{"kind":"paragraph","text":"注：若客户为断卡涉案客户则只能根据notes转发的联席办解控清单进行解冻，“总对总”平台推送的名单只能通过“总对总”平台解除，柜员无权自行解冻账户，客户因反洗钱原因被报送可疑交易报告而被采取的管控措施，则要按要求向反洗钱中心提交放宽或不管控流程进行审批。"},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.本人申请办理；"},{"kind":"paragraph","text":"2.解除管控后根据客户需求进行账户限额；"},{"kind":"paragraph","text":"3.特殊情况请结合当地监管要求。"}]},{"title":"2.1.5智能柜台清机及空白卡作废","children":[],"blocks":[{"kind":"paragraph","text":"一.核心系统环节"},{"kind":"paragraph","text":"1.准备好清机需加重空实物；"},{"kind":"paragraph","text":"2.将重空调剂给智能柜台重空管理员，由智能柜台重空管理员和清机操作员进行清机加重空处理；（若由重空管理员使用29188领用的，无须调剂）（建议删除）"},{"kind":"paragraph","text":"3.若清机发现卡未成功开出，需进行空白卡作废。"},{"kind":"paragraph","text":"二.操作流程","images":["image12.jpeg","image13.jpeg","image14.jpeg"]},{"kind":"paragraph","text":"将需要加进智能柜台的重空调剂给智能柜台重空管理员（若由重空管理员使用29188领用的，无须调剂）（建议删除）","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图\n（高亮部分为需填写部分）\n29158\n29188\n29163","shape":true},{"kind":"paragraph","text":"智能柜台重空管理员和清机操作员清点实物无误后，系统执行29188","shape":true},{"kind":"paragraph","text":"智柜清机后将没开成功的空白卡先在智能柜台重空管理员的M端作废空白卡，然后在核心系统作29163作废，并填写《重要空白凭证状态变更申请表》、《福建省分行重要空白凭证销毁清单》做传票，并在监控下双人将空白卡剪角作废后复印卡跟传票，在智能柜台重空管理员的M端确认无在途重空","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.传票及时整理；"},{"kind":"paragraph","text":"2.重空实物转移注意清点数量，一定要保管好；（重空丢失，责任重大）"},{"kind":"paragraph","text":"3.空白卡作废后剪掉芯片复印跟传票，作废卡用信封装袋，并在信封上备注柜员号、日期、作废卡卡号、张数，随传票一同上缴。（废卡处理以各行规定为准）（该项操作无取消）"},{"kind":"paragraph","text":"4.注意：清机后回收的卡片，应先通过核心系统查询该卡是否写入客户信息:"},{"kind":"paragraph","text":"（1）若回收的卡片写入客户信息时,则需登记《智能柜台回收重空（吞没卡）登记簿》，并联系客户本人持有效证件前来领卡；"},{"kind":"paragraph","text":"（2）若回收的卡片未写入客户信息，则空白卡作废时，重空管理员应先至M端，核对借记卡实物是否与M端在途中的借记卡卡号一致，确认一致，则在M端先执行作废后，再至核心系统执行29163作废，并填写《重要空白凭证状态变更申请表》和《福建省分行重要空白凭证销毁清单》做附件，注意申请表中要素要填写正确，并由经办、复核、负责人签字确认。最后重空管理员再次查询M 端，确认在途是否已处理。"},{"kind":"paragraph","text":"重空管理员操作时因未在M端处理前，先在核心系统做了29163交易，则会导致M端重空在途显示“BL端单边作废”，需在M端：重空管理-特殊账务调整-BL端单边作废调整（写说明）处理。"}]}],"blocks":[]},{"title":"2.2储蓄卡业务","children":[{"title":"2.2.1开立账户","children":[],"blocks":[{"kind":"paragraph","text":"一．客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、手机号实名认证；"},{"kind":"paragraph","text":"填写单据：《开户申请表》、《个人税收居民身份声明文件》、及开通外围功能签约协议如《电子银行风险提示》、《短信通知协议》等（目前使用无纸化代码则无需填写以上单据）。尽调单以及告知书仍需正常填写，询问客户开户需求，如客户告知他有跨境收款业务须填写《个人跨境汇入汇款客户调查问卷》。"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image15.jpeg"]},{"kind":"paragraph","text":"图一 图二"},{"kind":"paragraph","text":"分别为客户本人开卡和代办人开卡样例"},{"kind":"paragraph","text":"客户环节注意事项：\n客户需提供最新有效的身份证件（客户证件种类要求见附件一至附件三）。若客户主证件有效期未满90天，原则上不予开户；\n客户若为代办则要求见第四点相关附件。\n开户申请书上的地址信息需按照我行个人信息录入规范填写，职业信息要求完整准确且长度不少于四个汉字字符；地址需精确到门牌号。\n客户涉税身份若为非仅中国税收居民时，应按要求填写涉税声明细项。还需在核心比对界面录入辅助证件信息，并扫描至辅助证件留存影像。","shape":true},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"识别客户情况，了解客户的开户意愿","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.确认客户开户意愿，做到开户十问，以及向客户进行开户风险提示；\n2.确认无误后登陆数展平台福盾系统和银证通系统（删除）进行风险查询，客户达到准入条件后予以开户；\n3.登陆核心系统，查询客户是否有客户号存在，若客户无客户号或名下有不可用客户号，可参考客户号开户开立业务以及客户号维护业务（代码8101100、8101200、8101301）；\n4.客户无客户号的情况下，使用G04001/S001,按照客户提供的信息创建客户号，并联动至开卡页面，读取芯片IC功能后，需要注意页面需拉至下方签约外围功能；\n5.核心签约外围功能时，ETOKEN和蓝牙KEY可直接申请绑定，无需远程集中授权，办理完后需查询电子工具绑定签约状况，绑定成功后需在核心系统办理前端收费；(现在认证工具暂时为免费）\n6.在签约完外围功能后，需在G04001/S001点击提交，防止漏打传票。若提交后打印失败可通过ctrl+shift+R重印；（目前无纸化无需打印传票，仅需打印追溯码）\n7.把卡/认证工具递交给客户之前，需主管人员比对业务回单，主管人员确认卡号与回单上一致时，同时注意认证工具是否绑定成功后，由主管人员将卡递交给办理人员。","shape":true},{"kind":"paragraph","text":"审核客户材料，银证通系统（已无需查询）银证通系统（删除）和福盾系统查询、CICP（案件查控平台）\n（如手机实名制等信息）","shape":true},{"kind":"paragraph","text":"登录核心系统，使用G04001/S001办理开户业务","shape":true},{"kind":"paragraph","text":"提示客户回单签字，主管复核双人递交卡片","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.卡片的工本费是否收取；（按卡种收费）"},{"kind":"paragraph","text":"2.开户之后的限额是否调整；"},{"kind":"paragraph","text":"3.8101931对客采集客户信息接收授权书"},{"kind":"paragraph","text":"4.提示客户回访电话及建立台账。（部分地区已取消）"},{"kind":"paragraph","text":"四.相关附件"},{"kind":"paragraph","text":"A.有效身份证件包括："},{"kind":"paragraph","text":"1.中国居民：居民身份证；未满16周岁，可使用居民身份证或户口簿。16-18周岁以内需使用身份证开户，如有收入证明，可独立开户，否则需监护人带好关系证明以及有效证件陪同开户。（同时，开立电子银行也需遵守相关要求）"},{"kind":"paragraph","text":"2.港澳居民：港澳居民往来内地通行证；中华人民共和国港澳居民居住证。"},{"kind":"paragraph","text":"3.台湾居民：台湾居民往来大陆通行证；中华人民共和国台湾居民居住证。"},{"kind":"paragraph","text":"4.定居国外的中国公民：中国护照+定居地永久居住证（如客户身份证件仍在有效期内，且联网核查有影像）。需在核心系统使用8101200添加从证件信息"},{"kind":"paragraph","text":"5.外国公民为护照或者外国人永久居留证。"},{"kind":"paragraph","text":"6.法律、行政法规规定的其他身份证明文件。"},{"kind":"paragraph","text":"B.辅助身份证明包括但不限于："},{"kind":"paragraph","text":"1.中国公民为户口簿、护照、机动车驾驶证、居住证、社保卡、出生证、军人和武装警察身份证件、公安机关出具的户籍证明、工作证。"},{"kind":"paragraph","text":"2.（军人、武警尚未领取居民身份证的，还应出具军人保障卡或所在单位开具的尚未领取居民身份证的证明材料。）"},{"kind":"paragraph","text":"3.港澳居民为香港、澳门身份证。"},{"kind":"paragraph","text":"4.台湾居民为在台湾居住的有效身份证明。"},{"kind":"paragraph","text":"5.定居国外的中国公民为定居国外的证明文件。"},{"kind":"paragraph","text":"6.外国公民为外国居民身份证、使领馆人员证件或机动车驾驶证等其他带有照片的身份证件。"},{"kind":"paragraph","text":"7.完税证明、水电煤缴费单等税费凭证。"},{"kind":"paragraph","text":"证件号码和姓名录入规则"},{"kind":"table","rows":[["手工比对\n录入信息","证件类型","证件号码录入规则"],["手工比对\n录入信息","居民身份证","长度18位，由全部数字或数字加最末一位大写英文字符组成。 符合公安部身份证号码校验规则"],["手工比对\n录入信息","外国人永久居留证","旧版15位（国别码3位大写字母+ 12位数字）\n新版18位（17位数字+1位校验位）也称五星卡"],["手工比对\n录入信息","外国护照","只允许输入字母和数字。"],["手工比对\n录入信息","港澳居民来往内地通行证","第一个字母是H或者M，后面共8位数字。当首字母为“H”时国家/地区为“香港”，当首字母为“M”时国家/地区为“澳门”"],["手工比对\n录入信息","台湾居民来往内地通行证","7或8位数字"],["手工比对\n录入信息","中华人民共和国港澳、台湾居民居住证","长度18位，由全部数字组成。"],["手工比对\n录入信息","中国护照(需补充境外永久居留证号码)","护照号码栏位只允许输入字母和数字。\n补充证件号码栏位应录入个人境外永久居留证号码。"],["手工比对\n录入信息","外交官证","只允许输入字母和数字。"]]},{"kind":"paragraph","text":"备注：证件号码录入中，录入英文小写字母系统自动转换成大写字母。"},{"kind":"paragraph","text":"委托代办：首先，请查询被代理人是否在我行留有客户号，如果有，则可继续以下流程（原则上不允许代办开立客户号）；"},{"kind":"paragraph","text":"开立储蓄户（活期/定期），可直接开户；"},{"kind":"paragraph","text":"开立结算户原则上不允许代办，如因特殊情况代办（注意：代办不能超过三人）注意：代办原则上不能超过三人（改），则需提供以下资料："},{"kind":"paragraph","text":"A.代理人与被代理人两人身份证件原件。"},{"kind":"paragraph","text":"B.合法的委托书：经相关公证机构公证的能够证明代理关系的公证书。"},{"kind":"paragraph","text":"C.无民事行为能力或限制民事行为能力的开户申请人，由法定代理人或人民法院、有关部门依法制定的人员代理办理。"},{"kind":"paragraph","text":"D.代办开卡时，柜员应选择“代办且不激活”，激活必须由本人办理。"},{"kind":"paragraph","text":"E.被代理人因特殊原因无法到场，可提供上门开户服务。"}]},{"title":"2.2.2未成年人开社保卡","children":[],"blocks":[{"kind":"paragraph","text":"一．客户环节"},{"kind":"paragraph","text":"（8114001集约发起手工比对与补录，拍摄有效证件材料，联动省行集授权，通过后存为比对附件，适用无法机读证件）"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、监护关系证明；"},{"kind":"paragraph","text":"填写单据：开户申请书、开户审核尽调核查表。"},{"kind":"paragraph","text":"注意事项：\n1.审核社保信息与客户信息是否一致；\n2.确保客户有参保信息以及公安局系统中有录入客户信息；\n3.审核社保信息与客户信息是否一致。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"社保系统核对社保人基本信息，联网核查；","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①1.代办人为监护人：户口本、代办人身份证、出生证明（户主非监护人本人）、结婚证等；2.代办人非监护人：监护关系证明、公证书等。\n②审核申请表需开户申请书中填写待办理由、申请人以及代办人信息填写完整。","shape":true},{"kind":"paragraph","text":"G04001/S001点击创建客户，录入客户信息；录入代办信息","shape":true},{"kind":"paragraph","text":"开户完成，提醒客户在新开账户中存钱；","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n③未成年人有居民身份证，只需联网核查代办人与未成年人有效身份证；未成年人无居民身份证，需通过代码E38011上传户口本影像，录入代办人信息远程授权所需材料（代办人身份证联网核查、代办人影像、关系证明）。\n④勾选需开卡的附件，录入代办人信息；将里面的客户信息填写完整；点击刷卡，将要开立的卡插入，输入金额、开户用途；点击提交，打印回单，客户签字确认。","shape":true},{"kind":"paragraph","text":"根据客户设置合理限额；","shape":true},{"kind":"paragraph","text":"社保系统录入参保信息，核对社保信息与客户信息一致。","shape":true},{"kind":"paragraph","text":"业务完结注意事项"},{"kind":"paragraph","text":"1.社保卡领卡后查询制卡信息是否完整；"},{"kind":"paragraph","text":"2.开户后做好台账登记，按时回访；"},{"kind":"paragraph","text":"3.监护关系证明请注意未成年客户与监护人提供的户口簿做证明时，是否与监护人是户主与子女之间的关系，如若户主是祖父母或外祖父母等（其中，出生证明须配合户口簿作为辅助材料，但不可单独使用），户口簿中有其他亲属的，则要提供另外有效的监护关系证明；"},{"kind":"paragraph","text":"4.开卡完成后打印出来的回单柜员要做传票。"},{"kind":"paragraph","text":"5.资料留存：TY05第一联，代办证明材料复印件、开户申请书。"}]},{"title":"2.2.3借记卡限额8003323、37232、8114003","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件，银行卡；"},{"kind":"paragraph","text":"填写单据：开户申请书（新开户）、个人综合服务变更申请书（存量）。尽调表，承诺书"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image16.png","image17.png"]},{"kind":"paragraph","text":"图一（新开） 图二（存量）"},{"kind":"paragraph","text":"二、处理流程(8114003集约平台处理流程）。如集约平台无法处理（如非居、高龄、高风险等），则使用37232进行限额"},{"kind":"paragraph","text":"1、8114003发起，添加客户证件附件，成功后进行人脸识别，如人脸识别未通过或未进行，后续提交业务时须进行现场核准。"},{"kind":"paragraph","text":"2、根据客户诉求和实际情况，填写“客户调额期望值，并勾选需要调额的借记卡（仅允许单选）。点击“限额试算”按钮，初次试算结果回显在底部，前台人员与客户沟通确认初步限额，如“修改限额”栏位额度小于或等于“初次试算结果”，可直接提交业务。"},{"kind":"paragraph","text":"3、如初步额度无法满足客户诉求，网点需进一步与客户沟通，要求提供符合我行相关要求的证明材料。点击“补充资料”栏位的“附件”按钮，上传证明材料，并拖拽入相应分类。系统将业务流转至中心进行作业处理，状态为“处理中”。中心端处理完成后，业务将流转至待处理队列，网点经办可通过右下角“集中作业通讯栏”快速查询。点击待处理信息进入列表，选中相应记录，界面将回显根据交易集约规则库计算的“调整试算结果”网点依据调整试算结果再次与客户沟通确认限额，如“修改限额”栏位额度小于或等于“调整试算结果”，可直接提交业务。"},{"kind":"paragraph","text":"4.如业务被退回，系统显示退回原因，点击“附件”可补录影像，提交后将重新推送至运营中心审核"},{"kind":"paragraph","text":"5.如仍未满足客户预期，可按分行现有规则和流程协商，合理确定限额，提交业务时须进行现场核准"},{"kind":"paragraph","text":"二.业务完结注意事项"},{"kind":"paragraph","text":"1.客户如为新开卡维护限额，维护限额后应复核人员签字并递交卡片。"},{"kind":"paragraph","text":"2.如遇集约退件，应及时向复核人员反馈。"}]},{"title":"2.2.4销户、销卡","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、销户/销卡的介质；"},{"kind":"paragraph","text":"填写单据：销户/销卡的申请书、或变更单等。"},{"kind":"paragraph","text":"注意事项：\n1.销卡之前查询卡状态是否正常，外围产品是否已赎回及解约\n2.虚拟卡应提供能体现卡种类的账户资料（打印卡详细，体现卡片类型）","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"操作流程注意事项：\n①变更申请表，备注销卡、卡号。\n②通过G04002查看客户外围产品若存在IPDP默认资金账户，三方存管等，则应先通过C01060或60700将此功能进行解约，填写变更单。\n③步骤：C01040→理财投资协议（签署状态）→解约→提交（无需远程授权） 60700→选择对应解约项目→提交远程授权。\n60700→选择对应解约项目→提交远程授权。\n④实体卡：G04003→选择需要销户的银行卡→（联动）销卡界面→（拉至底部）按顺序选择对应功能进行解约→待所有功能皆解约完毕后点击提交→（联动）进入下一界面，选择现金结清或转账结清→提交→打印回单→客户签字确认。\n电子卡：客户销电子卡若客户记得密码则与销实体卡一致，若忘记密码则需先通过8003303进行密码重置。填写变更单于备注栏位填写电子虚拟卡密码重置，8003303手动输入卡号，点击密码重置，提交远程授权，→提交→打印回单→签字完成后继续通过G04003进行销卡，步骤、核准点同上。","shape":true},{"kind":"paragraph","text":"审核客户材料（身份证、介质、变更单等）①","shape":true},{"kind":"paragraph","text":"通过G04002查看客户所需要销的卡的外围产品开通情况②","shape":true},{"kind":"paragraph","text":"C01060或60700将部分无法通过销卡交易码自动完成解约的功能先解约③","shape":true},{"kind":"paragraph","text":"G04003完成后续销卡（两种情况实体卡、虚拟卡）④","shape":true},{"kind":"paragraph","text":"旧卡当客户面剪角作废（客户需要留旧卡的需要客户写明用途确认）","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.销卡销户回单张数较多，请确认回单是否打印完整；"},{"kind":"paragraph","text":"2.旧卡剪角后复印做传票。（若复印件卡号不清晰，须在复印件上手写卡号。）"},{"kind":"paragraph","text":"3.注意查看销户单据中是否有尾零结清及IC卡销户圈提记录，须将有关余额支付给客户，防止出现长款情况。"},{"kind":"paragraph","text":"4.如存在中银E贷签约销户解约——点中进去——点击跳转——清空卡号——提交，即可解约。）"}]},{"title":"2.2.5挂失与撤销挂失","children":[{"title":"2.2.5.1挂失G04006/S00001/8003309","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件；①"},{"kind":"paragraph","text":"填写单据：挂失申请书。②"},{"kind":"paragraph","text":"注意事项：卡密/折密同挂、余额超10万需挂失七天后解挂（卡密共挂是否提供第二证件（无需提供），其中特殊情况需当日解挂的应由个数部审签《零售柜面业务特殊审批表〉。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"操作流程注意事项：\n①业务办理前需核实客户情况、业务情况，核对客户信息并及时更新。办理业务前挂失单据需经办复核双签方能办理。办理业务前还需确认是否存在ATM转账圈存或冻结的情况。以免产生单边账，又无法进行强制扣划，引起不必要的麻烦和纠纷。\n②确认客户业务能否当天完结具体情况详见附件二；同时准备好远程授权所需的相关截图；业务能当日完结的界面需选择挂失、核实、销卡；无法完结的仅选择挂失、核实。","shape":true},{"kind":"paragraph","text":"识别客户情况①","shape":true},{"kind":"paragraph","text":"通过G04006/S00001/8003309进行挂失核实交易②","shape":true},{"kind":"paragraph","text":"判定是否能当日销卡，能当日销卡的联动G04003销卡③，无法当日销卡的待后续客户再次前来时销卡④。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n③销卡易出现无法通过综合销户进行一次性处理的情况，需通过外围系统分布处理可先行准备远程授权所需图片，外围系统操作详见详见附件二。\n④应无法当日销卡，挂失核实后需告知客户保留好业务回单、何时能办理销卡，具体时间详见附件三。\n⑤综合交易完成需单独点击提交进行打印否则将照成传票缺失。","shape":true},{"kind":"paragraph","text":"提交打印并签字⑤","shape":true}]},{"title":"2.2.5.2撤销挂失8003310","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、卡、在柜台办理时原《挂失申请书》"},{"kind":"paragraph","text":"交易码界面："},{"kind":"paragraph","text":"","images":["image18.png"]},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"联网核查、G04002、8003001查询并打印挂失登记簿并让客户签字确认","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①撤销卡临时挂失（需提供卡片）\n客户可在临时挂失期限内自行申请撤销卡临时挂失。解除临时挂失时，交易成功后由系统将其电子登记簿的“记录状态”置为“3-已解除”。\n②撤销卡正式挂失\n是指借记卡办理卡正式挂失后，客户可到省内联网网点柜台办理撤销卡正式挂失。撤销挂失时要求必须刷卡并验证卡密码的正确性，撤销成功后，由系统将其电子登记簿的“记录状态”置为“3-已解除”。\n③撤销卡密码挂失\n需到原挂失机构柜台办理撤销卡密码挂失。交易完成后，系统自动更新挂失业务电子登记簿。\n④撤销卡与密码同时挂失\n需到原挂失机构柜台办理撤销卡与密码同时挂失。交易完成后，系统自动更新挂失业务电子登记簿。\n⑤无论电子登记簿的“记录状态”处于“待核实”还是“己核实”，均允许撤销挂失。","shape":true},{"kind":"paragraph","text":"打印传票客户签字","shape":true},{"kind":"paragraph","text":"9082 解冻/9079冻结查询（若客户有挂失冻结），输入相应要素，加上450，提交远程授权，成功后打印TY04传票，交由客户签名后收回。","shape":true},{"kind":"paragraph","text":"三.相关附件"},{"kind":"paragraph","text":"附件一："},{"kind":"paragraph","text":"1.如遇账户持有人死亡的，需提供死亡证明、遗产继承证明材料，由遗产继承人前来办理挂失解除挂失一系列业务（符合小额遗产继承的按小额继承流程办理，即账户人在我行总资产小于等于5万元，提供死亡证明，直系亲属证明可直接办理）。"},{"kind":"paragraph","text":"2.公证委托书，由公证书中的受托人办理。"},{"kind":"paragraph","text":"3.客户因身患重病、行动不便等原因无法前来网点，可提供上门延伸服务，通过上门见证授权委托后，代理人前来网点办理挂失解挂。延伸服务客户分为意识清醒和意识不清醒，若客户意识清醒可直接代办挂失销户全流程，若意识不清醒则销户资金仅可进入医院账户。"},{"kind":"paragraph","text":"附件二："},{"kind":"paragraph","text":"若出现无法使用G04003取消的外围关系，则可通过60720查询确认外围关系，常见的外围关系处理方法如下："},{"kind":"paragraph","text":"一、外围联动注销电子银行（E20245）"},{"kind":"paragraph","text":"因部分借记卡除了活期主账户有签约电子银行外，卡下定期账户也关联了电子银行，因此建议都用E20245一步注销电子银行，该交易可同时注销主账户和关联账户。若客户存在其他不需要注销的账户关联电子银行则不建议使用该交易码。"},{"kind":"paragraph","text":"二、外围注销电话银行（E07002）"},{"kind":"paragraph","text":"1.选择“解约介质”（客户号/证件类型/交易卡号账号）后提交；"},{"kind":"paragraph","text":"2.选择相应的账户，选择“解约方式”（0-验密解约/授权解约）。"},{"kind":"paragraph","text":"※授权解约：无需输入密码，需远程授权。"},{"kind":"paragraph","text":"特别提示：对于有电话银行的客户销户前需向客户确认其是否有B股账户，是否确定销户。"},{"kind":"paragraph","text":"三、外围转移三方存管、银期转账、储蓄国债、IPDP默认账户均可使用G04004进行转移。"},{"kind":"paragraph","text":"特别提示："},{"kind":"paragraph","text":"1.其中三方存管、银期转账需在证券交易时间进行。"},{"kind":"paragraph","text":"2.IPDP转移后原销卡账户所购买的基金代销、理财无法入新卡账户将产生无头资金。"},{"kind":"paragraph","text":"四、客户预留短信通知号码为旧手机号时，无介质解除短信通知功能。"},{"kind":"paragraph","text":"先通过8101911综合变更手机号为新手机号（建议迁移至智能柜台办理），更新完毕后，客户再回柜台办理后续业务，回复短信解约。如系统提示有短信欠费，需客户补缴后取消短信功能。"},{"kind":"paragraph","text":"五、大额存单可通过G06008交易进行对应卡号变更。"},{"kind":"paragraph","text":"六、若出现无法解除的外围关系可使用60720进行逐一解除。"},{"kind":"paragraph","text":"注意事项："},{"kind":"paragraph","text":"1.电子IC卡注销通过E40129交易实现，需注意是否存在圈存的现金。"},{"kind":"paragraph","text":"2.信用卡自动还款可至信用卡综合外围将还款账户更换或至空值，需提醒客户信用卡已取消自动还款。"},{"kind":"paragraph","text":"3.国债功能优先使用转移而不是注销。"},{"kind":"paragraph","text":"附件三："},{"kind":"paragraph","text":"1.金额超过10万。"},{"kind":"paragraph","text":"密码遗忘，两项其中一种情况或两种皆有则需7天后销卡，使用临时身份证件挂失的需使用正式身份证进行销卡"}]}],"blocks":[]},{"title":"2.2.6换预制卡","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、旧卡"},{"kind":"paragraph","text":"填写单据：变更申请书，持卡换卡可免填申请书、尽调表。"},{"kind":"paragraph","text":"申请书填写图样："},{"kind":"paragraph","text":"","images":["image19.png"]},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"联网核查客户身份证","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n客户密码忘记且账户金额<10万的情况下需进行集中授权\n所需材料：\n身份证联网截图\n卡资料打印截图\n410账户余额打出并给客户签名\n旧卡照片\n客户头像\n身份证原件拍照","shape":true},{"kind":"paragraph","text":"8103315,G04012个人换预制卡","shape":true},{"kind":"paragraph","text":"旧卡可刷卡也可输入卡号，新卡直接插卡识别，然后进行换卡","shape":true},{"kind":"paragraph","text":"提示客户回单签字","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.换卡前先查询卡账户是否正常；"},{"kind":"paragraph","text":"2.若客户账户余额大于10万人民币需进行密码挂失，七天后进行密码重置换卡；"},{"kind":"paragraph","text":"3.客户旧卡记得剪角后复印跟传票；"},{"kind":"paragraph","text":"4.若金额小于10万人民币可以提示客户移步至智能柜台改密码。"},{"kind":"paragraph","text":"5.客户若忘记卡密码可尝试通过手机银行重置密码后再做其他业务。"}]},{"title":"2.2.7领非预制卡","children":[],"blocks":[{"kind":"paragraph","text":"客户环节注意事项：\n1.领卡单需要回收(若遗失，需要在回单上写遗失声明并让客户签名）。\n2.持卡换卡领非预制卡G04002卡片状态为“卡重发”，卡挂失领非预制卡G04002卡片状态为“卡挂失/卡密同挂”。\n3.若客户为线上换卡，则打印8003011借记卡非金融交易流水查询或通过手机银行及95566短信查换卡记录。\n4.客户通过手机银行进行持卡换卡交易，但领卡时旧卡丢失的需用G04006补做卡挂失后再进行领卡，卡挂失手续费根据客户层级及借记卡卡种进行收取。\n5.客户通过手机银行进行卡挂失补卡，在柜面通过8003001执行卡挂失确认后，再进行领卡交易。","shape":true},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"1.“持卡换卡”领非预制卡："},{"kind":"paragraph","text":"①客户本人持有效身份证件"},{"kind":"paragraph","text":"②领卡单"},{"kind":"paragraph","text":"③旧卡"},{"kind":"paragraph","text":"2.“卡挂失”领非预制卡："},{"kind":"paragraph","text":"①客户本人持有效身份证件"},{"kind":"paragraph","text":"②领卡单（挂失申请书客户回单联）"},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"1.持卡换卡领非预制卡："},{"kind":"paragraph","text":"输入代码G04013","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.知道密码：输入密码，回收标志选否，强制领卡标识选择正常领卡，客户信息确认后直接提交。\n2.忘记密码：回收标志选否，强制领卡标识选择正常领卡，客户信息确认，回单打印签字，提交集中授权，授权通过后，回单打印签字，联动提交，8003303密码重置连续授权。\n3.集中授权所需材料：\n①第一次集中授权所需材料：联网核查截屏、G04002卡资料截屏、410余额查询打印并让客户签字、客户头像、领卡单、新卡，旧卡。）\n②8003303连续授权需增加材料：客户领卡签字回单\n4.持卡换卡需要回收旧卡，剪角后复印跟账。","shape":true},{"kind":"paragraph","text":"系统录入","shape":true},{"kind":"paragraph","text":"客户信息确认、回单签字","shape":true},{"kind":"paragraph","text":"整理传票","shape":true},{"kind":"paragraph","text":"2.卡挂失领非预制卡："},{"kind":"paragraph","text":"8003001复制挂失编号\n并打印让客户签字\n（客户提供回单联并确认挂失编号）","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.知道密码：输入密码，回收标志选否，强制领卡标识选择正常领卡，客户信息确认后回单打印签字，再次提交后录入挂失编号再提交即可。\n2.忘记密码：回收标志选否，强制领卡标识选择正常领卡，客户信息确认，回单打印签字，提交集中授权，授权通过后，录入挂失编号，回单打印签字。8003303密码重置，录入挂失编号并设置新密码，连续授权。","shape":true},{"kind":"paragraph","text":"输入G04013","shape":true},{"kind":"paragraph","text":"系统录入","shape":true},{"kind":"paragraph","text":"客户信息确认、回单签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n3.集中授权所需材料：\n①第一次集中授权所需材料：联网核查截屏、8003001截屏、打印回单并让客户签名、G04002卡资料截屏、410余额查询打印并让客户签字、客户头像、领卡单、新卡。\n②8003303连续授权需增加材料：客户领卡签字回单。","shape":true},{"kind":"paragraph","text":"整理传票","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.持卡换卡需要回收旧卡，剪角后复印跟传票；"},{"kind":"paragraph","text":"2.领卡单原件需要回收(若遗失，需要在回单上写遗失声明并让客户签名），线上申请除外；"},{"kind":"paragraph","text":"3.卡挂失领非预制卡，通过8003001可查看挂失渠道，若为柜台挂失则需找出客户的挂失单，如为智能柜台挂失则凭借领卡单即可；"},{"kind":"paragraph","text":"4.此业务需联网核查及本人办理，若为代办需公证委托。"}]},{"title":"2.2.8对账簿补换发","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、对账簿对应的银行卡。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"身份证联网核查","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.确认身份证有效期、是否为客户本人；\n2.新凭证类型为对账簿，输入新凭证号码，签发原因选破损换发，录入旧凭证类型和号码，支取方式为无要求；\n3.提交打印新对账簿，复印新折扉页并让客户签字，新折交客户，注意复印的扉页随传票。\n4. 原则上客户持本人身份证件及借记卡办理。如需代办，需持代办人、客户本人双方身份证件及借记卡，网点进行身份核实，刷卡验密通过后即可办理）","shape":true},{"kind":"paragraph","text":"输入代码490查询旧凭证类型、复制旧凭证号码并截图打印（备注旧凭证丢失原因）","shape":true},{"kind":"paragraph","text":"输入代码500录入信息，做破损换发","shape":true},{"kind":"paragraph","text":"客户签字、传票","shape":true}]},{"title":"2.2.9存折、存单密码升级","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件；"},{"kind":"paragraph","text":"填写单据：个人变更申请书。"},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"登录核心，联网核查后使用29190办理","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.本人办理\n2.核对录入信息是否正确","shape":true},{"kind":"paragraph","text":"屏幕打印后客户签字","shape":true}]},{"title":"2.2.10领ATM吞没卡","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件"},{"kind":"paragraph","text":"注意事项：\n1.如吞没卡为他行借记卡须提供他行详细资料证明或卡面拼音或卡背面签字；\n2.注意需要客户本人领取。（因特殊情况，允许代办领吞没卡，视各行具体要求处理）\n）","shape":true},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"E79001查询领入吞没卡","shape":true},{"kind":"paragraph","text":"联网核查后，E79002领取吞没卡，提示客户在回单和吞没卡登记簿上签字。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.注意ATM后交接吞没卡时需填写ATM吞没卡移交清单；"},{"kind":"paragraph","text":"2.如情况紧急或客户领卡时暂无吞没卡接收数据，需填写ATM紧急取卡单。"},{"kind":"paragraph","text":"3、他行卡优先选择凭验密领取。"}]},{"title":"2.2.11历史交易查询E17008（交易码更新为8014001）","children":[],"blocks":[{"kind":"paragraph","text":"一．客户环节"},{"kind":"paragraph","text":"审核材料：客户本人有效身份证原件及复印件；"},{"kind":"paragraph","text":"填写单据：客户存款历史交易查询申请书"},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"1.通过数据展示平台查询（外省账户无法查询）"},{"kind":"paragraph","text":"2011年4月5日之前（无交易对手）；"},{"kind":"paragraph","text":"2011年4月5日之后（有交易对手）。需提前和客户说明。"},{"kind":"paragraph","text":"2.通过核心系统查询： E17008历史交易查询（可查外省账户）"},{"kind":"paragraph","text":"可查询区间：开户至今；一次仅可查询半年。"},{"kind":"paragraph","text":"3.8014001支持一次性打印近10年交易流水（包括：活期、定期、借记卡（含已销户/销卡）。"},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.数据展示平台查询仅支持客户本人申请查询或公检法机关查询；"},{"kind":"paragraph","text":"2.交易流水仅支持本人查询，不可代办；"},{"kind":"paragraph","text":"3.已故存款人账户，仅支持继承人查询其死亡之后的交易流水，不支持查询已故人生前流水。（新规是还可查询死亡前6个月的流水，请以最新文件规定为准）"},{"kind":"paragraph","text":"4.登记查询登记簿。"}]},{"title":"2.2.12小额继承（附加文件）","children":[],"blocks":[{"kind":"paragraph","text":"一．客户环节"},{"kind":"paragraph","text":"审核材料：办理人身份证原件、直系亲属关系证明材料（户口本、结婚证等）或公证遗嘱、账户人死亡证明原件或账户人火化证原件或者账户人身份证户口本注销证明原件等；"},{"kind":"paragraph","text":"填写单据：小额继承提取承诺书（签字盖手印）、仅查询账户情况还需填写已故存款人存款情况查询申请书"},{"kind":"paragraph","text":"注意事项：\n小额继承免公证的只能为已故存款人的配偶、子女、父母，其余需公证遗嘱的受益人才能查询取款。\n经办机构受理已故存款人亲属存款查询业务后，应凭死亡证明更新已故存款人客户号状态为“死亡”，对相关账户采取只收不付冻结措施，冻结原因为“客户身故，暂时中止账户服务”。","shape":true},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"1.查询"},{"kind":"paragraph","text":"识别客户情况，审核客户材料","shape":true},{"kind":"paragraph","text":"填写小额继承提取查询承诺书及已故存款人存款情况查询申请书","shape":true},{"kind":"paragraph","text":"登录核心系统，联网核查留存查询人信息，使用G04002/410/CIF客户查询交易，查询并打印余额给客户","shape":true},{"kind":"paragraph","text":"复印客户原件材料，跟随传票上缴","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.存款人已故，已故存款人的第一顺序继承人在提取已故存款人存款时，基于合法、正当理由申请查询已故存款人账户交易明细的，银行业金融机构应当应申请人要求，提供已故存款人死亡后以及死亡前6个月内的账户交易明细。已故存款人生前另有安排的除外。金规[2024]6号”（从2024年6月1日起实施）；\n2.经办机构受理已故存款人亲属存款查询业务后，应凭死亡证明更新已故存款人客户号状态为“死亡”。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.小额继承提取业务，是指已故存款人在同一法人银行业金融机构的账户余额合计不超过5万元人民币（或等值外币，不含未结利息），承诺书上“注明行内账户合计余额XXX元”（该话术修改为：已故存款人行内账户合计余额（含非存款类金融产品本金及收益）XX元）。经办复核双签确认。（存款查询情况告知书为列明存款金额。丧葬费、抚恤金不计入规定的账户限额。填写完总额后额外注明）（新增）\n2.提取申请人同意一次性提取已故存款人存款及利息，并在提取后注销已故存款人账户和停用客户号\n3.对于已故存款人凭证或者密码遗失、凭证与密码均遗失的，符合支取条件且提取申请人确定提取的，无需再进行凭证或密码挂失，可通过相关扣划交易直接处理（须经过授权），并在备注栏注明扣划原因“小额遗产继承划款”。\n4.已故存款人小额存款全部提取并销户后，应停用客户号。如因有在途业务而暂时无法销户的，应更新已故存款人客户号状态为“死亡”，死亡证明或法院宣告死亡判决书作为业务办理依据。","shape":true},{"kind":"paragraph","text":"2.继承提取"},{"kind":"paragraph","text":"识别客户情况，审核客户材料","shape":true},{"kind":"paragraph","text":"填写小额继承提取查询承诺书","shape":true},{"kind":"paragraph","text":"登录核心系统，联网核查留存查询人信息，然后进行取款转账销户交易","shape":true},{"kind":"paragraph","text":"全部销户后需停用客户号","shape":true},{"kind":"paragraph","text":"复印客户原件材料，跟随传票上缴","shape":true},{"kind":"paragraph","text":"三．相关文件"},{"kind":"paragraph","text":"闽中银个【2022】44号"},{"kind":"paragraph","text":"关于进一步明确简化提取已故存款人小额存款等业务要求的通知"},{"kind":"paragraph","text":"简化提取已故存款人小额存款常见问题的回答（2023年2月版）"},{"kind":"paragraph","text":"关于简化提取已故存款人小额存款相关事宜的通知（银保监办发【2021】18号）"},{"kind":"paragraph","text":"国家金融监督管理总局 中国人民银行关于优化已故存款人小额存款提取有关要求的通知金规〔2024〕6号"},{"kind":"paragraph","text":"中银发〔2023〕676号-中国银行关于发送个人人民币及外币存款业务相关规章制度和协议文本的通知"}]}],"blocks":[]},{"title":"2.3信用卡业务","children":[{"title":"2.3.1信用卡强制扣划并冻结","children":[],"blocks":[{"kind":"paragraph","text":"一．客户环节"},{"kind":"paragraph","text":"审核材料：审核客户经理提供的特殊业务审批表内容是否正确"},{"kind":"paragraph","text":"填写单据：9991凭证借贷联"},{"kind":"paragraph","text":"填单图样：","images":["image20.png"]},{"kind":"paragraph","text":"客户环节注意事项：\n①审核客户经理提供的审批表中的金额、姓名、账号、信用卡卡号是否正确；\n②填写9991凭证，包含本网点信用卡BGL，扣划金额，对账金额，交易代码，备注，笔数和扣划总金额。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"审核审批表并确认①","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①通过G04002查看该客户的信用卡卡号、扣划账号和金额，并截屏该界面。通过9079查看扣划账号是否冻结。\nA.冻结状态\na.被有权机关冻结，直接进行9081操作，业务完结。\nb.其他冻结，先进行60996进行维护，维护在本机构项下，本地授权，再进行9082解冻。\nB.未冻结状态，直接进行下一步操作。\n②核心操作21031进行强制扣划，录入以下内容后，提交进行省行集中授权。\nA.扣划账号\nB.扣划金额\nC.凭证类型：其他\nD.凭证号码：0\nE.支取方式：9强制扣划\nF.转入账号：本网点的信用卡BGL\nG.备注（信用卡逾期扣划）\n集中授权需要提交的材料：账号快捷查询、审批表、9991凭证。\n③8004006手动输入信用卡卡号，选择转账（须选择转账）后，输入扣划金额，提交。","shape":true},{"kind":"paragraph","text":"通过21031进行强制扣划②","shape":true},{"kind":"paragraph","text":"通8004006进行转账③","shape":true},{"kind":"paragraph","text":"通过9081进行账户冻结④","shape":true},{"kind":"paragraph","text":"通过23310进行追踪号补录⑤","shape":true},{"kind":"paragraph","text":"在第①步如有进行60996维护，应在上述步骤完成后，进行60998维护","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n④账户9081进行冻结（录入账号，冻结类型选择其他，备注信用卡逾期冻结），提交后连续授权。\n⑤操作23310进行补录追踪（20450、23350和23320截屏），连续授权即可，业务完结。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.账户如有冻结，可解冻的情况下，一定要先进行60996维护在本网点项下后再进行解冻。业务完结后，记得再通过60998解除该维护；"},{"kind":"paragraph","text":"2.在进行8004006操作时，要认真核对信用卡户名，核心必须点击转账进行操作；在业务完结后，通过20450/20490/20400查询本网点信用卡BGL是否为0；"},{"kind":"paragraph","text":"3.业务完成后追踪号一定要记得追平。"},{"kind":"notice","text":"备注：目前系统已实现自动扣划，无冻结、无余额的情况下进行核呆冻结。"}]},{"title":"2.3.2信用卡核查还款","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"客户信用卡欠款需还款，客户前来柜台发起还款申请。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"操作流程注意事项：\n①识别客户是否代办、业务金额是否需要进行联网核查。\n②手动输入卡号需核实卡号的正确性和真实性。\n③现金存入需做好现金清点工作。","shape":true},{"kind":"paragraph","text":"识别客户情况①","shape":true},{"kind":"paragraph","text":"执行8004006存入","shape":true},{"kind":"paragraph","text":"读取介质或手动输入卡号②","shape":true},{"kind":"paragraph","text":"选择现金存入③\n或转账存入","shape":true},{"kind":"paragraph","text":"提交打印并签字","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.金额大于等于5万元需要客户身份证件进行联网核查；"},{"kind":"paragraph","text":"2.非必要不选择转账存入方式，转账存入需要提前将现金通过21031转入BGL9991003账户，再使用8004006进行转账还款。"},{"kind":"paragraph","text":"备注：非现金业务，目前系统已实现柜台借记卡、存折和信用卡互转交易8005001行内汇款交易完成转账业务，无需通过BGL账户过渡。"}]},{"title":"2.3.3信用卡呆账还款","children":[],"blocks":[{"kind":"paragraph","text":"客户环节注意事项：\n①若客户为核呆还款，需提前与个金条线及他行联系进行沟通是否为新线挂账直接通过现金还款方式进行。","shape":true},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件；"},{"kind":"paragraph","text":"客户前来柜台发起还款申请。①"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"操作流程注意事项：\n现核呆还款都可通过8004006现金存入核呆信用卡还款完成。不能还款的再通过挂账方式进行。\n①他行核呆需提前联系他行发送NOTES文件给我行作为凭证\n②8004006存入需选择现金存入\n③20010现金过账需集中授权\n授权材料为：9991凭证、联网核查、头像\n备注：XXX呆账还款卡号\n集授通过后屏打作为传票\n④20045需集中授权（连续授权）\n授权材料为：20490-2030余额截屏、流水明细截屏、9991凭证、NOTES发文，需备注\n跨机构转账需提前与他行联系，在系统关闭前完成\n⑤E66001与E66002需授权人员复核，挂账资金待后续销账转入个金账户。","shape":true},{"kind":"paragraph","text":"识别客户情况","shape":true},{"kind":"paragraph","text":"8004006现金存入","shape":true},{"kind":"paragraph","text":"8004006无法存入"},{"kind":"paragraph","text":"20010现金过账","shape":true},{"kind":"paragraph","text":"本行核呆","shape":true},{"kind":"paragraph","text":"他行核呆","shape":true},{"kind":"paragraph","text":"E66001\n挂账","shape":true},{"kind":"paragraph","text":"20045\n转入他行","shape":true},{"kind":"paragraph","text":"待分行通知销账","shape":true},{"kind":"paragraph","text":"E66002\n销账⑤","shape":true},{"kind":"paragraph","text":"20045\n转入个金","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.若客户为他行核呆还款，需提前与他行联系进行沟通（班后跨网点9991划转需先报备省行渠运部账户团队，同意后再提交远程授权，对手双方要平账）；"},{"kind":"paragraph","text":"2.BGL班后时间追踪号要为0。"}]},{"title":"2.3.4信用卡相关销卡","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证件或其他有效证件、信用卡（如有）；"},{"kind":"paragraph","text":"填写单据：个人信息变更表。"},{"kind":"paragraph","text":"客户环节注意事项：\n1.确认客户身份证件是否真实有效。\n2.信用卡销户取现不能代办、存现可以代办。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"操作流程注意事项：\n客户信用卡如过期或未携带可通过集中授权进入销户界面（核准要点：联网核查、客户有效身份证件、G04002体现客户信息、信用卡号、头像）交易完成打印TY04第一联做传票。\n客户预销户如有网银等外围关系需要先将外围关系解约后方可预销户（可通过手机银行解除信用卡关联）。\n预销户可以通过拨打4006695566客服进行。\n执行8004007销户交易时，可以选择现金或者转账到客户储蓄账户进行销户。柜员选择转账销户时要注意销户资金会先转入9991003的BGL账户，需要补录追踪号方可进行21051转客户账号。（目前不允许使用BGL过度的转账方式销户）(事先查看相关BGL账户状态是否正常）","shape":true},{"kind":"paragraph","text":"联网核查、账户信息查询","shape":true},{"kind":"paragraph","text":"8004001信用卡综合服务","shape":true},{"kind":"paragraph","text":"8004007销户","shape":true},{"kind":"paragraph","text":"提交打印","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.查看BGL9991003余额是否为0；"},{"kind":"paragraph","text":"2.查看追踪号余额是否为0。"}]},{"title":"2.3.5信用卡合并客户号","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"提交材料：客户有效身份证原件；（若合并的2个客户号姓名或证件号码不一致，需提供2个客户号归属于同一客户的证明材料，包括但不限于信用卡申请资料，户口簿，公安证明等）"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image21.png"]},{"kind":"paragraph","text":"登录核心，联网核查后使用8101200查询客户名下客户号及对应状态，再通过8004036办理对私信用卡合并业务（关联时填写的核心客户号一定要用10位，不足的前面补齐0）","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：","shape":true},{"kind":"paragraph","text":"告知客户T+1日生效，T+1日后使用该代码进行查询","shape":true},{"kind":"paragraph","text":"业务成功通知客户，业务失败查看失败代码，联系客户前来处理","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.客户证件联网核查，核查后预留客户联系方式；\n2.该代码适用于客户名下存在两个客户号，且旧客户号为停用状态但名下信用卡为正常状态。若两个客户号均为正常状态，使用8101701进行合并即可；\n3.T+1日生效，需进入该代码查询业务状态；\n4.失败代码为E001,需将主从客户的账单日维护成同一天(选择保留主属客户的账单日，则上送从属客户号+主属客户的账单日，即去修改从客户的账单日；选择保留从属客户的账单日，则上送主属客户号+从属客户的账单日，即去修改主客户的账单日)；\n5.失败代码为E005,将维护从客户的临时额度调整为0；\n6.失败代码为E006,将两张其中的一张信用卡销户。选择需要销户的卡，点击销户按钮，调信用卡接口进行销户。(具体操作见中国银行股份有限公司信用卡柜台业务操作手册【2023年】4月版)。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.信用卡合并需要T+1日生效，隔日进去查询结果；"},{"kind":"paragraph","text":"2.合并失败查看失败代码判断能通过核心解决。无法通过核心解决的需客户填写信用卡业务申请表，报送后台修改；"},{"kind":"paragraph","text":"3.报送后台修改需提交（合并界面截图、客服系统截图、客户综合查询资料【G04001】、客户号信息、客户基本信息确认、业务申请表）等材料。"}]}],"blocks":[]}],"blocks":[]},{"title":"3.结算业务","children":[{"title":"3.1现金业务","children":[{"title":"3.1.1网点ATM清机&长短款挂/销账","children":[],"blocks":[{"kind":"paragraph","text":"一．网点ATM清机操作流程"},{"kind":"paragraph","text":"核对清机人员、后台人员签字的ATM现金领用单，签字①","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n（柜员务必先做账，清机人员再清机）\n①注意清机编号、金额。\n②金额输入清机金额；管理用户输入清机后台人员EHR号；提示码默认；现金统计分析码6200；备注输入清机编号、对应金额。\n③核对清点现金确认无误后核心再做账。\n④现金统计分析码5200。","shape":true},{"kind":"paragraph","text":"核心交易码21088领用现金②","shape":true},{"kind":"paragraph","text":"根据清机人员、后台人员签字的ATM现金上缴单核对清点金额③","shape":true},{"kind":"paragraph","text":"核心交易码27028上缴现金④","shape":true},{"kind":"paragraph","text":"二．长短款挂/销账操作流程"},{"kind":"paragraph","text":"根据后台提供的长短款挂/销入账依据准备核心做账","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.需要网点行长签字\n2.E05265选择长款或短款（集中授权：账户信息；后台提供的挂账依据）\n3.E05267选择长款或短款（集中授权：账户信息；后台提供的销账依据）","shape":true},{"kind":"paragraph","text":"核心交易码E05265","shape":true},{"kind":"paragraph","text":"核心交易码E05267","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.如信用卡或他行长短款需要发送省行查询后方可销账，销账BGL选择9991003；"},{"kind":"paragraph","text":"2.销账BGL账号须为本机构；"},{"kind":"paragraph","text":"3.单笔2-3万元须分行审批，3万以上需要省行审批."}]},{"title":"3.1.2机构缴、调款","children":[],"blocks":[{"kind":"paragraph","text":"一.网点现金领入记账（调款）"},{"kind":"paragraph","text":"早上双人开箱核验调款金额账实相符","shape":true},{"kind":"paragraph","text":"员工统一渠道系统中“集中运营管理”点击现金管理—现金申领—收款确认","shape":true},{"kind":"paragraph","text":"核心交易码9071004，\n提交后复核授权并打印","shape":true},{"kind":"paragraph","text":"员工统一渠道系统中“集中运营管理”点击现金管理—现金上缴","shape":true},{"kind":"paragraph","text":"复核人员核验账实相符\n包装扎把无误后双人封箱","shape":true},{"kind":"paragraph","text":"核心交易码9071011，\n提交后复核授权并打印","shape":true},{"kind":"paragraph","text":"二.网点现金调出记账（缴款）"},{"kind":"paragraph","text":"复核复核人员在CIBS扫描缴款箱编号，提交现金上缴单","shape":true}]},{"title":"3.1.3对公存取现","children":[],"blocks":[{"kind":"notice","text":"此模块为对私模块，建议删除。（建议还是保留）"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：存款账户日常结算办理人员携带本人有效身份证原件（现金存款超一万元时提供）、非存款账户日常结算办理人员还须携带授权书（存款账户当日累计现金存款超五万元时提供）或公司出具的介绍信。通过E52307交易查询是否为存款账户日常结算办理人员"},{"kind":"paragraph","text":"填写单据：单位存款凭条。"},{"kind":"paragraph","text":"填写图样："},{"kind":"paragraph","text":"","images":["image22.jpeg"]},{"kind":"paragraph","text":"图一"},{"kind":"paragraph","text":"客户环节注意事项：\n1.该笔业务是否需要证件，如需要，携带证件是否有效；\n2.客户填写的凭证日期必须为存款当日；\n3.对公存现错账冲正较为困难，存现之前须仔细核对存款信息，确保无误。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"检验单据填写是否完整，日期填写是否正确。大写金额需顶格填写。“备注”栏为必填项。","shape":true},{"kind":"paragraph","text":"","images":["image23.png"]},{"kind":"paragraph","text":"核心流程操作界面：","shape":true},{"kind":"paragraph","text":"登录核心，联网核查（如有需要）、使用1010存入","shape":true},{"kind":"paragraph","text":"提示客户在回单上签字（当次存款金额五万（含）以上需双人复核并签章）","shape":true},{"kind":"paragraph","text":"Tips"},{"kind":"paragraph","text":"操作流程注意事项：\n1.对公存现超一万以上时需存款人携带身份证，并进行联网核查。（判断该笔业务场景对私还是对公）对私使用8005001\n2.通过479/450交易查询该账户当日存款累计是否超5万元。非存款账户日常结算办理人员，在存款账户当日存现超限（限额为日累计五万元）时，需提供存款单位出具的授权书。\n3.大额存现非我行（本网点）对公账户时，需进行490远程授权，出具查询账户信息的业务交易背景，通过后截屏490账户信息，存款凭证上需经办人员和复核人员双签。\n4.监狱犯人向监狱对公账户缴存生活费系统需输入卡号回显监狱的对公账户，不能直接手输监狱账号，以便监狱账户财务核对。\n5.单位对公账户周末和节假日不能进行现金存缴。\n6：单位存款凭条需备注经办人与该单位的关系。\n6\n7.对公存现超5万需由复核人员复点现金并鉴章。","shape":true}]},{"title":"3.1.4行内现金汇款","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件；"},{"kind":"paragraph","text":"填写单据：人民币汇款申请书。"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image24.png"]},{"kind":"paragraph","text":"注意事项：\n现金汇款需汇款人有我行的客户号（即存在客户信息），如无先创建一个临时客户号","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"填单审核客户材料","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n现金汇款金额超过1万需集中授权所需材料有：\n联网核查截图\n办理人信息截图\n办理人头像\n身份证原件照片\n汇款申请书","shape":true},{"kind":"paragraph","text":"清点现金并联网核查身份证","shape":true},{"kind":"paragraph","text":"登录核心系统，通过8005001交易进行，汇款金额≤1万直接提交成功；汇款金额＞1万则需集中授权","shape":true},{"kind":"paragraph","text":"提示客户回单签字","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.与客户确认汇款金额，并与清点现金进行核对一致；"},{"kind":"paragraph","text":"2.汇款申请书上需填写汇款人九大要素。"}]},{"title":"3.1.5活期存/取（本币/外币）（卡、存折）","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：卡/存折、客户有效身份证原件（5万以上）。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image25.png"]},{"kind":"paragraph","text":"清点现金（存）\n交易码60/1060（取）","shape":true},{"kind":"paragraph","text":"交易码10/1010(存)\n刷折/卡(取)","shape":true},{"kind":"paragraph","text":"输入产品类型及产品子类：(存)\n输入金额并与客户确认(取)","shape":true},{"kind":"paragraph","text":"提交，打印回单并让客户签字\n客户输入密码，清点现金","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n收付现金时要求在客户面前点钱并核对金额，保证现金在客户视线范围内，做到唱收唱付。\n取款业务先记账再付款，存款先收款再记账。\n人民币存款金额超过五万要求携带有效证件进行联网核查（如代办需提供代办人 代办人及账户人有效证件）。\n人民币活期储蓄存折，产品大类是5501\n人民币存20万以上、取5万以上需集中授权。取款20万以上叫复核人员进行大额实时并在传票上签字。\n人民币存取5万及以上要双人复核\n存取5万人民币填写个人大额现金存、取款业务尽职调查问卷，如界面提示要求我们进行尽调，也需要填写尽职调查问卷。\n8.单位对公账户周末和节假日不能进行现金存缴。该模块为个人业务，建议删除该条条容","shape":true},{"kind":"paragraph","text":"对于存取金额在1万（含）-5万（不含）通过询问客户、结合联网核查判断是否客户本人办理，分为以下情况："},{"kind":"paragraph","text":"1、客户本人办理存取业务，无需留存证件"},{"kind":"paragraph","text":"2、代办人可以提供账户人及代办人证件，等同5万以上要求办理"},{"kind":"paragraph","text":"3、代办人仅能提供代办人证件，存款按现金汇款业务要求办理，取款需要备注账户本人无法到场办理原因或电话联系客户情况。"}]},{"title":"3.1.6定期存款","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户本人有效身份证原件、定期存折或存单或银行卡（如为代办需：客户本人及代办人有效身份证原件）。"},{"kind":"paragraph","text":"填写单据：优惠利率客户告知书（如为上浮利率则填写）。"},{"kind":"paragraph","text":"注意事项：\n1.确认客户身份证件是否真实有效；\n2.核对客户信息，确认客户所出示的证件是否与系统预留信息一致。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"联网核查","shape":true},{"kind":"paragraph","text":"10有折现金存款/1010 无折现金存款或45有折转账/1045无折转账输入金额，币种，产品类型，产品子类","shape":true},{"kind":"paragraph","text":"提交，打印TY04","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.现金存入≥5万元需换人复核，由复核人员进行大数核点收付现金实物，并在传票上加盖名章；\n2.转账存入≥50万元需远程集中核准，代办定活互转≥20万元需大额核实","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"如为转账存入定期一本通，需引导客户至智能柜台进行定期一本通存折补登操作或核心输入600进行存折补登"}]},{"title":"3.1.7定期取/续存业务","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证件、卡/折/存单"},{"kind":"paragraph","text":"填写单据：开户单（如需）、优惠利率告知书（如需）"},{"kind":"paragraph","text":"注意事项：\n先确认清楚该笔定期是否已到期，是否提前支取，以及客户后续想要（部分）支取还是续存。\n我行定期大多为自动转存，若超过到期日前来支取算作“提前支取”。提前支取存单需要在存单背面背书，存折在柜面做支取需在回单上写“同意（提前）支取第X笔” +名字+证件号码+日期+电话号码\n代办需携带两人有效身份证件，所有回单签两人名字。","shape":true},{"kind":"paragraph","text":"操作流程"},{"kind":"paragraph","text":"A.取定期"},{"kind":"paragraph","text":"","images":["image26.jpeg"]},{"kind":"paragraph","text":"审核材料\n、","shape":true},{"kind":"paragraph","text":"核心操作界面截图：3060","shape":true},{"kind":"paragraph","text":"1.现金结清：3060无折现金结清关户/3260有折现金结清关户。\n2.转账结清：3045无折转账结清关户/3545有折转账结清关户。","shape":true},{"kind":"paragraph","text":"打印回单，客户签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.办理业务当天到期的定期无需身份证件即可办理支取业务（本息金额小于5万）（正常都需要核查身份证）","shape":true},{"kind":"paragraph","text":"B.部分提取"},{"kind":"paragraph","text":"审核材料\n、","shape":true},{"kind":"paragraph","text":"有折部提360/无折部提1360","shape":true},{"kind":"paragraph","text":"打印回单，客户签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.柜面做部提，客户要在回单上写“本人要求部分提取第X笔XX金额”","shape":true},{"kind":"paragraph","text":"C. 定期取息/加钱续存"},{"kind":"paragraph","text":"","images":["image27.jpeg"]},{"kind":"paragraph","text":"审核材料\n、","shape":true},{"kind":"paragraph","text":"核心操作界面截图：G06007","shape":true},{"kind":"paragraph","text":"G06007 单笔结清续存（此交易码操作必须加减金额）","shape":true},{"kind":"paragraph","text":"打印回单，客户签字","shape":true},{"kind":"paragraph","text":"D.定期直接续存"},{"kind":"paragraph","text":"","images":["image28.jpeg","image29.jpeg"]},{"kind":"paragraph","text":"审核材料、联网核查\n、","shape":true},{"kind":"paragraph","text":"核心操作界面截图：G06002\n注：每一条记录都要勾选并试算金额","shape":true},{"kind":"paragraph","text":"1.3045无折转账结清关户/3545有折转账结清关户\n2.多笔结清：G06002多笔结清续存","shape":true},{"kind":"paragraph","text":"打印回单，客户签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.本金和利息会一起转存到下一笔定期中；\n2.G06002交易不管金额多大都要上集授，建议提前准备好所需截图。可以将多笔零散定期合为一笔金额续存。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.交易过程中现金存、取大于等于5万需要后台复核；"},{"kind":"paragraph","text":"2.操作本身并不复杂，问清楚客户要办理什么业务，再行操作。"}]},{"title":"3.1.8假币收缴","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证件原件"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"操作流程注意事项：\n①系统信息录入：收缴机构信息录入，点击新增，对应币种、面值、币别、版别、收缴日期、假币一二级制作方式、是否报警、假币来源、明细、客户信息、是否通过机具、发现地区、收缴单位号码是否具有冠字号、冠字号码、张数录入。\n②点击提交并打印凭证，客户核对签名，第二联交客户留存，注意提示客户如有异议可在三个工作日带上假币收缴凭证内向当地人行复议，若客户拒绝签名，应在假币收缴凭证上注明情况，并进行假币代保管登记本登记。\n③员工统一渠道操作：点击假币管理，点击二代假币流转，选择假币内部流转交出，交出机构及收入机构录入，点击提交后由后台复核，打印假币流转单据经办复核签章随假币实物上缴金库。后续需关注假币流转情况是否最终抵达人行。\n④检查录像监控保存至少三个月","shape":true},{"kind":"paragraph","text":"输入代码9071028","shape":true},{"kind":"paragraph","text":"系统信息录入","shape":true},{"kind":"paragraph","text":"录入完成后假币加盖假币章，假市收缴凭证客户签字","shape":true},{"kind":"paragraph","text":"登录后台登录员工统一渠道-\n进行假币上缴","shape":true},{"kind":"paragraph","text":"流程建议更新为："},{"kind":"paragraph","text":"1、共同鉴别、当面收缴（由有收缴假币资格的经办复核双人在监控下及客户可视范围内对假币进行人工核验，确认为假币无误后，告知鉴定结果，加盖假币章【人民币硬币、外币纸币不盖】。正面水印窗竖盖，背面中间横盖；）"},{"kind":"paragraph","text":"2、收缴人员录入系统、开具《假币收缴凭证》，告知权益"},{"kind":"paragraph","text":"3、登记《假币代保管登记簿》"},{"kind":"paragraph","text":"4、5个工作日内登录后台登录员工统一渠道完成假币上缴"},{"kind":"paragraph","text":"建议：以上种种还是需要回归到原始的管理办法要求，建议将这些操作流程归口到对应条线，由条线人员根据最新的管理办法及授权要点等，制定对应业务一页纸（比如假币收缴操作一页纸、对公存取业务一页纸等），通过专门的行信群分享，并根据员工的操作反馈及流程变更由专人实时更新，专人动态调整，员工遇到操作问题可以找到对应业务的操作一页纸，对应一页纸指引，逐步按规范操作业务，真正为一线员工提供可具实际操作参考价值的宝典。"},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.纸币经点钞机核验报警后，由有收缴假币资格的经办复核双人在监控下及客户可视范围内对假币进行人工核验，确认为假币无误后，加盖假币章【人民币硬币、外币纸币不盖】。正面水印窗竖盖，背面中间横盖；"},{"kind":"paragraph","text":"2.当收缴数量达到5张及以上时，需报警联系警方处理。一旦确认为假币，禁止将假币递出柜台窗口交给客户。"}]}],"blocks":[]},{"title":"3.2非现金业务","children":[{"title":"3.2.1大额存单申购、支取/配单G06008","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证件原件、银行卡或活期存折；若为代办，需提供代办人有效身份证件原件；（代办金额超过20万（含）需与账户本人核实）"},{"kind":"paragraph","text":"填写单据：如需配单需填写开户申请书。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"1.大额存单申购"},{"kind":"paragraph","text":"联网核查：查银行卡账户是否存在异常状态。","shape":true},{"kind":"paragraph","text":"使用G06008刷卡办理，选择客户需要申购的大额存单期限，输入金额提交。","shape":true},{"kind":"paragraph","text":"选中需配发的大额存单-选择凭证配发-提交联动至501配发存单。","shape":true},{"kind":"paragraph","text":"2.大额存单支取"},{"kind":"paragraph","text":"联网核查后使用G06008，刷卡办理。"},{"kind":"paragraph","text":"选择客户需要支取的大额存单，选择全部支取或部分支取，支取方式为凭密码支取，转入账户产品类型为5502，产品子类1001提交。填写大额存单支取通知书（如有）。"},{"kind":"paragraph","text":"操作流程注意事项：\n1.大额存单支取时，注意结清金额大于50万需提交集中授权（远授：联网核查+账户资料+G06008+银行卡+客户头像+背书后的存单，本人办理时结清金额如大于等于100万，还需要进行大额交易实时核实）；（目前新规定活，活定转账20万及以上需大额核实）\n2.根据《中国银行股份有限公司个人人民币存款业务管理办法（2023年发布）》规定，定活转账可委托他人代办。代办时按第十七条（三）款有关规定处理。对人民币单笔20万元（含）以上的代办业务，还应与账户人进行大额交易实时核实，代办情况下应通过拨打账户人电话等方式进行核实并留存记录（日期、时间、账户人电话、核实人、核实结果等）。\n3.大额存单部分支取提交后联动501部提换发新存单。","shape":true},{"kind":"paragraph","text":"Tips"},{"kind":"paragraph","text":"TIPS:"},{"kind":"paragraph","text":"1.进行大额存单申购前需先查询大额存单剩余额度是否满足客户需求。"},{"kind":"paragraph","text":"2.大额存单提前支取按活期利率计息，无法靠档计息。"},{"kind":"paragraph","text":"3.大额存单部分支取后剩余金额须大于大额存单起存金额。"},{"kind":"paragraph","text":"4.大额存单到期无法自动转存，到期日本息自动转入活期账户。"},{"kind":"paragraph","text":"5.建议客户尽量不配发存单，到期后可自动转入活期账户。"},{"kind":"paragraph","text":"6.该笔业务可建议客户使用手机银行或智能柜台办理更为便捷。"}]},{"title":"3.2.2转账（人民币）","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、转账介质；"},{"kind":"paragraph","text":"填写单据：转账汇款单，大额转账审批表（如有需要）。"},{"kind":"paragraph","text":"客户环节注意事项：\n1.客户的身份证件是否有效；\n2.该类业务基本均已实现在智能柜台办理，如需到柜面办理需注意审核；\n3.需提交远程授权的，应注意审核点；\n4.定期转账收款人必须为同名账户。\n大额转账需网点复核人员与账户人完成核实并做好记录。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"审核客户材料（有效身份证、介质等）①","shape":true},{"kind":"paragraph","text":"根据客户需要匹配对应交易码，详见相关交易码及步骤","shape":true},{"kind":"paragraph","text":"提交打印并签字，需提交远程授权的，应注意审核点","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.客户状态是否正常\n2存折结清或转存业务需在TY04备注提前/到期支取第x笔，并让客户签字，存单应做好背书\n3转账金额若≥50万，应填写大额转账单，若超100万（含）还需网点复核人员与账户人完成实时核实并做好记录\n4收款人非客户本人时，需与客户核实转账意愿，谨防电诈","shape":true},{"kind":"paragraph","text":"注意事项："},{"kind":"paragraph","text":"非同名行内人民币汇款使用8005001行内汇款交易，50万（含）以上需集中授权"},{"kind":"paragraph","text":"集中授权要素：联网核查+身份证+银行卡（汇款人）+人像+账户资料截屏+汇款申请书+100万（含）需大额核实截屏"},{"kind":"paragraph","text":"提示：以下代码仅限于同名互转"},{"kind":"paragraph","text":"①一本通转活一本通一本通----交易码：45"},{"kind":"paragraph","text":"必输项：45→账号、货币、金额、子账户类别、支取方式、转入账号、货币、产品类型、产品子类→提交"},{"kind":"paragraph","text":"②转账，卡转定一本通----交易码：1045"},{"kind":"paragraph","text":"必输项：1045→货币、账号（搜索-卡号-刷卡-确定-关联帐户-选中-返回账号卡号-关闭-关闭）、子账户类别、金额、转入账号、产品类型（5507）、产品子类、存期、基期（M）→提交。"},{"kind":"paragraph","text":"③转账，定一本通转活一本通----交易码：3045"},{"kind":"paragraph","text":"必输项：3045→转出账号、货币、凭证类型（2001）、凭证号码、支取方式、转入账号、产品类型、产品子类→提交。"},{"kind":"paragraph","text":"④转账，定一本通转活一本通----交易码：3545"},{"kind":"paragraph","text":"必输项：3545→账号、货币、子账户类别、序号、支取方式、转入账号、产品类型、产品子类→提交。"},{"kind":"paragraph","text":"⑤转账，定一本通转定一本通----交易码：3545"},{"kind":"paragraph","text":"必输项：3545→账号、货币、子帐户类别、序号、支取方式、转入账号、产品类型（5507）、产品子类、存期、基期（M）后提交。"},{"kind":"paragraph","text":"⑥转账，定一本通部提转活一本通----交易码：345"},{"kind":"paragraph","text":"必输项：345→账号、货币、序号、金额、支取方式、转入账号、产品类型、产品子类后提交。"},{"kind":"paragraph","text":"⑦转账，定一本通部提转定一本通----交易码：345"},{"kind":"paragraph","text":"必输项：345→转出账号、货币、序号、金额、支取方式、转入账号、产品类型（5507）、产品子类、存期、基期（M）→提交。"},{"kind":"paragraph","text":"⑧转账，定单部提转活一本通----交易码：1345"},{"kind":"paragraph","text":"必输项：1345→转出账号、货币、金额、凭证类型（2001）、凭证号码、支取方式、转入账号、产品类型、产品子类→提交；联动501→签发原因（3）、新凭证类型（2001）、新凭证号码→提交"}]},{"title":"3.2.3补换发存折","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、存折、对账簿（需带银行卡）"},{"kind":"paragraph","text":"客户环节注意事项：\n1.有效证件原件\n2.如为代办业务，存折内页不可交给客户；\n3.该业务不允许存折补磁，旧存折失磁按破损换折处理。","shape":true},{"kind":"paragraph","text":"二.操作流程","images":["image30.png","image31.png"]},{"kind":"paragraph","text":"核心操作界面：","shape":true},{"kind":"paragraph","text":"联网核查，使用代码G04002查询客户信息是否一致。","shape":true},{"kind":"paragraph","text":"补换发存折，交易代码500","shape":true},{"kind":"paragraph","text":"选择存折换发原因","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.490查询客户持有凭证为当前有效凭证（核对存折序号）\n2.存折挂失换发前需先办理重空挂失业务，挂失换发如为代办需要上门见证核实。若为对账簿丢失，无需挂失，客户提供情况说明并签字盖章即可；\n3.存折破损换发需回收正本旧存折，并在每页加盖作废章；\n4.若客户在换折时遗忘密码，可通过远程授权平台进行换折，注意审核远程授权要点；\n5.存折换发支取方式选择凭密码支取，对账簿支取方式选择无要求；\n6.不得使用500代码为客户补打旧存折扉页，应选择破损换发更换。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.存折磁条需剪角作废，并让客户签字；"},{"kind":"paragraph","text":"2定期存折满页换发需复印新存折扉页跟账；"},{"kind":"paragraph","text":"3.存折扉页收回后需与复核人员双签，并加盖作废章。"}]},{"title":"3.2.4开立、回收存款证明","children":[],"blocks":[{"kind":"paragraph","text":"柜面存款证明开立"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、凭密码支取的存款凭证。"},{"kind":"paragraph","text":"客户填写：存款证明申请书、个人存款证明客户须知、存款证明个人信息授权书、存款证明敏感个人信息授权书。"},{"kind":"paragraph","text":"客户环节注意事项：\n1、如为无凭证介质的账户开立存款证明，应通过440查询账户详细信息，提供凭证号码、凭证状态显示为空白的截屏。2、非凭密码支取的凭证只能在原开户行办理开立存款证明。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"①核验身份并查询账户情况\n②9079冻结情况查询截图\n③通过通用查询查看客户等级","shape":true},{"kind":"paragraph","text":"","images":["image32.png"]},{"kind":"paragraph","text":"核心交易操作界面：","shape":true},{"kind":"paragraph","text":"④执行 G06013 交易\n⑤界面录入后打印《存款证明申请书》并要求客户签字确认并填写联系电话","shape":true},{"kind":"paragraph","text":"⑥集授：人像、核查、介质、G04002、9079、申请书、存款证明凭证\n⑦集授通过后打印存款证明，系统联动收费","shape":true},{"kind":"paragraph","text":"⑧收费传票打印签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n截图：联网核查、G04002（确认金额）、440（如为无介质账户）；\n页面录入：英文名字录入时注意姓与名之间添加空格；\n3、9079账户查询截屏(需显示全部冻结记录)，经办柜员在录入9079交易查询冻结记录时，需按申请证明的子账户类型录入子账户类别/册号序号。有03冻结原因外的其他冻结不得开立存款证明；\n4、存款证明是根据客户等级进行收费，工本费原价20元，四级减半、六级及以上全免，其余原价。涉及收费，要提前告知客户并确认收费方式；\n5、要告知客户存款证明开立多久资金就会被冻结多久，证明到期后资金会自动解冻，若需要提前解冻，则需提供存款证明原件；\n6、系统会联动收费，可把通用查询界面屏打做依据，避免后期后督检查有疑问；\n7、传票：收费回单（若有）、存款证明申请书、个人存款证明客户须知、存款证明个人信息授权书、存款证明敏感个人信息授权书。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"日本驻华大使馆通知要求旅行社需要对银行开具的存款证明真伪进行辨别，我行可通过手机银行及中银跨境go进行核验。存款证明验证功能需要向存款证明申请人发送短信，才可在线查验。要询问客户后续是否有验证诉求，若有需求则务必确认核心预留的手机号码。"},{"kind":"paragraph","text":"电子渠道开立存款证明"},{"kind":"paragraph","text":"一、客户环节"},{"kind":"paragraph","text":"1、客户通过手机银行搜索“存款证明”进入开立界面；"},{"kind":"paragraph","text":"2、根据需求录入界面；"},{"kind":"paragraph","text":"3、电子版开立成功后可凭有效身份证件临柜打印纸质版存款证明。"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件。"},{"kind":"paragraph","text":"客户填写：《对外提供存款证明个人信息授权书（适用于线上）》。"},{"kind":"paragraph","text":"二、核心操作"},{"kind":"paragraph","text":"1、联网核查；"},{"kind":"paragraph","text":"2、确认客户已填写《对外提供存款证明个人信息授权书（适用于线上）》；"},{"kind":"paragraph","text":"3、执行G06013交易——添加附件——选择“电子存款证明打印”——按身份证号查询后选择需打印的内容——录入存款证明凭证编号——点击“打印”；"},{"kind":"paragraph","text":"4、打印后复印存款证明做传票。"},{"kind":"paragraph","text":"操作流程注意事项：\n联网核查\n厅堂指导客户通过手机银行开立需注意：用户名录入为英文/拼音大写全拼，姓、名之间添加空格；存款证明类型选择电子码（纸质版为客户支付邮费邮寄到家，一般不选择）。\n线上开立收费界面会显示原价20元，实际系统会根据客户等级进行减免，可通过流水查看实际扣除多少手续费。\n4、传票：存款证明复印件、《对外提供存款证明个人信息授权书（适用于线上）》。","shape":true},{"kind":"paragraph","text":"存款证明收回"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、存款证明原件。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image33.png"]},{"kind":"paragraph","text":"截图：联网核查、G04002","shape":true},{"kind":"paragraph","text":"核心交易操作界面：","shape":true},{"kind":"paragraph","text":"执行G06013交易","shape":true},{"kind":"paragraph","text":"提交集中授权、并打印传票","shape":true},{"kind":"paragraph","text":"系统会跳出印章冲正界面，若原件为电子章，务必录入电子印章编码","shape":true},{"kind":"paragraph","text":"收回存款证明加盖“作废”戳记作为交易传票","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1、集授材料：人像、核查、存款证明原件、G04002、介质（若有）\n2、系统尚不能区分新旧存款证明故印章冲正非强制录入，带有电子印章验证码的存款证明收回必须录入电子印章编码，否则会造成客户已收回存款证明但仍可在我行官网查询到为有效开立的存款证明。\n3、传票：系统传票、存款证明原件","shape":true}]},{"title":"3.2.5短信通知相关","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件；"},{"kind":"paragraph","text":"填写单据：《开户申请表》（开立短信通知）、《变更申请书》（变更、取消短信通知）、《短信通知协议》加一个短信协议图"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image34.png"]},{"kind":"paragraph","text":"图一 图二"},{"kind":"paragraph","text":"操作流程注意事项：\n联网核查，若客户为存量客户，先更新客户个人信息后再办理业务；\n若客户为新户，开户申请书上的地址信息需按照我行个人信息录入规范填写，职业信息要求完整准确且长度不少于四个汉字字符。(新开客户可参考 2.2.1开立账户中证件号码和姓名的规则)","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"识别客户情况，了解客户的需求","shape":true},{"kind":"paragraph","text":"核心交易操作界面：\n核心需读取卡号后才能回显界面，不便截图无介质需集中授权，不便截图","shape":true},{"kind":"paragraph","text":"登录核心系统，联网核查后使用 E16604/E16601/E166103办理短信通知相关业务","shape":true},{"kind":"paragraph","text":"打印传票，提示客户在回单上签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n注意是否欠费(取消需补缴，销户联动无需补缴欠费)\n有介质用 E16601、无介质用 E16603；\n无介质需提供“95566”工单或其他特殊情况说明。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.办理变更业务，确认是否变更到最新手机号；"},{"kind":"paragraph","text":"2.办理解约短信业务，确认是否解约成功。"}]},{"title":"3.2.6联名存款账户","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"提交材料：客户本人有效身份证原件（必要时还需提供辅助证件，如附有照片的证件或有法律效应的文件均可）；"},{"kind":"paragraph","text":"填写单据：填写完整的《联名账户申请书》，一式四份。外加账户所有联名人的：本人手机实名制查询；查询黑名单（删除）、福盾系统、银证通系统（删除）及案件查控平台、反诈风向标（查询结果记录在传票上），全部打印作传票。（材料同正常开户）"},{"kind":"paragraph","text":"注意事项："},{"kind":"paragraph","text":"1.告知客户起存金额为5万元"},{"kind":"paragraph","text":"2.核对手机号实名制"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"联名账户的开户","shape":true},{"kind":"paragraph","text":"联名账户开户注意事项：\n①起存金额为5万元，仅支持人民币。\n②只能开活期储蓄存折、定期存折、存单，不能开立借记卡。\n③不可约定转存、还贷、放款（仅整存整取可自动转存），不可以开立存款证明。\n④存款可代办，无需该联名账户中所有客户共同到场办理。\n⑤开户时，《联名账户申请书》背面有需客户签字处，应留意。\n⑥《联名账户申请书》与TY05第一联留作传票，其余分发给其他客户。","shape":true},{"kind":"paragraph","text":"分别对每个客户进行身份证件核查比对，每个人都必须有独立的客户号（若无客户号，需通过G04001/8101100新开立客户号），截图","shape":true},{"kind":"paragraph","text":"选定A客户，用G04001开立新核心储蓄存款账号（产品类型5506，产品子类0611），先不存款直接提交，打印TY05开户回单，交由A客户签名","shape":true},{"kind":"paragraph","text":"建立联名关系（分别对每个客户的G04002截图）\n通过60750进入，B客户号+A账号\n目标客户号:B，删除标识：否（若三人则重复本交易）","shape":true},{"kind":"paragraph","text":"通过60460查询ABC三人是否已存在联名关系","shape":true},{"kind":"paragraph","text":"60451（客户信息查询返回）：柜员核对信息无误后，选择左上角“连续账户”，确认后显示客户号改下账户状态，显示为联名账户","shape":true},{"kind":"paragraph","text":"60450客户账户后查询：是否联名账户：Y是","shape":true},{"kind":"paragraph","text":"创建联名户名：\n通过7050-“5账户户名变更”，“A姓名，B姓名，C姓名”（需使用全角逗号），顺序按照申请书客户排序，需集中授权","shape":true},{"kind":"paragraph","text":"7465（账户户名变更）1.账户名称→依次录入账户所有人的姓名，每个姓名用“，”分隔（全角）；2.删除标识，账户长名标识不得录入","shape":true},{"kind":"paragraph","text":"配发存折/存单：500/501，支取方式：凭密码支取","shape":true},{"kind":"paragraph","text":"1010现金存款或1045由主账户人账户转入，开户完成","shape":true},{"kind":"paragraph","text":"联名账户的销户","shape":true},{"kind":"paragraph","text":"联名账户销户注意事项：\n①转账、销户、结清时需该联名账户中所有客户共同到场办理。\n②因联名账户为储蓄户，因此存入、取出资金只能通过现金结清方式或转入主账户人A名下账户方式。\n③销户时，要收回客户持有的《联名账户申请书》，并在申请书上勾选销户。若客户回单丢失，应重新填写一份完整的申请书,每一页申请书的背面左上角需签字。\n④远授时除了每个账户所有人的头像，存折扉页和取款页也要拍，存单则是拍正反面（记得背书）。\n⑤若是转账结清，转入账户490要截图。\n⑥远授时申请书的第一面正面要拍，第234页的背面签名也要拍。","shape":true},{"kind":"paragraph","text":"分别对联名账户每个客户进行身份证件核查比对并截图，账户490截图，60460账户持有人截图","shape":true},{"kind":"paragraph","text":"3260现金结清或3545转账结清至主账户人A账户（都有远授）","shape":true},{"kind":"paragraph","text":"3860连续授权销户","shape":true},{"kind":"paragraph","text":"Q"}]},{"title":"3.2.7 83201跨境人民币","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：审核这笔资金是否能够入账"},{"kind":"paragraph","text":"注意事项：\n83201来账通常为港澳台地区账户汇入我行境内账户的人民币，原则上需在收到款项后的21个自然日内处理完毕。\n港澳地区仅支持同名账户互转，每日累计不超过8万元人民币。\n台湾地区居民可向境内同名或不同名账户汇入每日累计不超过8万元人民币。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image35.jpeg"]},{"kind":"paragraph","text":"83201发现来帐，判断该笔资金能否直接入账，是否需要提供资料并联系客户","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"1.可直接入账并手写申报单\n2.不可入账与客户联系后退汇\n3.联系不上客户或需要其他信息发查询给对方银行","shape":true},{"kind":"paragraph","text":"后台复核并打印回单","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.详见《中国银行股份有限公司境内机构个人跨境汇款业务管理办法（2023年版）》"},{"kind":"paragraph","text":"操作流程注意事项：\n1.83201提交--进入E8320102界面；\n2.功能参数：账号入账/修改入账/发出查询/直接退汇（对应上述几种处理情况）--提交。联动到下一界面选择查询原因和退汇原因提交即可；\n3.入账成功后经办根据回单内容手写申报单，并将回单和申报单交予申报人员。","shape":true}]}],"blocks":[]},{"title":"3.3贷款业务","children":[{"title":"3.3.1提前还款","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、还款介质（卡、存折）"},{"kind":"paragraph","text":"填写单据：客户经理制作的提前还款审批表、处理通知书等。"},{"kind":"paragraph","text":"填单图样：","images":["image36.jpeg","image37.jpeg"]},{"kind":"paragraph","text":"图一 图二"},{"kind":"paragraph","text":"客户环节注意事项：\n1.客户有效身份证原件。\n2.办理住房类贷款提前还款、超2万元（不含）房贷正常还款（如现金还款、逾期还款）需省行消费金融部审批后方可办理。\n3.贷款合同协定违约金收费规则页需客户经理双人签字确认。（如有申请特殊审批表可不收取，审批表签署到支行个金部）（目前免收违约金）","shape":true},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"","images":["image38.jpeg"]},{"kind":"paragraph","text":"通过核心代码10451.12695查询贷款利率、剩余还款计划，打印提供给客户经理制单。","shape":true},{"kind":"paragraph","text":"核心操作界面：","shape":true},{"kind":"paragraph","text":"登录核心，联网核查、G04002客户信息页面、490账户信息界面截屏，拍照还款介质（卡、折）\n（如手机实名制等信息）（无需提供）","shape":true},{"kind":"paragraph","text":"核心代码10430还款通过核心代码1074\\21035收取提前还款违约金（若有）","shape":true},{"kind":"paragraph","text":"提示客户回单签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.该笔业务需远程集授，在授权前需仔细核对客户经理提供的材料，确保材料上销贷业务公章清晰完整，需客户签字手印地方一应俱全。\n2.办理业务前再次与客户客户核对还款金额及还款意愿。\n3.普惠贷款提前还款免收提前还款违约金。\n4.贷款合同协定违约金收费规则页需客户经理双人签字确认。\n5.1074/21035提前还款违约金收费客户信息栏位要写贷款账号，账号类型选择贷款账户。\n6.提前还款业务违约金金额超过一千元时，需提交至远程集中授权中心处理，请仔细核对授权中心审核要点。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.该项业务办理完后部分回单需套打供给客户经理跟账。"},{"kind":"paragraph","text":"2.若为部分提前还款，再次打印12695剩余还款计划提供给客户。"},{"kind":"paragraph","text":"3.若为全部还款，联动结清贷款账户。"}]},{"title":"3.3.2消费分期放款","children":[],"blocks":[{"kind":"notice","text":"无此类业务，建议删除（建议保留）"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、银行卡"},{"kind":"paragraph","text":"填写单据：中国银行福建省分行专项分期业务申请表、消费分期刷卡单、贷款合同。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"确认BGL013放款金额","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.核对BGL金额款项已放置，防止先借后贷或BGL透支。\nE33101（跨行借记卡）\n21051（本行借记卡）","shape":true},{"kind":"paragraph","text":"通过E33101（跨行），21051（本行）放款","shape":true},{"kind":"paragraph","text":"提交打印","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.刷卡单需签字确认；"},{"kind":"paragraph","text":"2.消费卡种交易无法冲正，须提供“优客分期余额转出销户批准单”进行强制扣划。"}]},{"title":"3.3.3.自定义优先级转账还款","children":[],"blocks":[{"kind":"notice","text":"11034目前一级分行渠运部门不同意审批办理，除非R系统出现BUG"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、借记卡/存折。"},{"kind":"paragraph","text":"填写单据：填写核心银行系统（个人贷款）处理申请书—其他业务处理通知书②、福建分行个人金融特殊业务办理审批表。"},{"kind":"paragraph","text":"客户环节注意事项：\n①还款人携带本人有效证件、还款介质即可，可无需贷款人有效证件。\n②借款人确认处需签贷款人和还款人双方名字。还款金额默认为12695中的应还未还总金额，若客户资金不足也可先还部分。\n③表格需填写完整、准确，注意经办、复核、网点主任等签字和盖章是否齐全。","shape":true},{"kind":"paragraph","text":"二.操作流程","images":["image39.png"]},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"核查还款人身份信息和G04002还款账户信息","shape":true},{"kind":"paragraph","text":"12695查询贷款账户信息","shape":true},{"kind":"paragraph","text":"11034执行还款交易","shape":true},{"kind":"paragraph","text":"提交打印并签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.12695界面需打印作为传票附件；\n2.页面录入：刷借记卡/存折一子账户类别：CNY0一贷款账号手输一对账单摘要：客户 XXX(贷款客户)自定义优先级转账还款一优先级标识从左到右选择：P：拖欠本金-I：应收利息W：拖欠本金的罚息-A：应收利息的罚息-E：复利一征信状态默认 01：正常还款-柜台还款(非诉讼收回)。\n3.交易需远程集中授权，务必提前截图（联网核查+G04002还款账户信息+12695贷款账户信息+通知书+审批表+客户影像+还款介质）。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"传票整理：TY04、审批表、申请书、12695"}]}],"blocks":[]}],"blocks":[]},{"title":"4.外汇业务","children":[{"title":"4.1结售汇","children":[{"title":"4.1.1外币代兑换","children":[],"blocks":[{"kind":"notice","text":"（放到结售汇最后）"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：外汇兑换水单(优先使用打印的电子水单办理业务，手工填写水单仅在应急时使用）；代兑业务外币现钞结汇汇总单；兑换人身份证件；提供外币人员的护照复印件"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"兑换人联网核查","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.操作21246中需要填写企业客户号，卖出货币金额必须与客户提供的兑换水单相同，兑换日期与结汇汇总单交易日期相同\n2.集授材料：兑换人客户头像、联网核查截图、E8923404代兑点信息查询截屏、外汇兑换水单、代兑业务外币现钞结汇汇总单。注意确认录入总金额与汇率是否与兑换水单一致，汇率有时会四舍五入，需要手动修改。\n3.E8923401和E8923402 输入汇总单单号提交后左下角显示交易编码合规和交易成功即可","shape":true},{"kind":"paragraph","text":"E8923404代兑点信息查询","shape":true},{"kind":"paragraph","text":"21246外币代兑","shape":true},{"kind":"paragraph","text":"执行交易码E8923401","shape":true},{"kind":"paragraph","text":"执行交易码E8923402","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.注意审核企业是否与网点签约外币代兑协议、确认企业提供的外币提供者护照到期时间；"},{"kind":"paragraph","text":"2.若发现外币金额或人民币金额有误，可通过E8923402告知交易，修改清算状态失败，再通过E8923405修改授权状态为成功，复核通过即可。"},{"kind":"paragraph","text":"3.电子水单应经客户签字确认，在代兑机构经办人员盖章或签字确认，加盖“代兑业务专用章”后正式生效。如遇打印机故障或其他问题导致电子水单无法使用，可使用手工填制水单办理业务，但水单号应以系统生成的为准，将生成的水单号填写至手工填制水单上，手工填制水单预先印制水单号的，可将印制水单号划去，在旁边空白处抄写系统的水单号，并加盖”代兑业务专用章”。网点办理时，可按照外币代兑机构系统录入差错处理（见业务操作规程第三十三条第（三）点）。"}]},{"title":"4.1.2外币存取业务","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"本人办理：有效身份证件原件、账户介质（银行卡、活期存折）；"},{"kind":"paragraph","text":"委托办理：账户人和代办人的有效身份证原件，账户介质（银行卡、活期存折），委托办理授权书，近亲属关系证明（代办人只能是账户人近亲属才能办理，如父母、子女、配偶、兄弟姐妹们等）---标红删除"},{"kind":"paragraph","text":"客户环节注意事项：\n1.提交业务之前先进行个人外币存取钞登记；\n2.日累计超等值1万美元需提供证明材料(如：提钞备案表、他行取款回单等)。","shape":true},{"kind":"paragraph","text":"操作流程"},{"kind":"paragraph","text":"先联网核查，再通过E8921302行内控制名单查询后再交易","shape":true},{"kind":"paragraph","text":"存：10(存折)、1010(卡)，取：60(存折)、1060(卡)。\n币别栏选择客户对应要存取的货币编号","shape":true},{"kind":"paragraph","text":"个人外币存取钞登记后打印，提醒客户签名","shape":true},{"kind":"paragraph","text":"提交，打印回单，客户签名","shape":true},{"kind":"paragraph","text":"三．业务完结注意事项"},{"kind":"paragraph","text":"1.存外币时，要判断所收外币是否属于外汇管理局指定流通收付的币别版本，是否符合收兑标准；"},{"kind":"paragraph","text":"2.如果客户账户中外币是汇户仍然同意取现，客户需在业务回单上背书“同意汇户取现”并签字；"},{"kind":"paragraph","text":"3.存取时要注意产品类型和产品子类一一对应相应货币的种类，并注意区分钞汇户。"}]},{"title":"4.1.3结售汇业务","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件；"},{"kind":"paragraph","text":"填写单据：个人购汇申请书。"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image40.png"]},{"kind":"paragraph","text":"图一"},{"kind":"paragraph","text":"客户环节注意事项：\n客户证件是否真实有效；是否存在代办。个人可委托近亲属代办年度便利化额度内的结、购汇，提供户口簿，结婚证、或其他可以证明亲属关系的有效证明，办理人和被代理人的有效身份证件，如无法提供近亲属关系说明材料，可以近亲属关系承诺函代替。（注：近亲属，如父母、子女、配偶、兄弟姐妹们等）个人可委托他人或近亲属代办不占用额度内的结售汇。（提供账户人和代办人的有效身份证原件、提供有交易额的相关材料）","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"1.占用额度购汇"},{"kind":"paragraph","text":"核查身份证，查询是否有留存基本信息","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①首先在购汇前先用E8921302查询是否为我行关注客户,E8921301查询剩余购汇额度。其次可以通过叫号单判断客户是否有留存客户号，如果没有可查看开立客户号详细流程；\n②个人购汇申请书是否填写完整。","shape":true},{"kind":"paragraph","text":"45/1045","shape":true},{"kind":"paragraph","text":"提交打印并签字","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图："},{"kind":"paragraph","text":"","images":["image41.png"]},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.便利化结售汇额度为等值5万元/年（居民）、（非居民便利化结汇额度为等值5万元/年，非居民购汇凭本人有效证件一天可购汇等值500美元；凭有交易额的佐证材料可按实际金额购汇）"},{"kind":"paragraph","text":"2.统计分析码需正确"},{"kind":"paragraph","text":"3.需进行结售汇登记"},{"kind":"paragraph","text":"4.做不占用额度结售汇业务前必须做取得客户授权，做不占用额度查询(不占用额度参照相关操作流程)（不限定于侨汇便利化业务）"},{"kind":"paragraph","text":"四.文件依据"},{"kind":"paragraph","text":"1.转发总行《中国银行关于发送境内机构个人结售汇业务相关规章制度的通知》（闽汇银个[2018]130号）"},{"kind":"paragraph","text":"2.关于转发《个人外汇管理办法》和《个人外汇管理办法实施细则》的通知（闽汇[2007]9号）"}]}],"blocks":[]},{"title":"4.2 外币汇款","children":[{"title":"4.2.1外币同名跨行转账","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户提供有效身份证件及账户、收款人相关信息；"},{"kind":"paragraph","text":"填写单据：境内汇款申请书。（可通过E49205结算类申请填写来打印境内汇款申请书，超过1万美元填境内申报单）"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image42.jpeg"]},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image43.jpeg"]},{"kind":"paragraph","text":"联网核查，核验收款信息","shape":true},{"kind":"paragraph","text":"通过 8005200 进行经办操作；\n操作完成后需另一柜员通过 8005201复核。","shape":true},{"kind":"paragraph","text":"","images":["image44.jpeg"]},{"kind":"paragraph","text":"提示客户在回单上签字，确认款项已复核汇出。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.使用交易码8005200→功能选择“1录入”，业务类型：FMT100；\n2.使用交易码8005201→是否结售汇选择：“0非结售汇。”是否代办：“0否”；\n汇款货币、汇款金额、收款方信息：均根据申请书填写情况录入；\n3.收费信息：选择“从汇款账号中扣”“指定收费账号”或“不扣”；\n4.申报标识：“不申报；\n5.所有经办、复核流程原则上均在每日 16：30 分前完成，节假日不受理。（关注各行具体规定）","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.收款账户为对公账户、个人外汇结算账户、个人外汇资本账户的行内转账汇款（不含B股银证转账）以及个人跨行外汇转账汇款限于从外币现汇账户转出，若拟转出资金为现钞账户，需先转换为现汇资金再进行转账。（收款账户为对公账户、个人外汇结算账户、个人外汇资本账户的行内转账汇款（不含B股银证转账）以及个人跨行外汇转账汇款限于从外币现汇账户转出，转账时备注同名钞户或汇户转账，无需转成现汇再转账）"},{"kind":"paragraph","text":"2.需告知客户，建议客户提供SWIFT CODE，否则通过银行名称可能无法找到。"},{"kind":"paragraph","text":"3.告知客户手续费的金额：汇款金额折合为人民币的1‰收取，￥50-260。（可通过21046换算票据金额等值的人民币金额）。"},{"kind":"paragraph","text":"4.业务对每个币别的资金头寸都有时间限制，柜员在业务开始前务必先与支付清算部确认后再开始业务。"},{"kind":"table","rows":[["清算银行","币别","金额","截止时间","备注"],["中国银行","美元","/","17点","因我行为美元清算行，因此对金额并无特别限制，但大额美元汇出还需先联系省行支付清算部确定是否有头寸。"],["建设银行","港币","10万","15点","因我行为美元清算行，因此对金额并无特别限制，但大额美元汇出还需先联系省行支付清算部确定是否有头寸。"],["工商银行","日元","1000万","10点","因我行为美元清算行，因此对金额并无特别限制，但大额美元汇出还需先联系省行支付清算部确定是否有头寸。"],["浦发银行","英镑","5万","14点","因我行为美元清算行，因此对金额并无特别限制，但大额美元汇出还需先联系省行支付清算部确定是否有头寸。"],["浦发银行","加拿大元","2万","14点","因我行为美元清算行，因此对金额并无特别限制，但大额美元汇出还需先联系省行支付清算部确定是否有头寸。"],["浦发银行","瑞士法郎","2万","14点","因我行为美元清算行，因此对金额并无特别限制，但大额美元汇出还需先联系省行支付清算部确定是否有头寸。"],["浦发银行","澳大利亚元","10万","10点","因我行为美元清算行，因此对金额并无特别限制，但大额美元汇出还需先联系省行支付清算部确定是否有头寸。"]]}]},{"title":"4.2.2境内直系（近）亲属外币互转","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料： 客户提供收付款人有效身份证件及账户、直系（近）亲属关系证明原件（境内居民：公证书、户口本、结婚证、近亲属关系承诺函等）"},{"kind":"paragraph","text":"填写单据：境内汇款申请书/跨境汇款申请书。"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image42.jpeg","image45.jpeg"]},{"kind":"paragraph","text":"二、操作流程"},{"kind":"paragraph","text":"联网核查","shape":true},{"kind":"paragraph","text":"通过使用交易码8005001 进\n行转账，并联动到申报页面","shape":true},{"kind":"paragraph","text":"提示客户在回单上签字，留存申报材料。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.转入及转出双方均为境内居民，须将双方的申报标示改为境内申报。填写境内汇款申请书(黄色)；\n2.其中一方为非居民，则只申报境内居民一方，境外居民一方不申报。(收款方为境外人士填写跨境汇款申请书(蓝色)，收款方为境内人士填写境内汇款申请书(黄色))；\n3.均为境外居民，两者选不申报；\n4.交易附言：外币(钞户/汇户)直系(近)亲属划转；\n5、申报录入交易编码 925010；交易金额；交易附言：外币(钞户/汇户)直系(近)亲属划转；\n6.认真审核亲属关系证明材料；\n7.境内个人与境外个人外汇账户间的资金划转仅限本人之间或与近亲属之间,按跨境交易管理，即境内个人账户转入境外个人当日累计≤50000美元，境外个人账户转入境内个人账户不限金额。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"交易回单第一联、《申请书》第一、四联，客户身份证及相关关系证明材料复印件（加盖复印无效章）留存传票；交易回单复印件、《申请书》第三联交后台申报；交易回单第二联、《申请书》第二联（绿色）交还客户。"}]},{"title":"4.2.3跨境汇款","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"1.客户可使用手机银行预填单，简化操作；"},{"kind":"paragraph","text":"2.旅游，机票，签证等；"},{"kind":"paragraph","text":"3.录取通知书、学生证等。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image46.png"]},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"收集材料并审核","shape":true},{"kind":"paragraph","text":"E49120 建模板","shape":true},{"kind":"paragraph","text":"21093 汇款","shape":true},{"kind":"paragraph","text":"55490打印汇款申请书、影像补扫","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.购汇用途与汇款用途需一致；\n3.集授提供身份证原件、卡原件、G04002账户资料截屏、联网核查、客户头像、反洗钱尽调截图、汇款用途证明资料。\n3.若收款地区为港澳台，需将电报费类型修改为港澳台。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.根据用途审核材料；"},{"kind":"paragraph","text":"2.操作要点：（1）全英文大写（2）根据收款国家有特殊要求。"},{"kind":"paragraph","text":"如图"},{"kind":"paragraph","text":"","images":["image47.png"]}]},{"title":"4.2.4 TT前台待修改（TT打印、查询）","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、汇款介质；"},{"kind":"paragraph","text":"填写单据：55490将境外汇款申请书打印出来客户签字。"},{"kind":"paragraph","text":"注意事项：\n若汇款待修改因客户原因造成，须联系客户持有效身份证及汇款介质前来我行办理修改或冲正手续。若为修改，如修改汇款用途、SWIFT代码等，因核心系统修改界面无法直接进行上述内容修改，需在打印出来的《境外汇款申请书》对印栏位备注正确汇款用途及银行代码，客户签字确认，提交集中授权；若为“网银需合规”退回前台待修改的，在审核客户汇款用途合理后，在《境外汇款申请书》空白地方备注：“页面未修改”及“经审核，该笔汇款符合合规规定，同意通过电子渠道汇出”字样，加盖经办及机构负责人签章；无论何种原因修改，均需先上传影像，重新提交交易至集中授权审核。该笔业务集中授权拍摄：联网核查、G04002截图、境外汇款申请书、客户头像、汇款介质、国际汇款借记通知书、55490修改前截屏。\n若汇款待修改非客户原因造成，可不联系客户，提供说明，将申请书打印后备注修改原因并经办复核双签提交55490进行修改。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"55490打印境外汇款申请书并给客户签字并补扫影像。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n该笔业务需进行远程集中授权。务必提前截图（联网核查、g04002截图、490截图、汇款申请书、客户头像、身份证件、卡、报文明细、55490修改前截屏）。","shape":true},{"kind":"paragraph","text":"55490点击修改，并修改相应汇款信息；若无法在该界面修改，须在汇款申请书上相应栏位备注修改内容后补拍影像提交。","shape":true},{"kind":"paragraph","text":"集授通过则完成该业务","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.若客户无法到网点来修改，可考虑冲正重新发起汇款。（冲正退回会占用客户汇款额度，需谨慎冲正）\n2.冲正方式：（1）若客户无法前来柜台，我行可电话联系客户，取得客户同意后进行冲正，提交《错账冲正申请书》，（需注明包括但不限于联系客户的时间、方式及“已于汇款人XXX联系，汇款人同意退回冲正”字样），并由柜员、内控经理（内控副职）或正职共同签字。（2）对于连续三个工作日无法联系客户，由柜员、内控经理（内控副职）或正职在《错账冲正申请书》上，注明（每个工作日一次，三次）新增包括但不限于联系客户的时间、方式及联系不上的原因，并共同签字确认。\n3.隔日冲正的，需要打印交易发生当日的DEPD9950报表作为冲正的附件。","shape":true}]},{"title":"4.2.5业务名称MT996转已读","children":[],"blocks":[{"kind":"paragraph","text":"一.操作流程"},{"kind":"paragraph","text":"","images":["image48.png"]},{"kind":"paragraph","text":"登录核心系统，使用代码\n55472","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"报文类型选择“MT996”，报文子状态选择“TBPR","shape":true},{"kind":"paragraph","text":"调阅报文明细，\n选择报文状态为已读","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.查询时删除交易日期与起息日期；（已读后查询该报文方式：删除日期，输入机构号，提交查询）\n2.最迟次日根据报文处理相应的 TI103、TI202 报文。","shape":true},{"kind":"paragraph","text":"三．业务完结注意事项"},{"kind":"paragraph","text":"1.将MT996状态更改为“已读”不代表柜员完成查复要求，完成相关处理，应同当日、最迟次日根据报文指示处理相应的MT103、MT202报文。"},{"kind":"paragraph","text":"2.在选择进入调阅报文明细相关页面后，应需注意先选择功能打印，打印该笔对应报文，并交予对应处理人员，避免报文处理遗漏现象。"}]},{"title":"4.2.6 55472汇入入账","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：作为薪酬收入——劳务合同（需注意合同有效时间）、身份证明等。"},{"kind":"paragraph","text":"作为生活费、赡家款——身份证明、亲属关系证明（如户口簿）等。 退学费、房租——租房合同/退学费证明、学生证/在校证明，护照等。"},{"kind":"paragraph","text":"图纸、软件版费——合同、往来邮件截图等。"},{"kind":"paragraph","text":"货款——网店订单流水、网店信息。"},{"kind":"paragraph","text":"必要时可提供情况说明加以辅助。"},{"kind":"paragraph","text":"注意事项：\n阅读报文判断无法直入账原因（常见：命中反洗钱关键词、金额超限）；\n联系客户询问该笔资金来源及汇入用途，并提供相应材料证明；\n判断入账是否符合条件（一类卡活期一本通账户）；\n判断报文收款人英文与核心是否一致。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"情况一：无法直入账原因为金额超限\n55472功能参数选择入账后一路提交上集授即可\n情况二：无法直入账原因为命中反洗钱\n.55472提交后将发起一笔反洗钱尽调\n须经办登录事中子系统填写尽职调查问卷后，复核后返回至柜台（该操作通常由条线人员操作）\n注意因汇率变动等原因，建议柜台经办收到该条信息后立马上集授，不然容易失败就要重新发起反洗钱尽调。","shape":true},{"kind":"paragraph","text":"55472入账","shape":true},{"kind":"paragraph","text":"事中子系统填写尽职调查问卷","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.汇入金额超过1万美元需要填写申报单；\n2.集授截图：G04003、490、MT103报文内容、、若报文中有明码需将明码转换界面截图，55472截图（显示无法直入账原因）、事中子系统问卷内容、客户提供的入账材料等。\n3.无法入账或客户无法提供相关材料的，需退报处理（参照支付清算一页纸操作且,需注明：已过名单筛查）","shape":true}]},{"title":"4.2.7 E83201行内外币汇入","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：申报单(若可直接入账)"},{"kind":"paragraph","text":"操作流程注意事项：\n1.班后查账环节83201发现来账，需进行处理；\n2.83201通常为港澳台地区账户汇入我行境内账户的人民币，原则上需在收到款项后的21个自然日内处理完毕。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image49.png"]},{"kind":"paragraph","text":"班后83201发现来账情况","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"判断该笔资金能否入账，是否需要提供材料并联系客户","shape":true},{"kind":"paragraph","text":"经办系统处理：\n可直接入账并手写申报单(功能参数：账号入账)\n不可入账与客户联系后退汇(功能参数：直接退汇)\n联系不上客户或需要其他信息发查询给对方银行。(功能参数：发出查询)","shape":true},{"kind":"paragraph","text":"联动到下一界面选择查询原因\n并提交打印回单","shape":true},{"kind":"paragraph","text":"入账成功后根据回单内容手写申报单并交与申报人员","shape":true},{"kind":"paragraph","text":"注意事项：\n1.港澳地区仅支持同名账户互转，每日累计不超过8万元人民币；\n2.台湾地区居民可向境内同名或不同名账户汇入每日累计不超过8万元人民币。","shape":true}]},{"title":"4.2.8外币钞转汇","children":[],"blocks":[{"kind":"paragraph","text":"一、客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、借记卡或活期存折。"},{"kind":"paragraph","text":"无需填单"},{"kind":"paragraph","text":"二、操作流程"},{"kind":"paragraph","text":"操作流程注意事项：\n1.客户有效身份证件、若为非居民需存为比对附件。外币业务代办需要提供委托书和代办人身份证件。\n2.前面选择货币类型为对应外币，前面子账户为对应钞户，后面收款账户子账户类型为5501个人储蓄和对应外币子账户汇户。\n3.客户在回单上写下“同意XX币钞转汇”，并签字确认","shape":true},{"kind":"paragraph","text":"执行交易码1045/45，选择兑换","shape":true},{"kind":"paragraph","text":"打印回单并交客户备注签字","shape":true},{"kind":"paragraph","text":"身份证件联网核查","shape":true}]},{"title":"4.2.9光票托收","children":[],"blocks":[{"kind":"paragraph","text":"客户环节"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"1.本人有效身份证件原件："},{"kind":"paragraph","text":"（如委托代办，还应出具委托书，直系亲属关系证明原件、办理人员身份证原件等。）"},{"kind":"paragraph","text":"2.我行借记卡或活期存折，若未带可通过核心系统查询记下；"},{"kind":"paragraph","text":"3.托收的支票原件（客户本人在支票背面签名）；"},{"kind":"paragraph","text":"填写单据：填写完整的《光票托收申请书》，需要客户签名（收款金额超过等值1万美元，需填写《涉外收入申报单》）。"},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"1.提示码选择“AF对私光票托收”手续费内扣的，无需远程授权，可直接打印TY04（两份）交由客户签名后收回。\n2.提示码选择“NF免费”手续费外收的，需远程授权，将身份证件核查截屏资料、客户证件、客户头像、卡/折（如有）、票据正反面、光票托收申请书逐一拍照后提交授权。最后通过21035现金收费或74/1074有折/无折收费，收费有两项——（1）个人光票托收手续费—光票托收（2）对私邮费。","shape":true},{"kind":"paragraph","text":"审核材料①","shape":true},{"kind":"paragraph","text":"核心交易码58060“卡片托收入口”②","shape":true},{"kind":"paragraph","text":"整理材料③","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①审核支票各要素的完整性、出票日期（无特别备注的，有效期一般为6个月）\n②逐项输入必填要素：票据号码、货币（需与客户确认）、金额、票据类型（1.支票）、出票日期、付款人名称(如出票人为两人或以上，输入时请用逗号隔开；如出票人为澳门政府，出票人输入票上完整的中文名称，而非票上的葡萄牙语格式)、付款行全称、付款人国家/地区（需与客户确认）、收费账号（此项为可选项，可刷卡或手输账号，如为手续费外收则此栏可不填，点击“户名回显”）、货币与子账户类别均为人民币、提示码（选择“NF免费”或“AF对私光票托收”）、收款人账号（刷卡或手工输入，点击“户名回显”；如收款人为两人或以上，需要收款人同时到场，只能入一人账，需要另一人在申请书上写同意将所有款项打入X账户，并签字确认）、产品类型（5501）、产品子类（根据币别选择，皆为汇户）、申报标识（默认为“1：跨境申报”），其他栏位无需填写。(所有出票人和地址类信息需要输入完整，不要简写；如只是金额不同，票号不同，其他信息完全相同时，可用多张录入功能，节省时间)\n③1.整理传票：光票托收业务回单TY04第一联、光票托收申请书第二联（红联）、手续费回单（如是外收）第一联；2.提交后台：光票托收业务回单TY04第二联、光票托收申请书第一联（白联）、托收票据加盖划线章；3.其余交客户。","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图："},{"kind":"paragraph","text":"","images":["image50.png"]},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.提示客户入账时间：正常情况下，金额小于1万美元为31个自然日；金额大于等于1万美元为45个自然日（港币均为31个自然日，加元、澳元等个别币种均需45天，如遇节假日或疫情等特殊情况入账时间有可能存在顺延）。"},{"kind":"paragraph","text":"2.告知费用：人民币5万元以下（含）均为人民币60元【光票托收费用50元+对私邮费10元】；超过等值人民币5万元的为60—260元（光票托收费用按照等值人民币的1‰收取，50—250元+对私邮费10元）；另，达到1万美元安全托收需要国外行扣付5美元后入账；澳门元需要扣付40澳门元后入账；加元需由国外行扣付10加元后入账；可视情况与客户进行相应提示。"},{"kind":"paragraph","text":"3.内扣/外收，选择收费时，需审核支票的出票国家。例如，2张支票同为美国境内的情况，手续费只收1笔，因此在选择收费时，务必选择外收手续费，以防误收。"},{"kind":"paragraph","text":"4.我行不予受理的票据：非自由兑换货币的票据；表面注明流通地区限制的票据；持各种单据的影印件办理托收和咨询业务；陌生的、异常的大额票据（如金额大于10万美元的美国出具的光票）、出票行资信有疑问的票据、资信有疑问的客户委托的票据；用于投资、贷款或抵押等目的的大额票据；抬头人为个人且已背书转让的票据。"}]}],"blocks":[]},{"title":"4.3外币解付","children":[{"title":"4.3.1西联签约及解约","children":[],"blocks":[{"kind":"paragraph","text":"A.西联签约"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料： 客户有效身份证原件；借记卡"},{"kind":"paragraph","text":"填写单据： 西联签约申请表"},{"kind":"paragraph","text":"操作流程注意事项：\n注意审核签约申请表是否填写完整规范。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"登录核心，联网核查\nE42308客户签约维护—刷卡，维护方式选择签约，将客户信息录入","shape":true},{"kind":"paragraph","text":"客户填写西联签约申请表","shape":true},{"kind":"paragraph","text":"提示客户在回单上签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.信息录入准确即可\n2.手机银行解付过程中会联动签约，首选手机银行解付。","shape":true},{"kind":"paragraph","text":"B.西联解付"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件； 借记卡或活期存折（储蓄户、结算户都可以）；"},{"kind":"paragraph","text":"填写单据：西联收汇单，《个人跨境汇入汇款客户调查问卷》"},{"kind":"paragraph","text":"操作流程注意事项：\n收汇单填写完整。（需要求客户填写正确的收汇款人姓名<英文>，收汇款人母姓等相关信息，保证其填写各项要素完整）","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"客户填写西联收汇单","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n在填写收汇单时需要求客户填写正确的收汇款人姓名<英文>，收汇款人母姓等相关信息，保证其填写各项要素完整。","shape":true},{"kind":"paragraph","text":"登录核心，联网核查\nE42301办理解付","shape":true},{"kind":"paragraph","text":"提示客户在回单上签字","shape":true},{"kind":"paragraph","text":"业务完结注意事项"},{"kind":"paragraph","text":"若客户需要结汇，可引导至智能柜台、手机银行或者柜台操作。（若引导至非柜面渠道，注意对接大堂人员。）小额外汇可引导客户使用微信公众号“WesternUnion西联”直接解付人民币到账，。"}]},{"title":"4.3.2西联解付异常处理","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件及正确解付码"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"联网核查确认证件真实有效","shape":true},{"kind":"paragraph","text":"通过 E42301 解付交易确认解付异常情况。并确认解付码是否正确。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n在收款人信息出现不一致的情况下还需注意，除出现姓和名倒置情况导致的收款人英文姓名与汇款人所填写的不一致情况外，其余若出现收款人英文姓名与汇款人所填写的不一致情况，不可直接告知客户错误姓名，易导致风险。","shape":true},{"kind":"paragraph","text":"根据解付异常情况分别可通过：1、让收款人联系汇款人更正汇款信息2、银行电联西联公司以上两个途径处理。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.涉及反洗钱原因的，通过反洗钱系统确认后即可办理；\n2.汇款方导致的收款信息有误可要求客户联系汇款前往西联修改；\n3.西联公司准备金不足的解付异常，由银行端联系西联公司处理；\n4.其他原因的需联系西联公司确认后处理；\n5.系统提示该笔业务已在其他渠道解付中，那么请稍等几分钟后再尝试。西联公司电话：4009196747(需询问后台我行网点号)","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"常见电子渠道解付失败原因"},{"kind":"paragraph","text":"1）收款人英文姓名与汇款人所填写的不一致（姓和名倒置情况），需客户自行联系汇款人重新汇款（除出现姓和名倒置情况导致的收款人英文姓名与汇款人所填写的不一致情况外，其余若出现收款人英文姓名与汇款人所填写的不一致情况，不可直接告知客户错误姓名，易导致风险）"},{"kind":"paragraph","text":"2）收款人或汇款人姓名命中反洗钱名单，需至反洗钱事中子系统查询所有名单识别客户是否“真中”，若“误中”名单，可进行入账。"},{"kind":"paragraph","text":"3）若系统提示异常处理，请查询异常处理原因。则在E42302中查询异常原因，将报错界面截屏，并填写西联解付异常情况书一起发于西联官方邮件，西联通常会在接收到邮件的48小时内回函，并给予新的解付码。届时客户自行电子渠道解付即可。"},{"kind":"notice","text":"（西联邮件的要求一般后台会留有副本）","images":[]}]}],"blocks":[]}],"blocks":[]},{"title":"5.投资销售","children":[{"title":"5.1贵金属","children":[{"title":"5.1.1吉祥金销售","children":[],"blocks":[{"kind":"paragraph","text":"一、客户环节"},{"kind":"paragraph","text":"1、账户人、代办人有效身份证件(积存金业务代办要出具合法的公证委托书)"},{"kind":"paragraph","text":"2、借记卡或活期存折"},{"kind":"paragraph","text":"二、常用销售交易码"},{"kind":"paragraph","text":"","images":["image51.png"]},{"kind":"paragraph","text":"三、贵金属提金流程"},{"kind":"paragraph","text":"1、审批表（如（1）50g以上提金且取现帐户近6个月存在可疑管控记录；（2）单笔取现50万元（含）以上等值黄金。）"},{"kind":"paragraph","text":"2、填写个人大额投资金交易尽职调查问卷（50g以上提金）。"},{"kind":"paragraph","text":"3、填写中国银行股份有限公司实物贵金属业务加强尽职调查表"},{"kind":"paragraph","text":"（1）非原始购买人回购；"},{"kind":"paragraph","text":"（2）大额现金购买（单日累计5万、30日累积20万）；"},{"kind":"paragraph","text":"（3）积存金改绑清算帐户；"},{"kind":"paragraph","text":"（4）跨网点积存提取（提金机构是否为客户的积存开户机构，或客户在5年内是否在提金机构有过积存购买记录。如都没有，需进行强化尽调。；"},{"kind":"paragraph","text":"（5）不涉及上述场景，但拟办理实物贵金属业务的客户为D/E级，或其他需尽调情况。"},{"kind":"paragraph","text":"4、目前强化尽调调查功能已嵌入核心系统，尽调在交易前后录入均可（提交集中授权前完成尽调），如触发上述尽调场景，但未进行尽调或尽调类型或尽调内容错误，则交易失败。如办理了尽调，但是“尽调通过标识”选择了2-不通过，则交易也失败。"},{"kind":"paragraph","text":"5、积存金提取：贵金属积存交易申请单"},{"kind":"paragraph","text":"四、操作流程注意事项："},{"kind":"paragraph","text":"1．需集中授权（集授：联网核查+账户资料+交易画面（有显示数量的）+介质+人像；积存金提取（贵金属积存交易申请单））。"},{"kind":"paragraph","text":"2.注意需填写吉祥金编号打印客户反洗钱风险等级，并在屏打的单子上备注“已复核”，经办复核双签）。"},{"kind":"paragraph","text":"。"},{"kind":"paragraph","text":"3.注意销售渠道区别，实物销售需录入金条编号。"},{"kind":"paragraph","text":"4.付款方式为非直连，上传客户签字的POS刷卡单；付款方式为BGL扣款，填写《8492BGL应付暂收凭证》"},{"kind":"paragraph","text":"5.集授通过后的金价为实际交易金价，应提前与客户说明。"},{"kind":"paragraph","text":"6. 积存金跨网点提取是指查询积账户归属网点，非账户开户网点。可通过E61626积存金帐户信息管理进行查询。"}]}],"blocks":[]},{"title":"5.2理财","children":[{"title":"5.2.1国债","children":[],"blocks":[{"kind":"paragraph","text":"5.2.1.1凭证式国债申购"},{"kind":"paragraph","text":"一．客户环节"},{"kind":"paragraph","text":"1.本人办理：客户携带有效身份证原件、借记卡/活期存折（如有）。"},{"kind":"paragraph","text":"2.委托办理：代理人与被代理人两人身份证件原件、借记卡/活期存折（如有）。"},{"kind":"paragraph","text":"3、建立客户关系：①本人认购：没有客户号的投资者，需填写《个人开户及综合服务申请表》，采集客户基本信息，在核心银行系统建立客户号并按规定完成客户尽职调查工作；已有客户号的投资者，应与客户核对留存客户信息的有效性。②代办认购：对于代理人无我行客户号的，应通过《个人开户及综合服务申请表》采集代理人信息，在核心系统中创建临时客户号并录入客户信息；对于代理人已有我行客户号的，应与代理人核对留存信息。"},{"kind":"paragraph","text":"审核环节注意事项：\n1.注意区分三年、五年的国债债券代码；\n2.提示客户凭证式国债收款凭证妥善保存；\n3.可用E02067 日债额度查询，查询是否还有额度可以购买。 4、开立储蓄国债，资金账户须为本省账户。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"1.注意区分三年、五年的国债债券代码。\n2.提示客户凭证式国债收款凭证妥善保存\n3.购买前先用 E02036 日债额度查询，查询是否还有额度可以购买","shape":true},{"kind":"paragraph","text":"现金认购E02046；转账认购E02047。输入客户号、债券代码、交易面额、《中华人民共和国储蓄式国债(凭证式收款凭证》凭证号。","shape":true},{"kind":"paragraph","text":"尽职调查：对客户交易强化尽职调查，并在认购业务传票上记录“已尽调”；如为持有现金购买，应参照存款业务要求，填写当前有效的《个人大额现金存、取款业务尽职调查问卷》。存在大额或在当日现金认购以现金兑取后立即取现的应开展强化尽职调查，无法排除可疑的应上报可疑交易线索。","shape":true},{"kind":"paragraph","text":"提交打回单，联动后打印凭证式国债","shape":true},{"kind":"paragraph","text":"后台核准复核后，递交客户国债凭证","shape":true},{"kind":"paragraph","text":"提示：凭证式国债约定转存签约E02061"},{"kind":"paragraph","text":"凭证式国债约定转存凭证收回E02064"},{"kind":"paragraph","text":"","images":["image52.png"]},{"kind":"paragraph","text":"","images":["image53.png","image54.png","image55.png"]},{"kind":"paragraph","text":"5.2.1.2电子式国债申购"},{"kind":"paragraph","text":"一．客户环节"},{"kind":"paragraph","text":"1.本人办理：客户携带有效身份证原件、借记卡/活期结算账户。"},{"kind":"paragraph","text":"2.委托办理：代理人与被代理人两人身份证件原件、借记卡/活期结算账户。"},{"kind":"paragraph","text":"3、建立客户关系：①本人认购：没有客户号的投资者，需填写《个人开户及综合服务申请表》，采集客户基本信息，在核心银行系统建立客户号并按规定完成客户尽职调查工作；已有客户号的投资者，应与客户核对留存客户信息的有效性。②代办认购：对于代理人无我行客户号的，应通过《个人开户及综合服务申请表》采集代理人信息，在核心系统中创建临时客户号并录入客户信息；对于代理人已有我行客户号的，应与代理人核对留存信息。"},{"kind":"paragraph","text":"审核环节注意事项：\n1.注意区分三年、五年的国债债券代码；\n2.可用 E02067日债额度查询，查询是否还有额度可以购买。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"E02020托管账户开户。本交易用于投资者开立国债托管账户，并与投资者的资金账户进行关联，资金账户必须是凭密码支取的个人结算账户。开户后，我行向投资者提供“储蓄国债托管账户本”（E02026），记录投资者国债交易信息，托管账户本不作为重要空白凭证管理。","shape":true},{"kind":"paragraph","text":"E02027电子式国债认购。输入客户号、债券代码、交易面额。","shape":true},{"kind":"paragraph","text":"对客户交易强化尽职调查，并在认购业务传票上记录“已尽调”。","shape":true},{"kind":"paragraph","text":"交易成功后输出：打印TY04业务传票，中华人民共和国储蓄国债（电子式）认购确认书。","shape":true},{"kind":"paragraph","text":"5.2.1.3凭证式国债兑付"},{"kind":"paragraph","text":"一、客户环节"},{"kind":"paragraph","text":"1.本人办理：客户携带有效身份证原件；需要兑付的《中华人民共和国储蓄式国债(凭证式)收款凭证，如选择转账兑付时还需客户提供我行的借记卡/活期结算存折。"},{"kind":"paragraph","text":"2.委托办理：账户人和代办人的有效身份证原件。需要兑付的《中华人民共和国储蓄式国债(凭证式)收款凭证，如选择转账兑付时还需客户提供我行的借记卡/活期结算存折。"},{"kind":"paragraph","text":"操作流程注意事项：\n需告知客户国债提前兑付，系统会内扣手续费，手续费标准是千分之一。\n凭证式国债发行期内可以提前兑取（发行期最后一天（19日）不可办理提前兑付）。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"身份核实：居民身份证进行联网核查，其他证件通过其他有效方式进行核实，代办情况应核实双方证件。\n2、实时核实：代办情况应通过系统预留方式进行电话实时核实，并在传票上记录。","shape":true},{"kind":"paragraph","text":"3、国债提前兑取/兑取交易码E20251。输入账号、凭证类型(7009)、凭证号，选择支取方式(凭密码支取)(兑付为提前兑付或到期兑付）（与定期存款不同，国债不存在到期自动转存情况，到期即为到期兑付，提前即为提前兑付）","shape":true},{"kind":"paragraph","text":"4、凭证收回要求：国债收款凭证盖作废章，提前兑取时凭证背面记录购买人及代办人。\n5、可疑情况：存在大额或当日现金认购后以现金兑取后立即取现的应开展交易强化尽职调查，无法排除可疑的应上报可疑交易线索。","shape":true},{"kind":"paragraph","text":"提交打回单","shape":true},{"kind":"paragraph","text":"5.2.1.4电子式国债兑付"},{"kind":"paragraph","text":"一、客户环节"},{"kind":"paragraph","text":"1.本人办理：客户携带有效身份证原件；如选择转账兑付时还需客户提供我行的借记卡/活期结算存折。"},{"kind":"paragraph","text":"2.委托办理：账户人和代办人的有效身份证原件。如选择转账兑付时还需客户提供我行的借记卡/活期结算存折。"},{"kind":"paragraph","text":"","images":["image56.png"]},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image57.png"]},{"kind":"paragraph","text":"","images":["image58.png"]},{"kind":"paragraph","text":"","images":["image59.png"]},{"kind":"paragraph","text":"","images":["image58.png"]},{"kind":"paragraph","text":"","images":["image60.png","image58.png"]},{"kind":"paragraph","text":"","images":["image61.png"]}]},{"title":"5.2.2三方签约、解约、变更","children":[],"blocks":[{"kind":"paragraph","text":"1.客户申请：客户本人有效身份证原件。香港，澳门居民应提供港澳居民来往内地通行证原件。台湾地区居民应提供台湾居民来往大陆通行证原件。获得中国永久居留资格的境外自然人应提供外国人永久居留证原件。借记卡(支持单芯片卡)，《个人综合服务信息变更申请书》，与我行，证券公司签订的三方服务协议。 风控提示：第三方存管个人客户的银证转账开通，变更手续，关联借记卡变更，查询等业务必须由本人办理，不得代办，关联借记卡账户，证券保证账户的客户资料必须相符。 2.资料审核：（1）客户申请开通我行第三方存管服务前，应在证券公司开立证券资金账户，客户选择的证券公司限于与我行签订第三方存管合作协议的证券公司；根据我行与证券公司的约定，通过证券公司线上渠道(网上开户系统，手机app等)签署电子版三方服务协议并开通第三方存管服务的客户，我行与证券公司不再要求客户签署纸质版三方服务协议。（2）身份核实并签署三方协议，以及与所提供资料的一致性。"},{"kind":"paragraph","text":"3.1开户（E15241入口）E152411个人客户台账开立：（1）点击第三方存管项下\"E15241个人客户台账开立\"；（2）系统提示刷磁条卡或IC卡或人脸识别选卡；（3）输入证券资金账号，选择证券公司代码。 3.2开户（E15241入口）E152412个人客户台账开立：（1）核对核心系统返回资料与第三方存管系统返回资料的正确性、选择\"确认\"点击提交完成开户业务。（2）打印开户确认单，经客户签字确认后随传票保管。"},{"kind":"paragraph","text":"4.1个人客户变更卡号(E15242入口）E152421个人客户变更卡号：（1）确定客户本人，身份联网核查无误；（2）认真核对新卡卡号，输入证券资金账号，证券公司代码的正确性。"},{"kind":"paragraph","text":"4.2个人客户变更卡号(E15242入口）E152422个人客户变更卡号：（1）人工核对核心系统返回资料与第三方存管系统返回资料的正确性。（2）如果客户信息不一致，信息将显示在\"提示信息\"栏位。（审核是否为本人办理）"},{"kind":"paragraph","text":"5.1个人客户台账资料查询(E15243入口）E152431个人客户台账资料查询：（1）在查询方式栏位选择：\"0-根据借记卡号查询、1-根据证券资金账号查询”；（2）核对输入的资料正确性提交联动到E152432。"},{"kind":"paragraph","text":"5.2个人客户台账资料查询(E15243入口）E152432个人客户台账资料查询：全栏位回显，打印个人客户台账资料。"},{"kind":"paragraph","text":"6.凭证打印：打印凭证"},{"kind":"paragraph","text":"7.档案保管：客户申请及打印后的凭证随当日传票保管。"},{"kind":"paragraph","text":"特殊事项 一，第三方存管业务的营业时间 在证券交易日可以办理第三方存管开户，转账，查询，变更等业务。可办理银证转账，台账查询，余额查询的营业时间一般为9:00-15:00，具体视各证券公司的情况而定。可办理第三方存管开户，变更业务的营业时间一般为9:00-15:00. 二，关于电话银行 从P603批次开始，新签约客户不再要求开立电话银行；所有金融，非金融交易均不再校验银行端密码。 三，怎样办理撤销第三方存管服务 目前撤销第三方存管服务只能到证券公司营业部进行办理。60700交易是取消外围系统在核心的标识，并非真正进行第三方存管的销户。 四，办理客户资料变更的重要性 如您变更姓名，身份证件类型和号码等重要身份资料，需要到银行办理客户信息的变更手续，然后再至证券营业部办理证券资金账户客户信息的变更手续。因未能及时办理变更手续，银行和证券公司双方记录的信息不一致时，有可能影响您的转账交易。 五，投资B股业务是否需要办理第三方存管 目前第三方存管服务只提供人民币资金的转账。B股资金(美元，港币)的划转可以通过我行的柜台8股转账业务办理。 六，是否允许代办 第三方存管开户不允许他人代办"},{"kind":"paragraph","text":"七，是无计代办 第三方存管开户不允许他人代办 八，申请开通第三方存管服务的前提 客户申请开通我行第三方存管服务前，应在证券公司开立证券资金账户。客户选择的证券公司限于与我行签订第三方存管合作协议的证券公司。"},{"kind":"paragraph","text":"6.电子渠道"},{"kind":"paragraph","text":"6.1电子账户开、销、变"},{"kind":"paragraph","text":"6.1.1卡关联电子渠道【更新人：】"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、本人借记卡；"},{"kind":"paragraph","text":"填写单据：变更申请书。"},{"kind":"paragraph","text":"客户环节注意事项：\n①确认客户证件是否真实有效；客户携带的借记卡是否为该证件项下开立的。\n②变更申请书填写内容：姓名、手机号、客户签名、备注栏位（填写卡与账户关联）。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"核查客户证件","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①通过E38010或者E38011（需要手工存为对比附件）证件进行联网核查，核实证件的真实性和有效性。\n②通过G04002(需要本地授权)或者G04003核实该借记卡是否为该证件项下开立的。\nA.非本人借记卡，业务拒绝办理\nB.同名、但非该证件项下开立借记卡，需要进一步核实是否可以更改证件类型后再进行后续操作，否则业务终止。\n③核实是本人证件项下开立的借记卡，操作8103314，读取借记卡芯片，客户输入卡密码，提交后，将e-Channel栏框中第一行的关联和默认账户下面的方框打钩。\n④提交后打印TY04,客户在凭证空白处签字即可。","shape":true},{"kind":"paragraph","text":"确认借记卡是否本人该证件项下开立的","shape":true},{"kind":"paragraph","text":"通过8103314执行开通交易","shape":true},{"kind":"paragraph","text":"提交打印并签字","shape":true},{"kind":"paragraph","text":"6.1.2手机银行开立、销户及同步【更新人：】"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"1、客户提供本人有效身份证件。（16周岁至18周岁(不含)无收入证明需监护人代办，16周岁以下原则上不办理）"},{"kind":"paragraph","text":"2、部分业务需提供本人有效借记卡/活期存折/信用卡（存折、信用卡可开通但不建议使用，部份功能将受到限制。）"},{"kind":"paragraph","text":"填写单据："},{"kind":"paragraph","text":"1.开通电子银行需填写：《个人账户开户及综合服务申请书》《电子银行风险提示书》（填写姓名、手机号码、需要开通的产品，认证工具选择（根据客户需求）"},{"kind":"paragraph","text":"2.电子银行其他业务填写：《个人综合服务信息变更申请表》电子银行业务变更部分。"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image2.jpeg","image62.png","image63.jpeg"]},{"kind":"paragraph","text":"操作流程注意事项：\n1.相关内容是否填写准确、完整；\n2.新开手机银行限额填写至开户申请书。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"联网核查客户证件真实有效，确认借记卡是否有关联手机银行，新开手机银行需进行手机实名制核验","shape":true},{"kind":"paragraph","text":"联网核查后\n新开通过：G04001/S001/E20201办理手机银行开通业务，若客户已有网银可通过E20226个人渠道开通，同时通过E20256进行限额。\n销户通过：E20226，选择关闭手机银行\n若客户需关闭电子银行则通过E20245\n同步通过E20207客户证件信息同步\nE200315E-TOKEN 同步\nE50008 CA信息更新","shape":true},{"kind":"paragraph","text":"提示客户在回单上签字，如有认证工具需主管复核，并由主管递交工具。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.注意证件是否有效，联网核查三张照片是否一致；\n2.除监护人代办外，其他均不允许代办；\n3.需要进行合理限额；\n4.确认客户意愿是否仅关闭手机银行还是关闭整个电子渠道；\n5.若仅关闭手机银行需刷介质。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.确认客户所有认证工具是否均同步成功。"},{"kind":"paragraph","text":"2.如有绑定认证工具，须通过交易回单确认是否绑定成功，且需复核"},{"kind":"paragraph","text":"6.2认证工具开、销、变"},{"kind":"paragraph","text":"6.2.1预植证书相关业务【更新人：】"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、介质。"},{"kind":"paragraph","text":"客户环节注意事项：\n1.G04002查看客户是否开立手机银行，若未开立，可在执行G04001开立手机银行时同时配发预植证书，此操作可不上集中授权。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"核查、查看账户状态\n填写个人电子银行风险提示、变更申请书/开户申请书","shape":true},{"kind":"paragraph","text":"E50009 个人客户预植证书查询，使用客户号查询客户前期是否配发过预植证书","shape":true},{"kind":"paragraph","text":"执行 E50001个人客户预植证书申请、提交集授(核查、G04002、客户人像、介质、开户申请书或变更申请书（备注预制证书号码）)","shape":true},{"kind":"paragraph","text":".E50005个人客户预植证书更换提交集授(核查、G04002、客户人像、介质、-变更申请书、原预植证书信息)\n;","shape":true},{"kind":"paragraph","text":"执行+E20214 CA证书绑定","shape":true},{"kind":"paragraph","text":"付key（需主管复核递，需客户本人拿KEY）","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.截图：联网核查、G04002；\n2.E50000个人客户预植证书申请/E50005个人客户预植证书更新（预植证书过期更新且原Key有在）/E50004个人客户预植证书更换；\n3.绑定前通过E50009查询预植证书号码【截图】，连续授权；\n4.注意业务操作期间预植证书收费政策（目前是全免费）。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"新申请预植证书：付Key时由核准付出；重新配发预植证书的，让客户当场激活，若无法匹配可现场执行后续操作，部分客户会需要执行信息同步代码。"},{"kind":"paragraph","text":"7.其他增值业务"},{"kind":"paragraph","text":"7.1水电代缴"},{"kind":"paragraph","text":"7.1.1水电煤、有线电视委托代扣业务【更新人：】"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：办理人和代办人身份证原件、扣款介质。"},{"kind":"paragraph","text":"① 填写单据：福建省分行委托扣款申请表。"},{"kind":"paragraph","text":"","images":["image64.png"]},{"kind":"paragraph","text":"E03002生活缴费，输入信息(缴费)\nE03041个人委托代收，选择签约账号类型(委托代扣)","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：","shape":true},{"kind":"paragraph","text":"联动E0300202PCPS账单查询，查看用户信息(缴费)\n联动 E0304102，进入签约管理页面，首次签约点击新增(委托代扣)","shape":true},{"kind":"paragraph","text":"联动 E0300203PCPS 缴费支付，打印\n缴费凭证(缴费)\n联动E0304103，录入缴费信息，点击提交，联动E0304104，录入缴费用户号、日累计限额(默认50000)、是否永久生效、扣款频率(默认0001)(委托代扣)。","shape":true},{"kind":"paragraph","text":"显示缴费成功结果(缴费)\n联动E0304105PCPS代扣签约/修改/解约返回，今签约状态显示00-已签约，点击打印。在E0304102进入签约管理页面，可通过协议查看功能进行参数编辑，或进行解约。(委托代扣)","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.签约不可代办，解约可代办（代办需提供介质）；\n2.E0304102进入签约管理页面，参数编辑中仅可修改日累计限额、是否永久生效、扣款频率、签约账号、通知方式。\n3.签约时需查询客户信息是否完整，手机号栏位不为空，手机号栏位信息缺失将扣款失败。","shape":true},{"kind":"paragraph","text":"7.2保管箱"},{"kind":"paragraph","text":"7.2.1保管箱开立【更新人：】"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件；"},{"kind":"paragraph","text":"填写单据：开户申请书（个人开户及综合服务申请书）、保管箱个人客户准入审批表、个人客户保管箱租赁业务申请（变更/撤销）表、保管箱存放物品声明书、保管箱租箱合约、授权书（若需）"},{"kind":"paragraph","text":"操作流程注意事项：\n需客户本人办理。\n保管箱收费凭证需要3份、需审核是否有保管箱经办柜员、客户的签名。\n开户申请书上的地址信息需按照我行个人信息录入规范填写，职业信息要求完整准确且长度不少于四个汉字字符。\n开户前查询承租人及被授权人反洗钱风险等级，打印跟随当日传票。风险等级为D的准入神批表需上报分行条线审批，风险等级为E的准入审批表需上报省行条线审批。","shape":true},{"kind":"paragraph","text":"二、操作流程"},{"kind":"paragraph","text":"联网核查后，G04001创建客户号，联动到开通保证金账户（55170023）。","shape":true},{"kind":"paragraph","text":"1074（借记卡收费）或21035（现金前端收费）收取保管箱租金。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1、登陆核心系统，查询客户是否有客户号存在，若客户无客户号或名下有不可用客户号，可参考客户号开户开立业务以及客户号维护业务（代码8101100、8101200、8101301）。\n2、客户无客户号的情况下，使用G04001/S001，按照开户申请单上的信息创建客户号，且必须为正式客户号，临时客户号可开户但无法开箱。","shape":true},{"kind":"paragraph","text":"7.2.2保管箱保证金账户【更新人：】"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户有效身份证原件、保证金和租金"},{"kind":"paragraph","text":"填写单据：开户申请书（个人开户及综合服务申请书）。"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image65.jpeg","image66.png"]},{"kind":"paragraph","text":"图一 图二"},{"kind":"paragraph","text":"客户环节注意事项：\n1.确认客户证件是否真实有效；\n2.保证金和租金可通过取现或本人活期账户转账收取；\n3.开户单据需填写完整，地址职业等信息需合规。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"","images":["image67.png"]},{"kind":"paragraph","text":"联网核查，通过G04001执行开户交易","shape":true},{"kind":"paragraph","text":"核心操作界面：","shape":true},{"kind":"paragraph","text":"提交打印并提示客户签字","shape":true},{"kind":"paragraph","text":"通过1010/1045为新开立的保证金账户存入保证金。","shape":true},{"kind":"paragraph","text":"","images":["image68.png"]},{"kind":"paragraph","text":"核心操作界面：","shape":true},{"kind":"paragraph","text":"通过21035/1074收取租金","shape":true},{"kind":"paragraph","text":"8140813新增租约且联动到确认收租","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.储蓄账户项下选择新建，产品代码5517,0023，用途：储蓄，续存项下选择空白后提交。G04001交易需本地授权，提交前请先让复核人员审核。\n2.交易完整需点击提交进行打印，该交易无法补打。若提交后打印失败可通过ctrl+shift+R重印（信创版已无该功能）。\n3.根据客户开立的保管箱收取对应的保证金和租金，结束该笔交易后需打印并签字。\n4.保管箱保证金需大于保管箱租金。","shape":true},{"kind":"paragraph","text":"三．业务完结注意事项"},{"kind":"paragraph","text":"该笔业务为开立特殊账户，仅限于本人办理；"},{"kind":"paragraph","text":"提示客户回访电话及建立台账。"},{"kind":"paragraph","text":"7.3法院协助划拨存款【更新人：】"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料： 有权机关执法人员证件；文书、裁判文书、委托书"},{"kind":"paragraph","text":"填写单据： 登记《有权机关查冻扣登记簿》（目前核心9071911登记《有权机关查冻扣登记簿》，登记业务状态后让执法人员在柜外清签收。）"},{"kind":"paragraph","text":"二.操作流程","images":["image69.png"]},{"kind":"paragraph","text":"审核有权机关执法人员证件及\n相关文书、裁决书、委托书","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：","shape":true},{"kind":"paragraph","text":"登录核心，使用 409 查询账户余额、9079 查询账户冻结情况","shape":true},{"kind":"paragraph","text":"使用G06017 有权机关强制扣划","shape":true},{"kind":"paragraph","text":"使用 E96001 回执联上用印：用印前回执联备注完整（详见注意事项）用印后补扫影像","shape":true},{"kind":"paragraph","text":"归还回执联原件，请有权机关人员在《有权机关查冻扣登记簿》签字（核心9071911登记《有权机关查冻扣登记簿》，登记业务）","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n注意是否存在轮候冻结。轮候冻结指按冻结时间，第一个冻结的有权机关有权扣划，其余需要扣划的有权机关注明未能成功扣划的原因；\n解冻、扣划通知书、裁定书均需体现原冻结文号；\n扣划金额不能提取现金，只能转入有权机关指定账户。（特别注意：指定账户应为法院专用账户或法院指定的受害人账户，原则上不得其他无关账户）\n4. 柜台应据实填写回执，并于完成回执所载明的协助行为后向有权机关出具，不得在尚未协助前或协助过程中出具。为避免争议，回执上应注意写明已查询、冻结、扣划的金额及具体查询、冻结、扣划的时间（应具体到时、分、秒），经办复核双人签字确认。\n5、对于使用“9093借方部分冻结”交易进行超额冻结时，各行应在回执文书中准确填写“已冻结额”、“未冻结金额”及原因，注意“已冻结金额”应填写冻结时的账户实际余额（非核心系统“9093借方部分冻结”交易的冻结金额），“未冻结金额”应填写有权机关要求的冻结金额与账户实际余额的差额，原因备注为“余额不足”，同时在回执空白处加注“我行将在冻结期内冻结上述账户可以冻结的存款，直至达到需要冻结的数额××元（含“已冻结金额”××元和“未冻结金额”××元）。”","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"扣划完成后，文书正本及回执联、裁决书、委托书、有权机关执法人员证件各复印2份。文书正本+裁决书+委托书+回执联（复印件）交由后台留底；文书正本（复印）+裁决书（复印）+委托书（复印件）+回执联（复印件）柜员留做传票。"},{"kind":"paragraph","text":"7.4非税缴款【更新人：】（建议更名为非税缴款）"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户携带行政处罚决定书①（福建省政府非税收入缴款通知书（该通知书手写无效）或缴款通知电子缴款码）、缴款介质或现金客户、有效身份证件。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"操作流程注意事项：\n确认客户处罚决定是联网或非联网，决定书上是否有其他事项和违约金。\n非税收入收缴（中央非税）20位缴款码号码（缴款码已升级为20位），使用E31103-应缴信息查询及缴费交易，输入20位缴款码或17位批次号，选择缴款方式，账户类型手工必选，下拉菜单中选择（1现金；2借记卡；3存折；4支票；5BGL;6一般缴款书）；借记卡、活期存折需刷卡刷折，选择支票时需在缴款账号/卡栏位输入支票等对应的实际账号，选择BGL时需在缴款账号/ 卡号栏位输入对应的实际账号，还应输入BGL账号及追踪号，实际缴款人全称，真实付款人账号开户行机构，使用9991002内部账号必须选择追踪号，选择现金时需输入实际缴款人全称。当客户进行大额现金缴款必须选择存款来源并输入用途说明。\n非税收入收缴（地方非税电子化）20位缴款码号码，使用E31204-应缴信息查询及缴款交易，输入20位电子缴款码，选择缴款方式，账户类型手工必选，下拉菜单中选择（1现金；2借记卡；3存折；4支票；5BGL;6一般缴款书）；借记卡、活期存折需刷卡刷折，选择支票时需在缴款账号/卡栏位输入支票等对应的实际账号，选择BGL时需在缴款账号/ 卡号栏位输入对应的实际账号，还应输入BGL账号及追踪号，点击“提交”到下一界面\n交易查询及回单补打（中央非税）使用E31104\n交易查询及回单补打（地方非税电子化）使用E31205\n该缴款交易无法冲正，缴款过程需认真核实缴款信息，避免发生差错。","shape":true},{"kind":"paragraph","text":"识别客户情况","shape":true},{"kind":"paragraph","text":"通过E31204进行缴款、E31103进行缴款","shape":true},{"kind":"paragraph","text":"7.5个人养老金【撰写人：】"},{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"审核材料：客户本人、有效身份证件原件；"},{"kind":"paragraph","text":"填写单据：个人综合服务信息变更申请表。"},{"kind":"paragraph","text":"填单图样：","images":["image70.png"]},{"kind":"paragraph","text":"操作流程注意事项：\n1.养老金销户目前暂支持零余额账户销户；\n2.若客户的养老金账户有余额申请销户，可在缴费完成后的5个自然日内申请撤回每个自然年可以撤回一次，(如果客户分多笔缴存，只能选择撤回其中1笔；只支持撤回当年发生的误缴费交易；如果客户是通过微信、支付宝等第三方支付零钱提现的方式产生的误缴费，柜员在执行E5500101“缴费撤回”环节，“转入卡号”必须正确填写客户本人借记卡号，“转入户名”必须正确填写客户姓名。否则转出资金将被微信或支付宝等第三方支付退回，最终撤回失败且无法再次发起撤回交易。)账户余额为0后方可为客户办理销户。(不建议主动与客户宣传)缴费撤回流程于序号②③④；\n3.对于超过5个自然日客户误缴费申请撤回销户，应上报分行，由总行报送人社局后续处理流程等待进一步通知。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"1.养老金账户销户流程","images":["image71.png"]},{"kind":"paragraph","text":"身份证(或其他有效证件)联网核查","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：\n①操作页面","shape":true},{"kind":"paragraph","text":"使用代码GO4003综合销户，解约外围关系，在G04003没办法解约的可通过60720一键解约","shape":true},{"kind":"paragraph","text":"使用 60662 确认外围签约关系是否全部解除","shape":true},{"kind":"paragraph","text":"确认所有外围关系关闭,使用代码E55001里销户①（通过本页面资金转出完成结息结清销户）\n8103313销卡","shape":true},{"kind":"paragraph","text":"养老金销户需注意在完成E55001里销户操作后，必须通过8103313进行销卡操作，完成上述两项操作养老金销户才算完成。"},{"kind":"paragraph","text":"2.缴费撤回流程","images":["image72.png"]},{"kind":"paragraph","text":"身份证(或其他有效证件)联网核查","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：","shape":true},{"kind":"paragraph","text":"使用E55001个人养老金开户引导\n点击“缴费撤回”①","shape":true},{"kind":"paragraph","text":"3、当前客户5自然日内的所有缴费记录回显，选择要撤回的缴费记录，点击“缴费撤回③","shape":true},{"kind":"paragraph","text":"页面④返显该笔缴费的元转入卡号和\n转入户名，确认无误提交，业务办理完成，打印回单，交客户签名。（务必核对卡号和户名的一致性，以免因入账失败导致错过撤回期限，引发客户投诉）","shape":true},{"kind":"paragraph","text":"现行规章制度参考文件：\n人社厅函【2023】119号","shape":true},{"kind":"paragraph","text":"7.6机构重空29155调入（核心无需此操作）及29156领用【撰写人：】"},{"kind":"paragraph","text":"一.所需资料"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"双人监控下清点所申领重空，确保账实相符"},{"kind":"paragraph","text":"（P2员工统一渠道）内操作：业务支持--集中运营服务--凭证业务--重空凭证调入—>核心内重空柜员领用—>机构尾箱扎库—>机构尾箱日结（确保机构尾箱日结清单本日余额为0）"},{"kind":"paragraph","text":"二.操作流程","images":["image73.png","image74.png"]},{"kind":"paragraph","text":"P2员工统一渠道--业务支持--集中运营服务--凭证业务","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：","shape":true},{"kind":"paragraph","text":"使用 29156办理机构重空用户领用业务，授权成功后打印回单。","shape":true},{"kind":"paragraph","text":"操作完成后，通过29168查询该重空是否成功领入重空柜员名下。（通过29170机构重空库存查询，确保机构库存为0）","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.P2员工统一渠道机构重空确认、重空管理员扎帐后记得打印传票","shape":true},{"kind":"paragraph","text":"三．业务完结注意事项"},{"kind":"paragraph","text":"1.P2员工统一渠道重空确认打印的传票与核心29156产生的传票需有对应"},{"kind":"paragraph","text":"2、上两步操作完成后，需当日通过29170查询机构是否存在在途重空。完成领入重空当日，需确保机构无在途重空。"},{"kind":"paragraph","text":"3、厂家直寄预制卡至网点"},{"kind":"paragraph","text":"4、员工统一渠道申领（部分卡种需先报个金部审批再申领）"},{"kind":"paragraph","text":"5、在员工统一渠道申领的借记卡以及社保卡邮寄至网点后，网点柜员执行29194将借记卡领入机构名下后使用 29156办理机构重空用户领用，邮寄单作为附件跟传票。"},{"kind":"paragraph","text":"","images":["image1.jpeg"]}]}],"blocks":[]}],"blocks":[]}],"blocks":[]},{"title":"常见对公业务","children":[{"title":"1.账户篇","children":[{"title":"1.1账户的开立","children":[{"title":"1.1.1对公开户（核准类、报备类）","children":[],"blocks":[{"kind":"paragraph","text":"1.核准类、报备类需要的材料：营业执照、法人身份证、授权书、经办人身份证、租赁合同或水电费缴费单或房产证等、章程、网银操作员身份证件、超25%股东证件（D风险以上10%）、预留印鉴、（分公司还需总公司相关材料）。"},{"kind":"paragraph","text":"2.填写单据：开立本外币单位银行结算账户申请书、授权书、对公客户信息表、单位综合服务协议签署表+银企对账+协议（两套盖骑缝章）建议删除+账户管理协议（盖骑缝章）、法律责任告知书、分级分类审批表、账户管理协议、网银风险提示、上门核实表、中国银行对公客户补充调查问卷（有跨境需求才需要）、企业电子银行服务收费标准及优惠措施。（价目表）。（注：对账不附属需要单独再签署一份对账协议"},{"kind":"paragraph","text":"","images":["image73.png","image74.png"]},{"kind":"paragraph","text":"工商系统、坚盾查询","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：","shape":true},{"kind":"paragraph","text":"H001开户，对公开户双录系统","shape":true},{"kind":"paragraph","text":"可通过E52210先进行人行系统开户报备，再通过E52005扫影像提交复审，注意材料完整性。","shape":true},{"kind":"paragraph","text":"人行系统报备（其中核准类需将材料送至人行，待人行通过后，再到人行拿开户许可证），复审上传开户许可证影像。","shape":true},{"kind":"paragraph","text":"风险点：①确认企业工商状态无异常；②存疑的，上门核实后开通非柜面交易或网银延时生效；③及时报备人行系统，避免人行处罚。"},{"kind":"paragraph","text":"开户过程注意事项：\n1.需与法人双录，法人无法到场的需远程视频核实。针对经营地与注册地均为异地企业办理开户过程中，除完成常规上门核实外，还需对法人完成面签《单位结算账户综合服务协议签署表》并留存照片。\n2.网银限额需完成限额审批流程，正确使用分级分类审批表。\n3.开户完成后，需让复核人员将网银认证工具交予客户并在单据上签字注明时间，网银密码通过短信发送至企业网银操作员手机，最后提示客户及时修改网银密码。\n4、针对存量客户，开户前需核查“已核对特定国家客户清单”，在开户申请书上注明，并双签。\n5、除开立基本户外，需先到人行系统查询无久悬账户存在。","shape":true}]},{"title":"1.1.2对公外币开户","children":[],"blocks":[{"kind":"paragraph","text":"外币结算账户开立"},{"kind":"paragraph","text":"一、客户环节"},{"kind":"paragraph","text":"审核材料：营业执照、开户许可证、经办、法人、大额确认人身份证、预留印鉴人身份证、公司章程、网银操作员身份证件、超25%股东证件、公章、法人章、预留印鉴章、外管局外汇业务登记凭证（资本项）"},{"kind":"paragraph","text":"填写单据： 开立本外币单位银行结算账户申请书、授权书、对公客户信息表、单位基本情况表、单位综合服务协议签署表+银企对账+协议（两套盖骑缝）建议删除+账户管理协议（盖骑缝章）、中国银行对公客户补充尽职调查问卷、法律责任告知书、网银风险提示两份"},{"kind":"paragraph","text":"操作流程注意事项：\n1.客户需在我行有人民币户才能开立外币户；\n2.确认客户开立经常项下还是资本项下外币户；\n3.资本项下外币户必须有外管局业务登记凭证，且开户前需先报备；\n4.需维护客户号项下客户英文名称、英文地址、及主要海外分支机构所在国家/地区信息。","shape":true},{"kind":"paragraph","text":"二、操作流程"},{"kind":"paragraph","text":"坚盾、案件查控平台查询可疑信息、涉案企业查询","shape":true},{"kind":"paragraph","text":"隔天外汇申报系统申报","shape":true},{"kind":"paragraph","text":"反洗钱与制裁合规系统","shape":true},{"kind":"paragraph","text":"扫描影像","shape":true},{"kind":"paragraph","text":"H00101(外币开户)","shape":true},{"kind":"paragraph","text":"8201200 维护证件信息","shape":true},{"kind":"paragraph","text":"ASONE/外汇管理局","shape":true},{"kind":"paragraph","text":"印鉴卡登记签收（客户带走的情况下）","shape":true},{"kind":"paragraph","text":"E52505 同步核心到期\n日、更新联系人信息","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.外币户开户无需法人双录，但需要和法人核实开户意愿；\n2.开外币户需申报，经常项：申报标识N/A，账户性质5007；资本项：申报标识为外管局业务登记凭证上的核准号；\n3.对账要关联；\n4.ASONE 打印跟档案。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.开户后需网银关联外币账户，一般都需要开通结汇、购汇功能；"},{"kind":"paragraph","text":"2.人民币户和外币户同一天开立的多留一套对账材料做集约对账签约维护。"}]}],"blocks":[]},{"title":"1.2账户的销户","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节","images":["image75.jpeg"]},{"kind":"paragraph","text":"客户环节注意事项：\n营业执照（或注销营业执照相关证明）、法人身份证、经办人身份证（均为原件）、单位公章、法人章、预留印鉴章、开户许可证。\n②《销户申请书》→申请书要加盖单位公章加法人章。附申请书填写范例。","shape":true},{"kind":"paragraph","text":"1.客户携带有效证件；①"},{"kind":"paragraph","text":"2.填写销户材料；②"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"查询客户在人行系统的账户情况①","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①a.查询对公客户在人行系统是否存在久悬账户。\nb.注销基本户前查询是否关闭所有的一般户。\n②查询账户是否被冻结，若存在冻结。则分为司法冻结和内部冻结（司法冻结我行无权解冻，内部冻结请结合实际情况操作解冻。）\n③利用G04503查询客户账户名下的所有签约关系（网银、印鉴卡、重空、外围）\n④a.H00221注销新版网银以及UKEY/E20198注销旧版\nb.60700解约外围签约关系（注意集团网银是做解除账户关联）\nc.G04503/29168注销客户名下的所有重空（若客户持有印鉴卡交回或遗失，则填写遗失/交回函、若客户无法交会转账支票等重空，则填写无法交会的函并按实际情况填写重要空白凭证状态变更申请表、结算卡请翻至结算卡板块。）\n⑤3045/E33101转账结清；3060现金结清\n⑥E52212账户撤销申请","shape":true},{"kind":"paragraph","text":"查询账户状态②查询账户核心的签约关系③","shape":true},{"kind":"paragraph","text":"分步注销账户产品、外围④","shape":true},{"kind":"paragraph","text":"结清账户余额后关户⑤","shape":true},{"kind":"paragraph","text":"三.要点提示："},{"kind":"paragraph","text":"销户完成后，将材料上传复审和人行⑥","shape":true},{"kind":"paragraph","text":"1.客户无法提供法人身份证原件的，应在办理前双人上门核实、或者使用“见证通”产品，因特殊原因无法提供的，账户行应将相关情况逐级上报至二级行或直属行审批。经审批同意后，可先凭证件复印件办理销户手续，销户后一个月内必须采取自行上门或委托其他机构核实证件原件及其真实性。"},{"kind":"paragraph","text":"2、 账户销户处理场景（关于不同场景下解除隔离后账户风险防控及销户合规操作指引20231218版）"},{"kind":"paragraph","text":"（1） 首先强调任何场景下，都应严格把控销户资金支取风险："},{"kind":"paragraph","text":"①原则上应采取转账形式（如3045交易码）办理销户，确保资金去向可追溯；销户资金原则上仅可转至以下账户中：基本户（所销账户为非基本户情况）、其上级法人（例如分公司转母公司）或主管单位账户、根据客户出具的股东会决议转入股东个人账户、以及根据上级管理部门批复等相关证明文件转入指定账户等（对于未指定转入账户的，原则上销户资金应转入其法人个人账户）。"},{"kind":"paragraph","text":"②若销户单位处于注吊销状态下，严禁在销户前为客户办理资金支取业务，防止出现“为身份不明客户提供服务”违规情况，遭受监管处罚。"},{"kind":"paragraph","text":"（2）关于销户不同场景下处理情况"},{"kind":"paragraph","text":"因行政事业等非企业客户管理部门不同且要求不一致，下列以企业客户为例，非企业可参照执行，原则上应一事一议。各行在不同场景下处理请应根据属地化监管要求的不同作出相应调整。"},{"kind":"paragraph","text":"场景一：企业登记状态正常，可正常提供公章及预留印鉴"},{"kind":"paragraph","text":"该场景按正常销户流程进行处理，客户应提供法定代表人身份证件原件（非法人临柜办理需另行出具代办人身份证件原件）等、公章、授权书、预留印鉴章等材料办理销户。"},{"kind":"paragraph","text":"场景二：企业登记状态正常，账户余额大于1000元，公章及预留印鉴不全（缺一或均缺）"},{"kind":"paragraph","text":"应要求客户重新刻制印章，若涉及预留印鉴重刻的，则需先办理印鉴变更，之后按正常销户流程进行销户；若无法提供公章的，需提供印章注销/更换证明或登报记录。注意：根据印鉴管理相关规定，印章变更最早为次日生效，而非变更当日，账户行应立即送印鉴至建库部门办理变更，同时需要做好客户解释工作。"},{"kind":"paragraph","text":"场景三：企业登记状态正常，账户余额为小于或等于1000元，公章及预留印鉴不全（缺一或均缺）"},{"kind":"paragraph","text":"①原则上应要求客户对相关印章进行登报声明/提供印章注销证明（0余额账户可不要求登报；若仅法人章无法提供的且由法人办理的，则可不对法人章进行登报声明），出于风险及管理成本角度，可不要求客户办理印鉴变更。"},{"kind":"paragraph","text":"②经二级机构条线管理部门审批的《账户销户场景处理情况审批表》。"},{"kind":"paragraph","text":"③客户应出具《注销账户无法出具公章及预留印鉴签章说明函》及相关证明材料。"},{"kind":"paragraph","text":"④使用剩余印鉴在销户申请书及转账支票或结算业务申请书上盖章、验印（如仅剩财务章，则需对财务章进行验印）。该模式应要求法定代表人临柜办理；若非法人办理的，应参照“账户销户处理场景二”执行。"},{"kind":"paragraph","text":"补充：若当地人行对销户申请书盖章等材料有要求，应从其规定，例如：部分地区要求一定需登报，部分地区可仅凭银行出具说明即可。"},{"kind":"paragraph","text":"场景四：企业登记状态注吊销，但可正常提供公章及预留印鉴"},{"kind":"paragraph","text":"对于客户登记状态为注吊销证明文件问题：可使用其主管部门能出具相关内部系统证明文件（例如：工商内资登记表/行政许可决定书等）、或客户申请注销正常文件（回执等）、或打印主管部门官网查询记录截图作为其主证件。其余销户流程按照正常销户业务办理。"},{"kind":"paragraph","text":"场景五：企业登记状态注吊销，账户余额为小于或等于1000元，"},{"kind":"paragraph","text":"公章或完整预留印鉴缺一或都缺失"},{"kind":"paragraph","text":"参照“账户销户处理场景三”进行处理，要求法人进行办理，否则按“销户场景六”处理。"},{"kind":"paragraph","text":"场景六：企业登记状态注吊销，账户余额为大于1000元，公章及预留印鉴不全（缺一或均缺）"},{"kind":"paragraph","text":"①要求客户对相关印章进行登报声明/提供印章注销证明，无需重新刻制印章。"},{"kind":"paragraph","text":"②对于无法提供公章、预留印鉴中财务章、预留印鉴中公章/财务章/法人章以外其他章，上述三者情况之一的情况下，出具股东会决议（可采取上门亲见核实或经公证机关公证），或全体股东来我行办理并出具说明，上述股东决议或说明应声明无法提供完整章情况下销户申请材料及转账凭证上使用的印鉴及签字。对于股东确认问题，可调阅工商注吊销股权情况或经公证证明的股权证明。"},{"kind":"paragraph","text":"（若仅缺失预留印鉴中法人章的，可由法人来办理无需出具股东会决议等；非法人办理的则需要）。"},{"kind":"paragraph","text":"3、③经二级机构条线管理部门审批的《账户销户场景处理情况审批表》。"},{"kind":"paragraph","text":"④出具《注销账户无法出具公章及预留印鉴签章说明函》及相关销户材料。"},{"kind":"paragraph","text":"⑤使用支票或结算业务申请书进行转账，销户申请书及转账凭证上盖剩余有的印章并进行验印。"},{"kind":"paragraph","text":"特此说明：针对上述不同场景的处理，各行应审慎对待，应把控业务合规及风险可控原则；对于上述不同场景下处理要求可从严处理。"},{"kind":"paragraph","text":"非企业类账户在参考上述场景处置基础上，应更从严审慎对待。对于上述场景未涵盖的其他业务场景，原则上应一事一议，并取得上级行审批，账户行应按流程与相关部门做好沟通及审批工作。"}]},{"title":"1.3账户的变更","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"","images":["image76.png"]},{"kind":"paragraph","text":"注意事项：\n账户信息变更，应以系统比对结果为准，切不可依据客户所言（导致信息变更不充分）。\n为客户办理变更业务前，应确保企业外部信息无异常（工商是否异常、人行是否存在久悬）。\n部分重大事项的变更是否已完成上门核实（户名、法人、地址或其他条线规定需要上门核实的情形）。\n变更户名、法人、预留印鉴的需与新法人进行意愿核实；新法人为异地的，还需与原法人核实，原则上按照高风险客户进行非柜面限额管控建议改为原则上按照分级分类表进行非柜面限额管控（公转私日累计3万，公转公日累计10万）（建议删除）。\n5、涉及到印鉴变更，应先进行旧预留印鉴的比对并在新印鉴卡背面打印验印结果，比对通过方可变更印鉴；若旧预留印鉴遗失，应先做印鉴挂失（涉及公章、财务章遗失的还需登报声明）。","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"材料收集及审核①","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①按要求收集变更所需所有材料，审核客户填写的规范性及完整性，所有纸质材料双人审核并签章，有原件的还需加盖“复印件与原件一致”章；\n②企业相关人员是否已有客户号，相关人员的身份信息需联网核查并打印核查结果。\n③查询“国家企业信用信息公示”系统是否存在异常名录，并打印工商信息变更页；\n查询人行系统，是否存在久悬账户；若我行为一般户，还需要看二级人行系统基本户是否已变更。\n④8201301变更客户层信息（注意所有信息与工商比对，应变尽变。）；8201200查询受益人信息变更，要截图打印作传票。\n⑤E52002（E52005）复审账户信息变更：按实际需要对“账户基本信息”、“账户联系人”、“账户过账限制”、“印鉴卡”等信息进行变更；所有变更信息更改完成后需要将完整的变更材料上传影像，并同步“影像到期日”，后提交复审。\n⑥E52211输入相应信息，提交复审，向人行报备。","shape":true},{"kind":"paragraph","text":"确认客户企业人员信息②","shape":true},{"kind":"paragraph","text":"查询工商、人行、案防系统，并打印核查记录③","shape":true},{"kind":"paragraph","text":"客户层信息变更：8201301、8201200④","shape":true},{"kind":"paragraph","text":"账户层信息变更：人民币E52002、E52005\n（外币：E52502、E52505）⑤","shape":true},{"kind":"paragraph","text":"后续处理⑥","shape":true}]}],"blocks":[]},{"title":"2.结算篇","children":[{"title":"2.1现金存取业务","children":[{"title":"2.1.1对公现金缴存业务","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"1.审核材料：经办人身份证（超5万时提供）；"},{"kind":"paragraph","text":"2.填写单据：单位存款凭条。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"确定办理人员与公司关系","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：","shape":true},{"kind":"paragraph","text":"核查、登记办理人员身份信息","shape":true},{"kind":"paragraph","text":"审查填写单据，清点现金","shape":true},{"kind":"paragraph","text":"核心交易码：①1010;②8214105（集约）","shape":true},{"kind":"paragraph","text":"①1010：录入单据信息；②8214105：选择模板，扫描后提交","shape":true},{"kind":"paragraph","text":"打印回单交由客户签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①网点应首先判断所涉业务是对公业务还是对私业务：\n判断的主要依据是个人与对公客户的关系，以及个人代表谁办理业务。具体而言，如个人是对公客户的关联人，或员工代表对公客户办理业务，应判断为对公业务；如个人基于自身利益或诉求与对公客户发生交易，应判断为对私业务。不同的业务性质，需要适用不同的业务流程及尽职调查管理要求。对于对私业务按照总行个人数字金融部办理要求执行。\n②日常对公存现业务中有主要有以下三种场景\n场景1：办理人员已在对公客户层或产品层识别，包括法定代表人，及已在我行备案的财务人员、授权办理人员、单位结算卡持卡人或代办人等。\n场景2：办理人员能够出示对公客户出具的《单位结算账户相关业务授权书或介绍信等授权材料。授权材料应加盖公司印章，已明确说明可由指定人员办理现金存入业务，并提供办理人员身份信息。\n场景3：办理人员为我行与对公客户签订现金存入相关特定业务协议中指定的人员(即屈臣氏、星巴克等连锁经营模式)\n③单位存款凭条如何规范填写：\n对公客户办理现金存款业务，须完整、准确填写“单位存款凭条”必填项包括：日期、存款类别、户名、账号、金额，同时应要求客户在“备注”栏位如实填写“款项来源”信息，“款项来源”须表达“XXX单位(或人“本单位营业收入款”)。柜员不得受理无“款项来源“等相关内容的单位存款业务。\n④集约平台“8214105-对公现金存入”应确认账号开户行为本机构（暂不支持跨机构）\n⑤原则上非工作日不办理\n⑥交易金额大于20万，触发远程核准。","shape":true},{"kind":"paragraph","text":"三.办理人员尽职调查要求："},{"kind":"paragraph","text":"(一)对于单笔或当日累计存入现金达人民币5万元(含)或者外币等值1万美元(含)以上的业务，按照以下步骤对办理人员开展尽职调查："},{"kind":"paragraph","text":"1.确认办理人员与公司关系"},{"kind":"paragraph","text":"对于场景1,应通过系统查询我行对公客户已留存/备案信息，确认前来办理业务的个人确为相关人员，或按照单位结算卡等相关产品管理办法对办理人员进行确认。"},{"kind":"paragraph","text":"对于场景2,应核实授权材料的真实性，确认对公客户已向前来办理业务的个人进行授权。授权材料复印后随会计档案上缴备查。"},{"kind":"paragraph","text":"对于场景3,应调阅仍在生效期的业务协议，确认前来办理业务的个人确为协议指定人员之一。对于客户声称代表公司办理业务，但拒绝提供相关证明材料或客户行为异常、无法排除合理怀疑的，应拒绝办理。"},{"kind":"paragraph","text":"2.核查、登记办理人员身份信息"},{"kind":"paragraph","text":"在确认办理人员身份后，应要求办理人员出示有效身份证件，确认“人证相符”。还应对证件的有效性、真实性开展核实，并登记办理人员身份信息，使用“1010-无折现金存款”、“8214105-对公现金存入”办理业务。如发现“人证不相符”或证件真实性、有效性存疑的，应拒绝办理业务。"},{"kind":"paragraph","text":"操作方法如下："},{"kind":"paragraph","text":"对于场景1,需对办理人员的居民身份证开展联网核查，核查结果应打印并和身份证件复印件随会计档案上缴备查。"},{"kind":"paragraph","text":"对于场景2、3,应在“1010-无折现金存款”交易界面的代办人选项应选为“是”,在“代办人/授权办理人员客户信息采集”界面录入办理人员的姓名、联系方式、身份证明文件的种类、号码，在“代办理由”栏位录入其与公司的关系，对办理人员的居民身份证开展联网核查，核查结果应打印并和身份证件复印件随会计档案上缴备查。如办理人员的有效身份证件为居民身份证以外其他证件，应按参照我行识别个人证件相关要求开展识别和登记工作。"},{"kind":"paragraph","text":"(二)对于单笔或当日累计存入现金为人民币5万元(不含)或者外币等值1万美元(不含)以下的业务，由办理人员在业务凭证空白处填写姓名、身份证号、与公司的关系(如公司关联人、公司员工等),无需出示有效身份证件或授权书。经办柜员手工比对进行联网核查，将核查回显的姓名、证件号码与办理人员提供的姓名、证件号码进行核对，确保所填写的证件信息有效，打印手工核查结果并随会计档案上缴备查。"},{"kind":"paragraph","text":"四.对公账户现金存入业务常见Q&A"},{"kind":"paragraph","text":"1.监狱犯人家属持现金至我行柜台存入监狱虚拟卡账户用于犯人在狱中生活的消费支出，是否属于对公业务?"},{"kind":"paragraph","text":"答：监狱犯人家属所持现金为个人所有，其无法代表监狱。因此，该场景不属于对公业务。"},{"kind":"paragraph","text":"2.派出所执法人员持现金罚没款至我行柜台存入其上级公安局账户，是否属于对公业务?答：执法人员所持现金罚没款非个人所有，且派出所为公安局的派出机构，是公安局的组成部分。因此，该场景属于对公业务。"}]},{"title":"2.1.2对公现金支取","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"1.审核材料：客户携带有效身份证件；"},{"kind":"paragraph","text":"2.填写单据：现金支票，非日常业务办理人员需提供授权书。"},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"确定办理人员与公司关系","shape":true},{"kind":"paragraph","text":"核心交易操作界面截图：","shape":true},{"kind":"paragraph","text":"核查、登记办理人员身份\n信息、审查填写单据","shape":true},{"kind":"paragraph","text":"1060；②8214106（集约）","shape":true},{"kind":"paragraph","text":"1060：输入账号、凭证类型、选择支取方式；②8214106：按情况选择是否收费、现金统计分析码、代办人选项。点击单笔扫描，选择模板，扫描后提交","shape":true},{"kind":"paragraph","text":"1060：电子验印并打印在支票背面（5万元以上需双人核印）/②8214106：无需验印","shape":true},{"kind":"paragraph","text":"1060：按情况选择是否收费","shape":true},{"kind":"paragraph","text":"打印传票交与客户签字","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①现金支票的收款人为支票出票人\n1.柜员应审核经办人身份证件原件，核实经办人是否为单位日常结算业务授权办理人员。如经办人为日常结算业务授权办理人员，柜员应要求经办人在现金支票背面注明姓名、身份证件名称、证件号码、发证机关，并对其身份证件进行联网核查，经办人员身份证件复印件、联网核查记录作当日传票。\n2.如经办人非已授权的日常结算业务办理人员，柜员应按照新增被投权人员业务流程，要求经办人提供 《单位结算账户相关业务授权书》(以下简称“授权书”)、法定代表人(或单位负责人）、被授权人身份证件原件及复印件等材料。\n②现金支票的收款人为个人\n1.各行应审核经办人身份证件原件，并核实经办人是否为现金支票记载的收款人，如经办人为现金文票记载的收款人，柜员应要求经办人在现金支票背面注明姓名、身份证件名称、证件号码、发证机关，并对其身份证件进行联网核查，经办人员身份证件复印件、联网核查记录作当日传票。\n2.如经办人非现金支票记载的收款人，应要求提供代理人、被代理人身份证件原件，同时要求经办人 （即代理人）在现金支票背面注明代理人、被代理人姓名、身份证件名称、证件号码、发证机关，并对代理人、被代理人身份证件进行联网核查，代理人、被代理人身份证件复印件、联网核查记录作为当日传票。\n③交易金额大于5万，触发远程核准。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.审核支票填写的规范性，特别是日期、大小写合规性、账户账号的名称。"},{"kind":"paragraph","text":"2.注意支票有无涂改，有涂改支票作废。"}]}],"blocks":[]},{"title":"2.2对公转账","children":[],"blocks":[{"kind":"paragraph","text":"一．所需材料"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"1若收款人为同一开户行：转账支票＋进账单"},{"kind":"paragraph","text":"2除此以外：结算业务申请书"},{"kind":"paragraph","text":"客户环节注意事项：\n1结算业务申请书需企业日常经办人员本人带身份证原件办理；若非日常经办人员需提供授权书，代办人需提供本人身份证件办理，并在结算申请书中填写代办人姓名、联系电话、证件类型、证件号码、有效期等内容 。\n2若为大额公转私需提供材料作附件（如借款，需提供借款合同，收款回单等）","shape":true},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"支票同行1045；跨行33101","shape":true},{"kind":"paragraph","text":"系统录入，收付款人、金额等信息，验印提交","shape":true},{"kind":"paragraph","text":"同行金额超限或公转私等需要集中授权，需拍收付款人490，付款凭证，转账材料（若有）；跨行需叫后台人员及时复核。","shape":true},{"kind":"paragraph","text":"打印传票，整理凭证","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1若为金额达到50万需双人验印\n2若金额达到500万非同户名转账，需热线查证（非经办人员），填写大额转账审批表\n3若为33101跨行转账需叫后台人员及时复核","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.整理业务单据"},{"kind":"paragraph","text":"2.关注当日来往报，若有退回情况及时联系客户"}]},{"title":"2.3集约平台","children":[],"blocks":[{"kind":"paragraph","text":"①、核心交易码"},{"kind":"paragraph","text":"8214002—行内汇款"},{"kind":"paragraph","text":"8214003—转账支票付款"},{"kind":"paragraph","text":"8214008—RCPS跨行对公大额转账"},{"kind":"paragraph","text":"8214009—RCPS跨行对公小额转账"},{"kind":"paragraph","text":"②、凭证审核"},{"kind":"paragraph","text":"1、上传凭证要求：票面整洁，书写工整，字迹清晰，无错别字，要素信息正确，包括但不限于凭证日期书写规范，金额大小写一致等。(注意：如遇字迹潦草可用铅笔在下行或上行处重新写一遍，尤其转账支票上付款账号若不清晰，不可在原账号上进行描写！审核转账支票正背面的盖章是否规范盖在签章处、行号不要盖到支付密码栏位。) （受理柜员要在经办或记账栏位签字或签章）"},{"kind":"paragraph","text":"2、经办柜员应先行核对印鉴的清晰度、准确性、是否变形，降低拒绝率。（尤其需要核对印鉴小码是否加盖清晰，核对账号、户名准确性，查询余额是否足够，账户状态是否正常，有无管控）"},{"kind":"paragraph","text":"3、对于使用结算业务申请书的，需将汇款附言填写至“附言”栏位。"},{"kind":"paragraph","text":"4、对于使用“转账支票+进账单”，需将汇款附言填写至支票“用途”栏位、进账单“备注”栏位。"},{"kind":"paragraph","text":"③、操作要点"},{"kind":"paragraph","text":"1、柜员每日需执行8214020—集中作业信息提示（否则签退后再签到将无法收到集中作业消息提醒）"},{"kind":"paragraph","text":"2、根据业务或凭证类型，使用对应的交易码。（行内公转私时，对私账号和定期账户扫描上传时需输入产品类型和产品子类。）"},{"kind":"paragraph","text":"3、根据业务实际，选择正确标识（如“加急”、“收费”）及汇款方式（R-实时汇款，S-挂账类汇款）。"},{"kind":"paragraph","text":"4、严格按照模板顺序放入对应的业务凭证。"},{"kind":"paragraph","text":"5、对不规范影像可点击“质检”调整画面。"},{"kind":"paragraph","text":"6、单次批量上传最多不超过100笔。（100笔（含）及以上的批量业务，仍需按现行预约要求申请预约，由全国中心安排分批次提交，网点每批次提交的业务不能超出100笔。）"},{"kind":"paragraph","text":"7、注意集约平台受理时间：工作日8:30-18:00，跨行大额截止时间16:50"}]},{"title":"2.4非税业务","children":[],"blocks":[{"kind":"paragraph","text":"一．客户环节"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"情况一：转账支票+进账单+福建省非税收入缴款通知书"},{"kind":"paragraph","text":"情况二：一般缴款书"},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"情况一E31204，情况二21031、E33103","shape":true},{"kind":"paragraph","text":"录入信息，支票或一般缴款书第二联验印，提交","shape":true},{"kind":"paragraph","text":"若为一般缴款书21031（无折客户账转内部账）转入我行BGL","shape":true},{"kind":"paragraph","text":"E33103 缴税\n填写特种转账传票，转入缴税单位账户","shape":true},{"kind":"paragraph","text":"打印传票，若为一般缴款书第一联盖财税专用章后给客户留存，第二联跟传票，第三四五联盖财税专用章后送人行","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1、达到金额50万需双人验印\n2、一般缴款书三四五联当日16：00前送人行，填写及盖章需十分清晰，避免人行退票( 根据当地人行要求情况送审）\n3、一般缴款书第一联盖财税专用章后给客户留存，第二联跟传票","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"一般缴款书三四五联当日16：00前送人行，送前先拍条线人员审核，避免退票"}]},{"title":"2.5证明类业务","children":[{"title":"2.5.1询证函、资信证明","children":[],"blocks":[{"kind":"paragraph","text":"以下为针对正常状态账户开展的操作流程，销户等特殊情况参考条线相关文件"},{"kind":"paragraph","text":"一.资信证明所需材料"},{"kind":"paragraph","text":"审核材料：法人身份证复印件、经办人身份证原件及复印件，营业执照复印件加预留印鉴章。填写中国银行股份有限公司单位客户结算证明业务申请书。"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"注意事项：\n1、查询中国注册会计师协会行业管理信息系统网站公示的会计师事务所的回函信息，电话联系事务所工作人员，核实回函信息真实准确，并在函证空白处注明核实情况，打印查询页面作为附件（删除）\n2、查询该单位是否为小微企业，小微企业可免收费用，打印查询页面作为免费依据\n3、根据函证中要求询证的内容，查询账户状态（490）、冻结情况（9079）、贷款还款情况（通用查询-连接账户，查看是否存在贷款账号-短查询）、对账单，打印查询页面作为附件（删除）\n4、资信证明申请书格中若为划斜线的，可无需抓取数据，若为空白或填写无的，也需抓取数据\n5、结算资信证明，询证函，不得使用E96001申请电子印章。\n6.经办人在结算证明业务申请书上备注本单位***于**年**月**日在中国银行**支行开立的单位客户结算证明**份，已被本单位员工**领取。签名+日期。","shape":true},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"经办交易码E52601复核E52607","shape":true},{"kind":"paragraph","text":"","images":["image77.jpeg"]},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"输入会计师事务所相关回函信息及询证截止日（删除）","shape":true},{"kind":"paragraph","text":"根据需询证的内容，点击每个选项进入页面，进行数据抓取","shape":true},{"kind":"paragraph","text":"待数据抓取完毕后，将人工查询打印的相关附件数据与系统抓取的数据进行核对，确保数据无误（删除）","shape":true},{"kind":"paragraph","text":"扫描询证函原件、所有附件材料","shape":true},{"kind":"paragraph","text":"询证函中第14项其他栏位为空的，需在系统页面内其他栏位填写：来函未对此项目内需确认内容进行具体说明（删除）","shape":true},{"kind":"paragraph","text":"提交复审","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1、输入的回函信息及询证截止日需准确（删除）\n2、所有出具回函的数据必须有附件依据（删除）\n3、影像依据完整扫描（删除）\n1、回函自取：经办人在结算证明业务申请书上备注本单位***于**年**月**日在中国银行**支行开立的单位客户结算证明**份，已被本单位员工**领取，签名+日期，并将签收记录上传至影像系统。\n2、回函邮寄：首先，查询中国注册会计师协会行业管理信息系统网站公示的会计师事务所的回函信息，电话联系事务所工作人员，核实信息真实准确，并在空白处注明核实情况，打印查询页面作为附件；其次，将EMS回执联上传至影像系统。\n3、若涉及资信证明收费，同样也要将收费船票上传至影像系统。","shape":true},{"kind":"paragraph","text":"待数据抓取完毕后，将人工查询打印的相关附件数据与系统抓取的数据进行核对，确保数据无误","shape":true},{"kind":"paragraph","text":"二、询证函（审计询证函、验资询证函）已上收全国中心处理"},{"kind":"paragraph","text":"","images":["image78.png"]},{"kind":"paragraph","text":"（一）审计询证函："},{"kind":"paragraph","text":"1、退回开户机构补充资料：执行“8214022退回开户机构任务处理”， 根据退回原因选择相应的按钮，进入详情页面，点击“影像查看”，判断能否补充提供相关的审核材料，补充结果填写《银行询证函验印确认回执》、《银行询证函询证内容确认函回执，经经办、有权人签字后，扫描上传影像。"},{"kind":"paragraph","text":"2、因印鉴问题（特殊印鉴、一销户）转至开户机构：进入P2端查询询证函来函影像并下载验印影像。路径：交易集约-集中作业处理-询证函影像查询。验印结果填写《银行询证函验印确认回执》，经开户机构经办、有权人签字后，开户机构经办在BL端进行影像上传并提交。"},{"kind":"paragraph","text":"3、 已销户账户：开户机构可通过重启印鉴，或联系客户补充营业执照、单位说明、客户销户证明等资料进行核实，核实结果填写《银行询证函验印确认回执》，经开户机构经办、有权人签字后，开户机构经办在BL端进行影像上传并提交。"},{"kind":"paragraph","text":"4、退回开户机构收费：执行E52605交易，根据应收、实收金额判断收费项目，点击“现金收费”或“转账收费”收取询证函手续费；点击“邮寄费现金收费”或“邮寄费转账收费”收取询证函邮费。请注意收费项目的准确性。收费回单扫描上传至系统中留存备查。"},{"kind":"paragraph","text":"5、退回开户机构打印：执行“8214024退回开户机构打印”，回函交于来人并指导"},{"kind":"paragraph","text":"来人在身份证件复印件上签收确认。 开户机构柜员将回函、身份识别资料等全部扫描留存系统备查。"},{"kind":"paragraph","text":"（二）验资询证函："},{"kind":"paragraph","text":"1、网点收到验资询证函，应审核函证中所填写的账号是否属于四类账户（验资账户、资本金账户、募集资金专用账户、境内SPV人民币托管账户）、如不属于四类账户，视情况可用资信证明予以回函。如若为四类账户且符合受理范围，开户机构发起函证扫描。"},{"kind":"paragraph","text":"2、符合中心受理标准的执行“8214005询证函业务受理服务”交易，输"},{"kind":"paragraph","text":"入以下栏位后点击“提交”："},{"kind":"paragraph","text":"来函类型：只允许选择“标准来函”；"},{"kind":"paragraph","text":"业务类型：固定选择“验资询证函”；"},{"kind":"paragraph","text":"是否加急：“不加急”或“加急”"},{"kind":"paragraph","text":"回函方式：“邮寄”或“自取”"},{"kind":"paragraph","text":"是否收取邮费：选择“正常收费”；"},{"kind":"paragraph","text":"是否收取手续费：选择“正常收费”；"},{"kind":"paragraph","text":"缴入日期：选择日期；"},{"kind":"paragraph","text":"邮费：按处理中心邮寄收费标准录"},{"kind":"paragraph","text":"（三）询证函查询方式支持公众号查询中心处理的审计询证函进度"},{"kind":"paragraph","text":"“中国银行企业微银行”公众号-微服务-函证查询服务，可查询通过交易集约组件发起且数据检核通过的纸质审计询证函业务。"},{"kind":"paragraph","text":"（四）注意事项"},{"kind":"paragraph","text":"1、行8214022、8214024交易查询机构项下是否有中心退回待处理任务，相关任务需在自任务推送之日起三个工作日之内完成提交"},{"kind":"paragraph","text":"2、8214022无法查询相关的待处理交易，网点核准用户可通过“E52611-取消处理”释放交易给当班经办人员进行处理。"},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"notice","text":"（原稿此节标注：删除）"},{"kind":"paragraph","text":"1.注意需在10个工作日内及时回函，使用TY05打印，白联及询证函原件、附件依据随传票，蓝联寄出；"},{"kind":"paragraph","text":"2.非小微企业涉及收费200元/份及快递费（交易码E52605，账户内收取）；"},{"kind":"paragraph","text":"3.将复审通过后打印出的回函、快递回单、收费回单（如有）一同扫描至影像内。"}]},{"title":"2.5.2有权机关查冻扣","children":[],"blocks":[{"kind":"paragraph","text":"一．所需材料：有权机关执法人员证件、查冻扣通知书及回执联、裁定书（如有）"},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"核对通知书各项内容（文书号、姓名、卡号等），有权机关执法人员证件人员，回执联是否正确","shape":true},{"kind":"paragraph","text":"z","images":["image79.png"]},{"kind":"paragraph","text":"1、查询：通用查询—账户信息、410账户余额。\n2、冻结或解冻：查询9079账户冻结情况，根据需要进行9081冻结或9091解冻。","shape":true},{"kind":"paragraph","text":"扣划具体步骤图示：","shape":true},{"kind":"paragraph","text":"3、扣划：使用交易码G06017，具体操作步骤如右图所示","shape":true},{"kind":"paragraph","text":"4、用印：交易码E96001—标准标准凭证—有权单位查冻扣通知书（回执联）—打印用印章（如右图）","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.G06017中对账单摘要中应填入通知书的文书编号；查冻扣通知书需要有权人签字。\n2.在进行汇款时应正确填写通知书上的收款方的账户、户名、开户行名称（关键词模糊搜索），在备注上注明姓名及文书号；\n3.冻结权限仅限于海关、公安机关、国家安全机关等，外汇机构、银保监、财政部无冻结权限；\n4.查询9079冻结情况时，查冻扣通知书、裁定书需体现原冻结文号。\n5.如果客户号是隔离状态，应先一键解隔离（需省行条线审批）。关注下批统一报隔离时间，再次隔离客户号。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.有权机关执法人员证件复印件上备注“此复印件仅用于办理XX业务”；"},{"kind":"paragraph","text":"2.回执书上应注意写明已查询、冻结、扣划的金额及具体时间（精确到时分秒）；"},{"kind":"paragraph","text":"3.如账户余额小于有权机关要求的冻结金额，则在“已冻结金额”处应填写冻结时的实际账户余额，“未冻结金额”应填写要求冻结金额与已冻结金额的差额，原因备注为“余额不足”。"}]}],"blocks":[]}],"blocks":[]},{"title":"3.产品篇","children":[{"title":"3.1网银","children":[{"title":"3.1.1IGTB网银业务操作规程","children":[],"blocks":[{"kind":"paragraph","text":"一、客户环节"},{"kind":"paragraph","text":"审核材料：①新开户新开网银需提供：营业执照原件及复印件、法人身份证原件及复印件、网银操作员身份证原件及复印件、经办人身份证原件及复印件，所有复印件需加盖预留印鉴，“与原件核对相符”章（经办复核私章或双签）并在复印件打印联网核查；②存量客户办理操作员新增、修改等业务，需提供：原操作员有效身份证件复印件、新操作员、经办人证件原件及复印件（如无法提供原操作员证件复印件可出示说明），以上复印件需加盖预留印鉴，“与原件核对相符”章（经办复核私章或双签）并在复印件打印联网核查；"},{"kind":"paragraph","text":"填写单据：中国银行股份有限公司企业网银标准模式服务申请表、中国银行企业网上银行风险提示、中国银行股份有限公司企业电子银行章程"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image80.jpeg","image81.png"]},{"kind":"paragraph","text":"注意事项：\n申请表及客户提供的复印件加盖预留印鉴并验印\n对办理人员身份证件进行联网核查，并截图打印","shape":true},{"kind":"paragraph","text":"注意事项："},{"kind":"paragraph","text":"1、申请表及客户提供的复印件加盖预留印鉴并验印"},{"kind":"paragraph","text":"2、对办理人员身份证件进行联网核查，并截图打印"},{"kind":"paragraph","text":"二．操作流程"},{"kind":"paragraph","text":"新开户新开网银：H00101-高频产品智能选择-企业网银-到达网银签约界面，延续生效根据实际情况选择是否立即生效-选择用户管理的人员-依次选择操作员、管理员-是否绑定选择是-录入UK序列号（KEY的序列号最后一位不输）-保存-选择需开通的网银服务-提交","images":["image82.jpeg","image83.jpeg","image84.jpeg","image85.jpeg","image86.jpeg","image87.jpeg"]},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"存量变更操作员：H0221-录入要素查询-用户信息查询及设置-修改-更换自然人-读取证件-输入企业网银办理人信息-提交主管授权"},{"kind":"paragraph","text":"","images":["image88.jpeg","image89.jpeg","image90.jpeg","image91.jpeg","image92.jpeg"]},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"存量客户办理换key业务：H00221-账号、查询-用户信息查询及设置-证书更换-输新的KEY号，提交主管授权"},{"kind":"paragraph","text":"","images":["image88.jpeg","image89.jpeg","image90.jpeg","image93.jpeg"]},{"kind":"paragraph","text":"核心交易操作界面截图","shape":true},{"kind":"paragraph","text":"操作流程注意事项："},{"kind":"paragraph","text":"1、申请表填写完整，需办理的具体业务勾选完整"},{"kind":"paragraph","text":"2、证书工具及密码信封需双人核对后递交客户"},{"kind":"paragraph","text":"3、涉及网银操作员删除后新增的，对账系统应同时进行变更，否则客户将无法对账"},{"kind":"paragraph","text":"4、网银相关资料验印未自动通过需要双人验印。并在旁边签字确认。"}]}],"blocks":[]},{"title":"3.2短信通","children":[{"title":"开立/变更/撤销对公短信通知","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"审核材料："},{"kind":"paragraph","text":"①法人、被授权人、短信接收人的身份证原件及复印件"},{"kind":"paragraph","text":"②营业执照原件及复印件"},{"kind":"paragraph","text":"③公章和法人章"},{"kind":"paragraph","text":"*注意：需核对材料复印件与原件相符及真实（双人签章）"},{"kind":"paragraph","text":"填写材料："},{"kind":"paragraph","text":"开立短信通知："},{"kind":"paragraph","text":"《中国银行股份有限公司单位银行综合产品服务申请书》，非法人办理需填写《单位银行结算账户相关业务授权书》，并加盖银行预留印鉴，勾选对公短信通相应栏位，经办、复核验印核对无误后继续办理。"},{"kind":"paragraph","text":"变更短信通知："},{"kind":"paragraph","text":"加盖公章法人章的《中国银行股份有限公司对公短信通产品变更/撤销申请表》，非法人办理需填写《单位银行结算账户相关业务授权书》，并加盖公章和法人章，无需核印。"},{"kind":"paragraph","text":"撤销短信通知："},{"kind":"paragraph","text":"加盖公章法人章的《中国银行股份有限公司对公短信通产品变更/撤销申请表》非法人办理需填写《单位银行结算账户相关业务授权书》，并加盖公章和法人章，无需核印。"},{"kind":"paragraph","text":"操作流程注意事项：\n核心交易码\n开立短信通知：E16701/H00201\n变更/撤销短信通知：E16701/E16702","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"审核客户材料①","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n①客户提交的所有相关个人身份证件都应进行联网核查，审核授权书、申请表内容完整性。\n②E16701录入账号，选择相应客户类型，选择定制服务进行维护。\n③H00201录入统一社会信用代码证，系统会回显账户信息，录入对应账号，选择对公短信通业务进行维护。\n④对公短信收费为每个手机号20元/月或每个手机号240元/年，扣费日期为每月5号，若有短信减免需于5号前完成，避免误收，提示客户账户5号时应有足够余额，避免账户因欠费无法收取到动账信息。\n⑤E16701可选择对应服务：已签约账户新增短信接收手机号码、变更短信接收手机号码、变更发送短信金额上下限、变更付费账号、变更付费账户别名、变更优惠模式、变更付费方式、撤销已签约账户下某一条已签约的服务信息，撤销已签约账户下所有对公短信通服务。","shape":true},{"kind":"paragraph","text":"开立","shape":true},{"kind":"paragraph","text":"变更/撤销","shape":true},{"kind":"paragraph","text":"通过E16701②或H00201③执行开立交易④","shape":true},{"kind":"paragraph","text":"通过E16701执行变更与撤销交易⑤","shape":true},{"kind":"paragraph","text":"提交打印并签字","shape":true},{"kind":"paragraph","text":"流程补充：开通短信通知-E16701-输入客户号/账号-提交-定制服务-增加：动户通知、手机号、上限、下限、收费-提交-ty04【客户信息补录】"},{"kind":"paragraph","text":"做完新增短信通知手机号码以后，E16701下方有一个客户信息补录按钮，里面是可以录入手机号机主的姓名+身份证号。（E16701旧线交易码不会自动联动采集接受短信授权人的身份信息）"},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"审核材料无遗落客户填盖信息、网点双人签章"},{"kind":"paragraph","text":"四.相关附件"},{"kind":"paragraph","text":"《中国银行股份有限公司对公短信通产品管理办法（2019年版）》"},{"kind":"paragraph","text":"《单位银行结算账户相关业务授权书》"},{"kind":"paragraph","text":"《中国银行股份有限公司单位银行综合产品服务申请书》"},{"kind":"paragraph","text":"《中国银行股份有限公司对公短信通产品变更/撤销申请表》"}]}],"blocks":[]},{"title":"3.3结算卡","children":[{"title":"3.3.1结算卡开立","children":[],"blocks":[{"kind":"paragraph","text":"一、新开户同时开立结算卡"},{"kind":"paragraph","text":"审核材料：同开户材料"},{"kind":"paragraph","text":"需填写凭证：《中国银行股份有限公司单位银行综合产品服务申请书》"},{"kind":"paragraph","text":"操作流程：经办柜员输入“H00101”进入交易画面，根据实际情况进行选择"},{"kind":"paragraph","text":"","images":["image94.jpeg"]},{"kind":"paragraph","text":"二、持账户开预制卡（允许授权他人代办）"},{"kind":"paragraph","text":"企业所需材料："},{"kind":"paragraph","text":"1、法定代表人或单位负责人、指定持卡人身份证件以及代办人原件及复印件"},{"kind":"paragraph","text":"2、营业执照原件"},{"kind":"paragraph","text":"3、公章和法人章"},{"kind":"paragraph","text":"需填写凭证:"},{"kind":"paragraph","text":"1、《中银单位结算卡产品开办/变更申请表》"},{"kind":"paragraph","text":"1、《单位银行结算账户相关业务授权书》（代办）"},{"kind":"paragraph","text":"操作流程："},{"kind":"paragraph","text":"1、结算卡主账户开户行审核开卡资料完整合规，跨网点查询拟关联的从账户状态是否为正常状态，并对所有相关个人身份证件进行联网核查。指定持卡人需为我行个人客户（含临时客户），客户号可通过搜索（个人）按钮查询返回，如无此客户会联动创建临时客户。"},{"kind":"paragraph","text":"2、经办柜员进入“8203101开单位预制卡”交易，输入以下栏位后点击“提交”："},{"kind":"paragraph","text":"卡号：直接输入预制卡卡号或点击“插卡”，选择“芯片卡”插卡读入卡号。"},{"kind":"paragraph","text":"账号：可输入结算卡的主账号或点击“搜索”查询账号；"},{"kind":"paragraph","text":"单位结算卡指定持卡人编号：输入单位结算卡指定持卡人个人客户号。"},{"kind":"paragraph","text":"一户通子账户类型：选择一户通子账户类型。"},{"kind":"paragraph","text":"进入明细画面，系统自动回显卡的基本信息，经办柜员输入以下栏位后提交："},{"kind":"paragraph","text":"年费费率：输入收取年费的百分比，系统自带百分号，此处输入0-100即可；"},{"kind":"paragraph","text":"免年费期：输入免年费的期限（数字，必须为整数），单位为“年”；"},{"kind":"paragraph","text":"收费方式：现金收费、转账收费、空白（默认从主账户收费）。"},{"kind":"paragraph","text":"结算卡查询权限：必输项，A：该账户所有金融交易；B：该卡发生的金融交易；C：无查询权限。"},{"kind":"paragraph","text":"结算卡信息阀值：必输项，回显可修改。"},{"kind":"paragraph","text":"国际区号：输入正确的国际区号。"},{"kind":"paragraph","text":"单位结算卡指定持卡人手机号：输入对私指定持卡人手机号。"},{"kind":"paragraph","text":"工本费：必输项，回显可修改，最大支持14整数（表现形式无前补零）+小数点+3位小数。"},{"kind":"paragraph","text":"3、“8203101开单位预制卡”交易需核准，核准规则为“强制核准”。"},{"kind":"paragraph","text":"4、发卡后系统联动或批处理收取工本费与年费。"},{"kind":"paragraph","text":"5、《系统输出凭证（TY05）》—单位开预制卡"},{"kind":"paragraph","text":"6、开卡成功后，卡片未激活状态，默认密码为（已隐去），需经激活后方可使用，激活时将允许客户修改密码。"},{"kind":"paragraph","text":"7、若开卡成功，收费失败，柜员需另发起综合收费交易进行补收费。"},{"kind":"paragraph","text":"备注：结算卡工本费5元，年费450元/张/年；（以实际政策为准）"},{"kind":"paragraph","text":"三、持账户开单位非预制卡"},{"kind":"paragraph","text":"1、提交资料：客户提交资料同持账户开单位预制卡操作流程。"},{"kind":"paragraph","text":"客户在制卡完成后办理领卡，指定持卡人本人持《系统输出凭证（TY05）（单位开非预制卡）》（客户回单联）连同有效身份证件一同提交开户行办理领卡有关手续。"},{"kind":"paragraph","text":"2、操作流程：经办柜员在系统选择“8203102开单位非预制卡”交易，输入账号、可售产品编号、单位结算卡指定持卡人编号、是否配介质、开卡类型等信息后提交。进入明细画面，系统自动回显卡的基本信息，经办柜员输入结算卡查询权限、结算卡信息阀值、国际区号、单位结算卡指定持卡人手机号、年费费率、免年费期限、工本费等信息后提交："},{"kind":"paragraph","text":"3、发卡后系统联动或批处理收取工本费与年费。"},{"kind":"paragraph","text":"4、统输出凭证（TY05）——单位开非预制卡"}]},{"title":"3.3.2结算卡销户","children":[],"blocks":[{"kind":"paragraph","text":"一、单位结算卡销户（可代办）"},{"kind":"paragraph","text":"客户需提供材料："},{"kind":"paragraph","text":"1、持卡人有效身份证件/办理人有效身份证件"},{"kind":"paragraph","text":"2、结算卡"},{"kind":"paragraph","text":"3、公章和法人章"},{"kind":"paragraph","text":"需提交凭证："},{"kind":"paragraph","text":"1、《中银单位结算卡挂失/解挂/销卡业务申请书》"},{"kind":"paragraph","text":"2、《单位银行结算账户相关业务授权书》（代办）"},{"kind":"paragraph","text":"备注：注意销卡时该卡是否有欠费。如有欠费，须通过收费交易进行收费处理。如欠缴年费，可通过核准强制销卡；处于挂失期限内的卡不能销卡；"},{"kind":"paragraph","text":"操作流程："},{"kind":"paragraph","text":"审核客户材料","shape":true},{"kind":"paragraph","text":"持卡知道密码销卡","shape":true},{"kind":"paragraph","text":"持卡忘记密码销卡","shape":true},{"kind":"paragraph","text":"未持卡忘记密码销卡","shape":true},{"kind":"paragraph","text":"8203103单位销卡卡交易（远程核准）","shape":true},{"kind":"paragraph","text":"8003309挂失（远程核准），身份证联网核查，密码重置天数可录入“0”，页面下方“是否挂失核实确认”根据实际情况选择相应的核实方式。核准打印挂失回单并签字","shape":true},{"kind":"paragraph","text":"8003309挂失（远程核准），其中挂失天数可录入“0”，页面下方“是否挂失核实确认”应根据实际情况选择相应的核实方式，“是否冻结”录入“N-不冻结”。","shape":true},{"kind":"paragraph","text":"打印TY05并签字","shape":true},{"kind":"paragraph","text":"8003303重置密码（无纸化）","shape":true},{"kind":"paragraph","text":"8203103单位销卡交易，按系统页面要求录入销卡原因等信息后提交，客户输入新密码后完成销卡。核准打印TY05签字","shape":true},{"kind":"paragraph","text":"8203103 单位销卡交易（远程核准），按系统页面要求录入销卡原因等信息后提交，复核人员授权后完成销卡。","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n申请书需按实际情况勾选。\n挂失销卡需填挂失编号\n为控制风险，注销的卡片由银行剪角作废","shape":true}]},{"title":"3.3.3结算卡取款","children":[],"blocks":[{"kind":"paragraph","text":"一、所需材料"},{"kind":"paragraph","text":"审核材料：指定持卡人持单位结算卡、本人有效身份证件"},{"kind":"paragraph","text":"无需填写单据"},{"kind":"paragraph","text":"二、操作流程"},{"kind":"paragraph","text":"询问客户取现用途，联网核查","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n用途应录入在无折现金取款交易中“对账单摘要”栏位\n本业务只能由指定持卡人办理","shape":true},{"kind":"paragraph","text":"7062查询异常状态，对系统提示限制非柜面交易的账户，非开户行不得取现、转账","shape":true},{"kind":"paragraph","text":"1060取款","shape":true},{"kind":"paragraph","text":"回单打印后客户签字","shape":true}]},{"title":"3.3.4结算卡重置密码","children":[],"blocks":[{"kind":"paragraph","text":"一．智能柜台修改密码"},{"kind":"paragraph","text":"单位结算卡指定持卡人持卡及密码可在智能柜台修改卡密码，指定持卡人在智能柜台客户端点击“结算卡修改密码” 菜单，插卡、输入原取款密码。 原取款密码验证通过后，指定持卡人设置6位新密码。密码修改成功，客户可选择打印交易凭条。"},{"kind":"paragraph","text":"二．柜台修改密码"},{"kind":"paragraph","text":"审核材料：《中银单位结算卡挂失/解挂/销卡业务申请书》、指定持卡人有效身份证件、结算卡（本业务只能由指定持卡人办理）"},{"kind":"paragraph","text":"操作流程："},{"kind":"paragraph","text":"1、在系统选择“8003302修改密码”交易，插卡读入结算卡卡号后点击“提交”按钮，系统返回回显相应卡片信息，核对无误后，点击“密码”按钮，请指定持卡人在密码键盘上输入卡旧密码及两次卡新密码，点击“提交”按钮。"},{"kind":"paragraph","text":"2、交易成功，系统自动生成电子交易回单，BL前端弹窗提示“推送交易回单，待客户电子签名确认”。"},{"kind":"paragraph","text":"","images":["image95.png"]},{"kind":"paragraph","text":"3、客户通过柜外清确认业务办理结果无误后进行电子签名操作。"},{"kind":"table","rows":[],"images":["image96.png","image97.png","image98.png"]},{"kind":"paragraph","text":"4、客户电子签名确认后，BL前端展示“电子单据预览”窗口，经办柜员可点击右侧PDF回单预览合成的电子交易回单。"},{"kind":"paragraph","text":"","images":["image99.png"]},{"kind":"paragraph","text":"5、若客户签字不清晰或不规范，经办柜员可点击“退回重签”按钮，柜外清将引导客户再次签名确认。"},{"kind":"paragraph","text":"6、经办柜员点击“电子单据预览”窗体的“提交”按钮，BL前端展示“影像断点续传”窗口。状态显示“上传成功”，此交易涉及的电子单据上传后台成功。"},{"kind":"paragraph","text":"","images":["image100.png"]},{"kind":"paragraph","text":"7、如点击“电子单据预览”窗体的“关闭”按钮，弹窗提示“如关闭当前窗口，此交易涉及的电子单据将无法完成电子归档处理。请确认是否“关闭”？”。如经办柜员点击“确定关闭”，将导致当前交易涉及的电子单据无法上传后台，亦无法使用相关渠道客户补打电子单据功能。"},{"kind":"paragraph","text":"","images":["image101.png"]},{"kind":"paragraph","text":"操作提示：此“关闭”按钮仅供特殊情况下强制结束交易流程使用，正常交易流程中，请勿点击此按钮。"},{"kind":"paragraph","text":"8、如当前交易涉及相关纸质传票，请注意在交易办结前通过下图弹窗及时打印“无纸化追溯码”。"},{"kind":"table","rows":[],"images":["image102.png","image103.png","image104.png"]}]},{"title":"3.3.5结算卡解除CVV锁定","children":[],"blocks":[{"kind":"paragraph","text":"同一结算卡在同一天内如果出现连续三次卡CVV码校验错误，系统将锁定该卡。指定持卡人应持本人有效身份证件及卡片到任意网点柜台办理解除CVV锁定。本业务只能由指定持卡人办理。"},{"kind":"paragraph","text":"操作流程："},{"kind":"paragraph","text":"1、柜员在系统选择“8003304解除CVV锁定”交易，插卡读入结算卡卡号后点击“提交”按钮，系统返回并且回显相应卡片信息，柜员核对无误后，请指定持卡人在密码键盘上输入卡旧密码和两次卡新密码后点击“提交”按钮。“8003304解除CVV锁定”交易须核准。"},{"kind":"paragraph","text":"2、交易成功，系统自动生成电子交易回单，BL前端弹窗提示“推送交易回单，待客户电子签名确认”。"},{"kind":"paragraph","text":"","images":["image95.png"]},{"kind":"paragraph","text":"3、客户通过柜外清确认业务办理结果无误后进行电子签名操作。"},{"kind":"table","rows":[],"images":["image105.png","image98.png"]},{"kind":"paragraph","text":"4、客户电子签名确认后，BL前端展示“电子单据预览”窗口，经办柜员可点击右侧PDF回单预览合成的电子交易回单。"},{"kind":"paragraph","text":"","images":["image106.png"]},{"kind":"paragraph","text":"其他内容同“8003303重置密码”，不再赘述。"}]},{"title":"3.3.6结算卡密码解锁","children":[],"blocks":[{"kind":"paragraph","text":"同一结算卡于同一交易日内连续三次输入交易密码错误，系统将锁定该卡，指定持卡人可在卡锁定当日持本人有效身份证件、结算卡到任意网点柜台办理结算卡解锁。如指定持卡人在卡锁定当日未办理卡解锁，系统将在当天批量处理后自动解除锁定。本业务只能由指定持卡人办理。"},{"kind":"paragraph","text":"操作流程："},{"kind":"paragraph","text":"1、柜员在系统选择“8003305卡密码解锁”交易，插卡读入结算卡卡号后点击“提交”按钮，系统返回并且回显相应卡片信息，柜员核对无误后，点击“提交”按钮。交易须核准，核准规则为“强制核准”。"},{"kind":"paragraph","text":"2、交易成功，系统自动生成电子交易回单，BL前端弹窗提示“推送交易回单，待客户确认”。"},{"kind":"paragraph","text":"","images":["image107.png"]},{"kind":"paragraph","text":"3、客户通过柜外清确认业务办理结果无误后进行电子签名操作。"},{"kind":"table","rows":[],"images":["image108.png"]},{"kind":"paragraph","text":"4、客户确认后，BL前端展示“电子单据预览”窗口，经办柜员可点击右侧PDF回单预览合成的电子交易回单。"},{"kind":"paragraph","text":"","images":["image109.png"]},{"kind":"paragraph","text":"其他内容同“8003303重置密码”，不再赘述"}]}],"blocks":[]},{"title":"3.4回单箱","children":[{"title":"3.4.1开立/变更/撤销回单箱功能","children":[],"blocks":[{"kind":"paragraph","text":"一.审核客户所提供基础材料："},{"kind":"paragraph","text":"1、营业执照原件及复印件"},{"kind":"paragraph","text":"2、法人原件或复印件"},{"kind":"paragraph","text":"3、经办人身份证原件及复印件"},{"kind":"paragraph","text":"4、公章及银行预留印鉴章（公章/财务章、法人章）"},{"kind":"paragraph","text":"*注意：需核对材料复印件与原件相符及真实（双人签章）"},{"kind":"paragraph","text":"二.审核填写材料："},{"kind":"paragraph","text":"开立回单箱："},{"kind":"paragraph","text":"《中国银行股份有限公司单位银行综合产品服务申请书》，申请单位名称、账号和扣费账勾选肆，“回单服务”，勾选智能柜台、设置回单打印密码，客户确认处盖银行预留印章。"},{"kind":"paragraph","text":"非法人办理需填写《单位银行结算账户相关业务授权书》（盖公章和法人章）。"},{"kind":"paragraph","text":"变更回单箱："},{"kind":"paragraph","text":"加盖公章法人章的《中国银行股份有限公司回单变更/撤销申请表》，非法人办理需填写《单位银行结算账户相关业务授权书》（盖公章和法人章），填写变更相应栏位，经办、复核在印鉴系统中核验客户预留印鉴章。"},{"kind":"paragraph","text":"撤销回单箱："},{"kind":"paragraph","text":"加盖公章法人章的《中国银行股份有限公司回单变更/撤销申请表》，非法人办理需填写《单位银行结算账户相关业务授权书》，（盖公章和法人章），填写变更相应栏位，经办、复核在印鉴系统中核验客户预留印鉴章。"},{"kind":"paragraph","text":"三.核心交易码："},{"kind":"paragraph","text":"开立回单箱：H00201开通回单箱，打印综合信息确认表，一键签约"},{"kind":"paragraph","text":"变更/撤销回单箱：H00219（系统要点击两次查询），查看是否开通回单箱功能"},{"kind":"paragraph","text":"四.传票打印客户签字+盖章"},{"kind":"paragraph","text":"五.审核材料无遗落客户填盖信息、网点双人签章"}]},{"title":"3.4.2柜台打印回单及对账单流程","children":[],"blocks":[{"kind":"paragraph","text":"一.客户环节"},{"kind":"paragraph","text":"客户提供补打回单申请书，授权书（加盖公章、法人章）、经办人身份证原件、复印件加盖公章。"},{"kind":"paragraph","text":"二.审核要点"},{"kind":"paragraph","text":"（1）.核实客户身份信。（2）.比对预留印鉴。"},{"kind":"paragraph","text":"三.系统操作"},{"kind":"paragraph","text":"（1）.系统执行8241054回单补打、报表系统打印对账单"},{"kind":"paragraph","text":"（2）.若打印出的回单、对账单未带电子章，可手动发起E96001用印申请。"},{"kind":"paragraph","text":"（3）.要点提示：回单和对账单涉及客户账户信息，银行人员有责任保护客户信息安全，因此核实客户身份至关重要，可以避免一些不必要的纠纷。"}]}],"blocks":[]},{"title":"3.5对公金融产品","children":[{"title":"3.5.1结构性存款","children":[],"blocks":[{"kind":"paragraph","text":"一.结构性存款签约审核材料："},{"kind":"paragraph","text":"1、《中国银行公司客户结构性存款产品销售协议书》（公章、法人章）"},{"kind":"paragraph","text":"2、《中国银行公司客户结构性存款产品说明书》（公章、法人章）"},{"kind":"paragraph","text":"3、《中国银行公司客户结构性存款产品投资者权益须知》（公章、法人章）"},{"kind":"paragraph","text":"4、法定代表人/负责人证件复印件（需进行联网核查）；非法定代表人/负责人亲自办理的，需提供法定代表人/负责人证件复印件、授权书及代办人证件原件，并留存代办人证件复印件。"},{"kind":"paragraph","text":"注意事项"},{"kind":"paragraph","text":"1、结构性存款的扣款账户应与签约账户保持一致"},{"kind":"paragraph","text":"2、《中国银行公司客户结构性存款产品说明书》、授权书均按要求编号，编号规则为“客户号+年月日（如20210101）+三位编号（如001）"},{"kind":"paragraph","text":"3、签约材料填写的日期需与系统操作日期相符"},{"kind":"paragraph","text":"4、确认客户已签订《中国银行股份有限公司银企对账协议》且自动附属功能已生效，确保客户后续开立的对公结构性存款账户按协议约定对账。确认已完成客户的非金融账户涉税信息尽职调查工作，执行“8201200对公客户信息查询及维护”交易检查确认”居民涉税标识“栏位为”2：“已声明”，以免影响对公结构性存款产品正常起息。"},{"kind":"paragraph","text":"5、复核人员应加强对销售协议、权益须知、产品说明书、授权书等材料中公司名称、日期、编号、印章等要素的审核，确保签约材料随网店当日会计传票保管。（需扫描件发起条线人员上传省行指定ftp网址）"},{"kind":"paragraph","text":"入口交易：60640客户签约结构性存款查询"},{"kind":"paragraph","text":"二、结构性存款认购审核材料 1、《中国银行公司客户结构性存款产品风险揭示书》（预留印鉴、法定代表人签章）"},{"kind":"paragraph","text":"2、《中国银行公司客户结构性存款产品认购委托书》（应为系统打印，不得手写）（预留印鉴、法定代表人签章）"},{"kind":"paragraph","text":"3、法定代表人/负责人证件复印件（需进行联网核查）；非法定代表人/负责人亲自办理的，需提供法定代表人/负责人证件复印件、授权书及代办人证件原件，并留存代办人证件复印件。"},{"kind":"paragraph","text":"、"},{"kind":"paragraph","text":"交易码G06016,（远程材料：440、联网核查、结构性存款（机构客户）业务授权书、中国银行公司客户结构性存款产品风险揭示书、中国银行公司客户结构性存款产品认购委托书、选中购买的产品需要截屏","shape":true},{"kind":"paragraph","text":"操作流程注意事项：\n1.注意产品的可用额度。\n2.认购委托书、风险揭示书验印、认购委托书金额超过50万（含）双人验印，认购委托书核印要体现金额。\n3．账号、账户名称、金额、发售计划编号与委托书一致\n4.通过PIDM系统对出具证件原件的单位有权人证件进行联网核查，并将核查结果打印在证件复印件上。\n5.风险揭示书客户确认栏需客户手工填写。","shape":true},{"kind":"paragraph","text":"全套认购材料（含交易回单第一联）一同扫描传入FT\nT+2日，通过系统查询确认已扣款起息后向客户出具结构性存款产品证实书","shape":true}]},{"title":"3.5.2理财类存款","children":[],"blocks":[{"kind":"paragraph","text":"一.所需材料"},{"kind":"paragraph","text":"① 公章及预留印鉴章"},{"kind":"paragraph","text":"② 法人身份证复印件一份（加盖公章）"},{"kind":"paragraph","text":"③ 经办人身份证原件及复印件一份（加盖公章）"},{"kind":"paragraph","text":"④ 营业执照复印件一份（加盖公章）"},{"kind":"paragraph","text":"填写单据："},{"kind":"paragraph","text":"① 机构客户/代销机构客户理财申请单"},{"kind":"paragraph","text":"② 机构客户/代销机构客户理财产品协议"},{"kind":"paragraph","text":"③ 机构客户/代销机构客户投资者权益须知"},{"kind":"paragraph","text":"④ 法人身份证复印件、代办人身份证复印件、理财产品业务授权书及反洗钱尽职调查材料（如有代办人）法人签章授权确认"},{"kind":"paragraph","text":"填单图样："},{"kind":"paragraph","text":"","images":["image110.png","image111.png","image112.png","image113.png"]},{"kind":"paragraph","text":"操作流程注意事项：\n后台事中查反洗钱名单(营业执照、法人身份证、经办人身份证)","shape":true},{"kind":"paragraph","text":"二.操作流程"},{"kind":"paragraph","text":"集约交易："},{"kind":"paragraph","text":"发起业务：8214202代销对公理财签约”交易发起，勾选“理财产品投资协议签署”或“代销资管产品协议签署”（可同时勾选）。如为代办，则“是否代办”栏位勾选“是”。"},{"kind":"paragraph","text":"点击“添加比对附件”按钮，选择正确的比对附件。业务提交时，系统将自动校验被查询账户的证件信息与“比对附件”是否一致。如不一致，系统报错并控制无法提交。"},{"kind":"paragraph","text":"影像扫描。点击扫描，法人本人办理时，选择模板“中国银行股份有限公司代理销售理财公司机构客户理财产品申请单”；授权他人办理时，选择模板“中国银行股份有限公司代理销售理财公司机构客户理财产品申请单”+“单位结算账户相关业务授权书”。点击“扫描仪获取”扫描业务凭证，点击“上传&提交”，业务发起成功。"},{"kind":"paragraph","text":"","images":["image114.png"]},{"kind":"paragraph","text":"交易集约运营组件处理完成后，选择8214016待打印业务信息，点击“打印详情”，选择待打印业务，点击打印，业务处理完成。"},{"kind":"paragraph","text":"操作流程注意事项：\n1.申请书上无法取得法人签字，使用私章的话，要法人签章授权确认书。\n2.法人签章授权确认书加盖公章和法人章。\n3.机构客户/代销客户理财申请单上预留印鉴和公章都要盖，缺一不可(同一个章盖一种即可)要双人验印!!!\n4.机构客户/代销机构客户理财产品协议→首页加盖公章和法人章，骑缝加盖公章。\n5.机构客户/代销机构客户投资者权益须知→首页加盖公章和法人章，骑缝加盖公章\n6.单位结算账户相关业务授权书加盖公章和法人章\n7.代销理财签约完，所有结算账户均可购买，无需再新增账号。","shape":true},{"kind":"paragraph","text":"三.业务完结注意事项"},{"kind":"paragraph","text":"1.如若要在网银上购买理财，须同时在网银上开通“中银理财”功能。操作按网银开通产品功能办理!"},{"kind":"paragraph","text":"2.灵活版网银开通“中银理财”,要设置产品限额，需要后台维护"}]}],"blocks":[]}],"blocks":[]}],"blocks":[]}],"blocks":[{"kind":"paragraph","text":"","images":["image1.jpeg"]}]}});
